/**
 * ספר בראשית - פשט מודרני, נהיר ועכשווי בלשון בני אדם
 * כולל את כל 12 פרשות חומש בראשית וכל 1,533 הפסוקים (פרקים א - נ)
 */
window.PeshatBereshit = {
  "1_1": "בתחילת בריאת העולם, ברא אלוהים את השמיים ואת הארץ.",
  "1_2": "והארץ הייתה ריקה ושוממת, חושך כיסה את פני המים העמוקים, ורוח אלוהים נשבה על פני המים.",
  "1_3": "אמר אלוהים: 'יהיה אור', ומיד נוצר האור.",
  "1_4": "ראה אלוהים שהאור טוב, והבדיל בין האור לבין החושך.",
  "1_5": "קרא אלוהים לאור 'יום', ולחושך קרא 'לילה'. חלף הערב והגיע הבוקר – זה היה היום הראשון.",
  "1_6": "אמר אלוהים: 'יהיה רקיע בתוך המים שיבדיל בין מים למים'.",
  "1_7": "עשה אלוהים את הרקיע והבדיל בין המים שתחת הרקיע לבין המים שמעל הרקיע, וכך אכן קרה.",
  "1_8": "קרא אלוהים לרקיע 'שמיים'. חלף הערב והגיע הבוקר – זה היה היום השני.",
  "1_9": "אמר אלוהים: 'ייאספו המים שתחת השמיים למקום אחד ותיראה היבשה', וכך אכן קרה.",
  "1_10": "קרא אלוהים ליבשה 'ארץ', ולאוסף המים קרא 'ימים', וראה אלוהים שהדבר טוב.",
  "1_11": "אמר אלוהים: 'תוציא הארץ צמחים: עשבים המצמיחים זרעים, ועצי פרי שעושים פרי לפי מינם עם זרעים בתוכם', וכך קרה.",
  "1_12": "הוציאה הארץ עשבים שמצמיחים זרעים לפי מינם, ועצים שמניבים פרי עם זרעים לפי מינם, וראה אלוהים שזה טוב.",
  "1_13": "חלף הערב והגיע הבוקר – זה היה היום השלישי.",
  "1_14": "אמר אלוהים: 'יהיו מאורות בשמיים להבדיל בין היום ובין הלילה, וישמשו לאותות, לעונות השנה, לימים ולשנים'.",
  "1_15": "ויהיו מאורות ברקיע השמיים כדי להאיר על הארץ, וכך אכן קרה.",
  "1_16": "עשה אלוהים את שני המאורות הגדולים: השמש (המאור הגדול) לשלוט ביום, והירח (המאור הקטן) לשלוט בלילה, וכן את הכוכבים.",
  "1_17": "הציב אותם אלוהים ברקיע השמיים כדי להאיר על הארץ.",
  "1_18": "ולמשול ביום ובלילה ולהבדיל בין האור לבין החושך, וראה אלוהים שזה טוב.",
  "1_19": "חלף הערב והגיע הבוקר – זה היה היום הרביעי.",
  "1_20": "אמר אלוהים: 'יתמלאו המים ביצורים חיים שורצים, ועופות יעופפו מעל הארץ על פני השמיים'.",
  "1_21": "ברא אלוהים את התנינים הענקיים ואת כל היצורים החיים הרוחשים במים למיניהם, ואת כל העופות בעלי הכנף למיניהם, וראה שזה טוב.",
  "1_22": "בירך אותם אלוהים ואמר: 'פרו והתרבו, מלאו את המים בימים, והעופות יתרבו על הארץ'.",
  "1_23": "חלף הערב והגיע הבוקר – זה היה היום החמישי.",
  "1_24": "אמר אלוהים: 'תוציא הארץ יצורים חיים למיניהם: בהמות, שרצים וחיות בר למיניהם', וכך אכן קרה.",
  "1_25": "עשה אלוהים את חיות הבר לפי מיניהן, את הבהמות למיניהן ואת כל שרצי האדמה למיניהם, וראה אלוהים שזה טוב.",
  "1_26": "אמר אלוהים: 'נעשה אדם בדמותנו ובצלמנו, והם ישלטו בדגי הים, בעופות השמיים, בבהמות, בכל הארץ ובכל השרצים הזוחלים על האדמה'.",
  "1_27": "ברא אלוהים את האדם בצלמו הרוחני, בצלם אלוהים ברא אותו; זכר ונקבה ברא אותם.",
  "1_28": "בירך אותם אלוהים ואמר להם: 'פרו והתרבו, מלאו את הארץ ושלטו בה, ורדו בדגי הים, בעופות השמיים ובכל חיה הזוחלת על הארץ'.",
  "1_29": "אמר אלוהים: 'הנה נתתי לכם את כל העשבים שמצמיחים זרע על פני כל הארץ, ואת כל העצים שיש בהם פרי עם זרע – הם יהיו לכם למאכל'.",
  "1_30": "ולכל חיות הארץ, עופות השמיים וכל שרצי האדמה שיש בהם רוח חיים, נתתי את כל העשב הירוק למאכל, וכך היה.",
  "1_31": "ראה אלוהים את כל מה שעשה, והנה הדבר מושלם וטוב מאוד. חלף הערב והגיע הבוקר – יום השישי.",
  "2_1": "כך הושלמה בריאת השמיים והארץ וכל צבאם (כל ברואיהם).",
  "2_2": "ביום השביעי השלים אלוהים את מלאכתו אשר עשה, ושבת ביום השביעי מכל המלאכה שיצר.",
  "2_3": "בירך אלוהים את יום השבת וקידש אותו, כי בו נח מכל מלאכת הבריאה אשר ברא לעשות.",
  "2_4": "אלו תולדות השמיים והארץ בעת היבראם, ביום שבו עשה ה' אלוהים ארץ ושמיים.",
  "2_5": "כל שיח ועשב השדה עדיין לא צמחו בארץ, משום שה' אלוהים לא המטיר גשם על הארץ, ולא היה אדם שיעבוד את האדמה.",
  "2_6": "אדים לחים עלו מן האדמה והשקו את כל פני האדמה.",
  "2_7": "יצר ה' אלוהים את האדם מעפר מן האדמה, ונפח באפיו נשמת חיים, וכך הפך האדם ליצור חי בעל תבונה ודיבור.",
  "2_8": "נטע ה' אלוהים גן בעדן במזרח, ושם שם את האדם אשר יצר.",
  "2_9": "הצמיח ה' אלוהים מן האדמה כל עץ נעים למראה וטוב למאכל, וכן את עץ החיים בתוך הגן, ואת עץ הדעת טוב ורע.",
  "2_10": "נהר יצא מעדן להשקות את הגן, ומשם התפצל לארבעה נהרות ראשיים.",
  "2_11": "שם הנהר הראשון פישון, הוא המקיף את כל ארץ החווילה ששם מצוי הזהב.",
  "2_12": "וזהב אותה ארץ הוא משובח ביותר, ושם מצויים גם הבוֹדֵלַח (אבן בדולח/בושם יקר) ואבן השוהם.",
  "2_13": "שם הנהר השני גיחון, והוא מקיף את כל ארץ כוש.",
  "2_14": "שם הנהר השלישי חידקל, הזורם מזרחית לאשור, והנהר הרביעי הוא נהר פרת.",
  "2_15": "לקח ה' אלוהים את האדם והניח אותו בגן עדן, כדי שיעבוד את הגן וישמור עליו.",
  "2_16": "ציווה ה' אלוהים על האדם לאמור: מכל עצי הגן אתה רשאי וחופשי לאכול.",
  "2_17": "אבל מעץ הדעת טוב ורע לא תאכל ממנו, כי ביום שתאכל ממנו – תהיה חייב מיתה ותהיה בן מוות.",
  "2_18": "אמר ה' אלוהים: לא טוב שהאדם יהיה לבדו, אעשה לו עזר כנגדו (בת זוג שתתאים לו ותסייע לו).",
  "2_19": "יצר ה' אלוהים מן האדמה את כל חיות השדה ועופות השמיים, והביאם אל האדם לראות כיצד יקרא להם, וכל שם שקרא האדם ליצור החי – זה היה שמו.",
  "2_20": "קרא האדם שמות לכל הבהמות, לעופות השמיים ולכל חיות השדה, אך לאדם עצמו לא מצא עזר שתתאים לו.",
  "2_21": "הפיל ה' אלוהים תרדמה עמוקה על האדם והוא ישן, לקח אחת מצלעותיו וסגר בבשר במקומה.",
  "2_22": "בנה ה' אלוהים את הצלע שלקח מן האדם לאישה, והביא אותה אל האדם.",
  "2_23": "אמר האדם בהתרגשות: הפעם הזאת היא עצם מעצמותיי ובשר מבשרי! לזאת ייקרא 'אישה' כי מאיש נלקחה זו.",
  "2_24": "על כן יעזוב איש את אביו ואת אמו ויידבק באשתו, והיו שניהם לגוף אחד ולנפש אחת.",
  "2_25": "שניהם היו ערומים, האדם ואשתו, ולא התביישו בכך (כי היו בתמימות גמורה לפני החטא).",
  "3_1": "הנחש היה ערמומי מכל חיות השדה שעשה ה' אלוהים, ואמר אל האישה: 'האם באמת אמר אלוהים שלא תאכלו מכל עץ הגן?'",
  "3_2": "אמרה האישה אל הנחש: 'מפירות עצי הגן מותר לנו לאכול'.",
  "3_3": "'אך מפרי העץ שבתוך הגן אמר אלוהים: אל תאכלו ממנו ואל תיגעו בו, פן תמותו'.",
  "3_4": "אמר הנחש אל האישה: 'אינכם עתידים למות כלל!'",
  "3_5": "'אלא שאלוהים יודע שביום שתאכלו ממנו ייפקחו עיניכם, ותהיו כמו אלוהים יודעי טוב ורע'.",
  "3_6": "ראתה האישה כי העץ טוב למאכל, מושך את העיניים ונחמד כדי להחכים, לקחה מפריו ואכלה, ונתנה גם לבעלה שהיה עמה, והוא אכל.",
  "3_7": "נפקחו עיני שניהם והבינו שהם ערומים, תפרו יחד עלי תאנה ועשו לעצמם חגורות לכיסוי גופם.",
  "3_8": "שמעו את קולו של ה' אלוהים מתהלך בגן לרוח היום (לפנות ערב), והתחבאו האדם ואשתו מפני ה' אלוהים בין עצי הגן.",
  "3_9": "קרא ה' אלוהים אל האדם ואמר לו: 'איפה אתה?'",
  "3_10": "השיב האדם: 'את קולך שמעתי בגן, ופחדתי כי ערום אנוכי, ולכן התחבאתי'.",
  "3_11": "אמר לו ה': 'מי אמר לך שאתה ערום? האם אכלת מן העץ אשר ציוויתי עליך שלא לאכול ממנו?'",
  "3_12": "אמר האדם: 'האישה אשר נתת לצידי – היא נתנה לי מן העץ, ואכלתי'.",
  "3_13": "אמר ה' אלוהים לאישה: 'מה זה עשית?' אמרה האישה: 'הנחש הטעה ופיתה אותי, ואכלתי'.",
  "3_14": "אמר ה' אלוהים אל הנחש: 'בגלל שעשית זאת, ארור תהיה מכל הבהמות ומכל חיות השדה, על גחונך תזחל ועפר תאכל כל ימי חייך'.",
  "3_15": "'ואיבה אשים בינך ובין האישה, ובין צאצאיך לצאצאיה; הוא יכה אותך בראש, ואתה תכיש אותו בעקב'.",
  "3_16": "אל האישה אמר: 'ארבה מאוד את צער הריונך, בעצב תלדי בנים, אל אישך תהיה תשוקתך והוא ימשול בך'.",
  "3_17": "ולאדם אמר: 'בגלל ששמעת לקול אשתך ואכלת מן העץ אשר ציוויתיך לא לאכול ממנו, ארורה תהיה האדמה בגללך, בעמל ויגיעה תאכל ממנה כל ימי חייך'.",
  "3_18": "'קוצים ודרדרים תצמיח לך האדמה, ותאכל את עשב השדה במקום פירות גן עדן'.",
  "3_19": "'בזיעת אפיך תאכל לחם עד שתשוב אל האדמה שממנה נלקחת, כי עפר אתה ואל עפר תשוב'.",
  "3_20": "קרא האדם את שם אשתו 'חוה', כי היא הייתה אם כל אדם חי.",
  "3_21": "עשה ה' אלוהים לאדם ולאשתו בגדי עור והלביש אותם בכבוד.",
  "3_22": "אמר ה' אלוהים: 'הנה האדם נהיה יחיד ומבדיל בעצמו בין טוב לרע, וכעת יש חשש שישלח ידו וייקח גם מעץ החיים, יאכל ממנו ויחיה לנצח במצבו החוטא'.",
  "3_23": "שילח ה' אלוהים את האדם מגן עדן, כדי לעבוד את האדמה שממנה לוקח.",
  "3_24": "גירש את האדם, והציב ממזרח לגן עדן את הכרובים (מלאכים) ואת להט החרב המתהפכת, כדי לשמור על הדרך לעץ החיים.",
  "4_1": "האדם ידע (התחבר באישות) את חוה אשתו, היא הרתה וילדה את קין, ואמרה: 'קניתי ויצרתי איש בעזרת ה''.",
  "4_2": "הוסיפה ללדת את אחיו את הבל; הבל הפך לרועה צאן, ואילו קין היה עובד אדמה (חקלאי).",
  "4_3": "לאחר זמן מה, הביא קין ממבחר פרי האדמה מנחה לה'.",
  "4_4": "והבל הביא גם הוא מבכורות צאנו ומן השמנים והמובחרים שבהם; פנה ה' ברצון אל הבל ואל מנחתו.",
  "4_5": "אך אל קין ואל מנחתו לא שעה (לא קיבל ברצון), וחרה הדבר לקין מאוד ופניו נפלו מעצב ומכעס.",
  "4_6": "אמר ה' אל קין: 'למה חרה לך ולמה נפלו פניך?'",
  "4_7": "'הלוא אם תיטיב מעשיך תתקבל ותתנשא, ואם לא תיטיב מעשיך – לפתח הלב רובץ החטא ויצר הרע, ואליך תאוותו להכשילך, אך אתה מסוגל לשלוט בו'.",
  "4_8": "דיבר קין אל הבל אחיו, ובהיותם יחד בשדה קם קין על הבל אחיו והרג אותו.",
  "4_9": "אמר ה' אל קין: 'איפה הבל אחיך?' אמר קין בהתחמקות: 'אינני יודע, האם אני השומר של אחי?'",
  "4_10": "אמר ה': 'מה עשית! קול דמי אחיך צועקים אליי מן האדמה!'",
  "4_11": "'וכעת ארור תהיה מן האדמה אשר פצתה את פיה לקבל את דמי אחיך מידך'.",
  "4_12": "'כאשר תעבוד את האדמה היא לא תוסיף לתת לך את כוחה ויבולה, נודד וגולה תהיה בארץ ללא מנוח'.",
  "4_13": "אמר קין אל ה': 'גדול עוווני מנשוא (חטאי כבד מלהכיל, או: האם עונשי כבד מדי לסליחה?)'.",
  "4_14": "'הנה גירשת אותי היום מעל פני האדמה ומפניך איסתר, אהיה נע ונד בארץ, וכל מי שימצא אותי יהרוג אותי'.",
  "4_15": "אמר לו ה': 'לכן, כל מי שיהרוג את קין יינקם שבעתיים', ושם ה' לקין אות מגן כדי שלא יכה אותו כל המוצא אותו.",
  "4_16": "יצא קין מלפני ה', והתיישב בארץ נוד ממזרח לעדן.",
  "4_17": "ידע קין את אשתו, והיא הרתה וילדה את חנוך; קין בנה עיר וקרא את שם העיר על שם בנו חנוך.",
  "4_18": "לחנוך נולד עירד, עירד הוליד את מחויאל, מחויאל הוליד את מתושאל, ומתושאל הוליד את למך.",
  "4_19": "לקח לו למך שתי נשים: שם האחת עדה, ושם השנייה צילה.",
  "4_20": "עדה ילדה את יבל, הוא היה אביהם של יושבי אוהלים ורועי מקנה.",
  "4_21": "שם אחיו יובל, הוא היה הממציא והאב של כל המנגנים בכינור ובעוגב (כלי פריטה ונשיפה).",
  "4_22": "וצילה ילדה גם היא את תובל קין, חרש ומלטש כל כלי נחושת וברזל, ואחות תובל קין הייתה נעמה.",
  "4_23": "אמר למך לנשותיו עדה וצילה: 'שמעו קולי נשי למך והקשיבו לאמרתי: האם איש הרגתי בגלל פצעי וילד בגלל חבורתי?'",
  "4_24": "'אם שבעתיים יוקם קין על הריגת הבל, הרי למך שלא הרג בזדון יוקם שבעים ושבעה'.",
  "4_25": "ידע אדם שוב את אשתו וילדה בן, וקראה את שמו 'שת', באומרה: 'כי שת ונתן לי אלוהים זרע אחר במקום הבל שהרגו קין'.",
  "4_26": "וגם לשת נולד בן, והוא קרא את שמו 'אנוש'; אז החלו בני האדם להתפלל ולקרוא בשם ה' (או שהחלו לחלל את שם ה' בעבודה זרה).",
  "5_1": "זה ספר תולדות האדם: ביום שברא אלוהים את האדם, בדמות אלוהים עשה אותו.",
  "5_2": "זכר ונקבה ברא אותם, בירך אותם וקרא את שמם 'אדם' ביום שנבראו.",
  "5_3": "חי אדם מאה ושלושים שנה, והוליד בן בדמותו ובצלמו, וקרא את שמו שת.",
  "5_4": "היו ימי אדם לאחר שהוליד את שת שמונה מאות שנה, והוליד בנים ובנות.",
  "5_5": "כל ימי חיי אדם שחי היו תשע מאות ושלושים שנה, ואז נפטר.",
  "5_6": "חי שת מאה וחמש שנים, והוליד את אנוש.",
  "5_7": "חי שת אחרי שהוליד את אנוש שמונה מאות ושבע שנים, והוליד בנים ובנות.",
  "5_8": "כל ימי שת היו תשע מאות ושתים עשרה שנה, ואז נפטר.",
  "5_9": "חי אנוש תשעים שנה, והוליד את קינן.",
  "5_10": "חי אנוש אחרי שהוליד את קינן שמונה מאות וחמש עשרה שנה, והוליד בנים ובנות.",
  "5_11": "כל ימי אנוש היו תשע מאות וחמש שנים, ואז נפטר.",
  "5_12": "חי קינן שבעים שנה, והוליד את מהללאל.",
  "5_13": "חי קינן אחרי שהוליד את מהללאל שמונה מאות וארבעים שנה, והוליד בנים ובנות.",
  "5_14": "כל ימי קינן היו תשע מאות ועשר שנים, ואז נפטר.",
  "5_15": "חי מהללאל שישים וחמש שנה, והוליד את ירד.",
  "5_16": "חי מהללאל אחרי שהוליד את ירד שמונה מאות ושלושים שנה, והוליד בנים ובנות.",
  "5_17": "כל ימי מהללאל היו שמונה מאות ותשעים וחמש שנה, ואז נפטר.",
  "5_18": "חי ירד מאה שישים ושתיים שנה, והוליד את חנוך.",
  "5_19": "חי ירד אחרי שהוליד את חנוך שמונה מאות שנה, והוליד בנים ובנות.",
  "5_20": "כל ימי ירד היו תשע מאות שישים ושתיים שנה, ואז נפטר.",
  "5_21": "חי חנוך שישים וחמש שנה, והוליד את מתושלח.",
  "5_22": "התהלך חנוך בדרכי האלוהים אחרי שהוליד את מתושלח שלוש מאות שנה, והוליד בנים ובנות.",
  "5_23": "היו כל ימי חנוך שלוש מאות שישים וחמש שנה.",
  "5_24": "התהלך חנוך עם האלוהים בצדקות, ואיננו עוד בעולם הזה כי לקח אותו אלוהים חיים אליו.",
  "5_25": "חי מתושלח מאה שמונים ושבע שנה, והוליד את למך.",
  "5_26": "חי מתושלח אחרי שהוליד את למך שבע מאות שמונים ושתיים שנה, והוליד בנים ובנות.",
  "5_27": "היו כל ימי מתושלח תשע מאות שישים ותשע שנה (האדם שחי הכי הרבה שנים), ואז נפטר.",
  "5_28": "חי למך מאה שמונים ושתיים שנה, והוליד בן.",
  "5_29": "קרא את שמו 'נח' באומרו: 'זה ינחם אותנו ממעשינו ומעמל ידינו מן האדמה אשר קילל ה''.",
  "5_30": "חי למך אחרי שהוליד את נח חמש מאות תשעים וחמש שנה, והוליד בנים ובנות.",
  "5_31": "היו כל ימי למך שבע מאות שבעים ושבע שנה, ואז נפטר.",
  "5_32": "נח היה בן חמש מאות שנה, והוליד נח את שם, את חם ואת יפת.",
  "6_1": "כאשר החלו בני האדם להתרבות על פני האדמה, ונולדו להם בנות.",
  "6_2": "ראו בני השופטים והשרים (או בני האלוהים) את בנות האדם כי יפות הן, ולקחו להם נשים מכל מי שבחרו בכפייה.",
  "6_3": "אמר ה': 'לא תדון ולא תישאר רוחי באדם לעולם בשל היותו בשר בלבד, ויהיו ימי הארכת אפו מאה ועשרים שנה לתשובה'.",
  "6_4": "הנפילים (ענקים ואנשי שררה) היו בארץ בימים ההם וגם לאחר מכן, כאשר באו בני השרים אל בנות האדם וילדו להם, הם היו הגיבורים המפורסמים מאז ומעולם.",
  "6_5": "ראה ה' כי רבתה רעת האדם בארץ, וכל יצר ורצון מחשבות לבו הוא רק רע בכל יום.",
  "6_6": "התעצב והתנחם ה' על כך שיצר את האדם בארץ, והתעצב אל לבו על השחתתם.",
  "6_7": "אמר ה': 'אמחה את האדם אשר בראתי מעל פני האדמה, מאדם ועד בהמה, עד שרץ ועד עוף השמיים, כי ניחמתי על שעשיתים'.",
  "6_8": "אך נח מצא חן וחסד בעיני ה'.",
  "6_9": "אלה תולדות ומעשי נח: נח היה איש צדיק ותמים בדורותיו המושחתים, בדרכי ה' התהלך נח.",
  "6_10": "הוליד נח שלושה בנים: את שם, את חם ואת יפת.",
  "6_11": "והארץ נשחתה לפני האלוהים במעשי תועבה, והתמלאה הארץ חמס וגזל.",
  "6_12": "ראה אלוהים את הארץ והנה נשחתה, כי כל בשר (אדם וחי) השחית את דרכו הטבעית על הארץ.",
  "6_13": "אמר אלוהים לנח: 'קץ כל בשר בא לפניי כי נתמלאה הארץ גזל וחמס מפניהם, והנני משחית אותם יחד עם הארץ'.",
  "6_14": "'עשה לך תיבה מעצי גופר (עץ עמיד למים), תעשה בתיבה תאים וחדרים, ותצפה אותה בזפת מבית ומחוץ למניעת חדירת מים'.",
  "6_15": "'וכך תעשה את מידותיה: שלוש מאות אמות אורך התיבה, חמישים אמה רוחבה, ושלושים אמה גובהה'.",
  "6_16": "'חלון צוהר תעשה להאיר את התיבה, ותסיים אותו באמה מלמעלה, פתח התיבה תשים בצדה, ותבנה בה קומה תחתונה, שנייה ושלישית'.",
  "6_17": "'ואני, הנני מביא מבול של מים על הארץ להשחית כל בשר שיש בו רוח חיים מתחת לשמיים, כל אשר בארץ יגווע וימות'.",
  "6_18": "'ואקים את בריתי איתך, ובאת אל התיבה אתה, בניך, אשתך ונשי בניך איתך'.",
  "6_19": "'ומכל היצורים החיים מכל בשר, שניים מכל מין תביא אל התיבה להחיות איתך – זכר ונקבה יהיו'.",
  "6_20": "'מהעופות למיניהם, מהבהמות למיניהן ומכל שרצי האדמה למיניהם, שניים מכל מין יבואו אליך כדי להישאר בחיים'.",
  "6_21": "'ואתה קח לך מכל מאכל שנאכל ואסוף אליך, ויהיה לך ולהם למזון'.",
  "6_22": "עשה נח ככל אשר ציווה אותו אלוהים, בדיוק כך עשה.",
  "7_1": "אמר ה' אל נח: 'בוא אתה וכל בני ביתך אל התיבה, כי אותך ראיתי צדיק לפניי בדור הזה'.",
  "7_2": "'מכל הבהמה הטהורה תיקח לך שבעה שבעה (שבעה זוגות), איש וזוגתו, ומן הבהמה אשר איננה טהורה – שניים, איש וזוגתו'.",
  "7_3": "'גם מעופות השמיים שבעה שבעה, זכר ונקבה, כדי להשאיר זרע חיים על פני כל הארץ'.",
  "7_4": "'כי בעוד שבעה ימים אמטיר גשם על הארץ במשך ארבעים יום וארבעים לילה, ואמחה את כל היקום אשר עשיתי מעל פני האדמה'.",
  "7_5": "עשה נח ככל אשר ציווה אותו ה'.",
  "7_6": "ונח היה בן שש מאות שנה כאשר המבול של המים ירד על הארץ.",
  "7_7": "בא נח ובניו, אשתו ונשי בניו איתו אל התיבה, כדי להינצל ממי המבול.",
  "7_8": "מן הבהמה הטהורה, ומן הבהמה שאינה טהורה, ומן העופות, וכל אשר רוחש על האדמה.",
  "7_9": "שניים שניים באו אל נח אל התיבה, זכר ונקבה, כפי שציווה אלוהים את נח.",
  "7_10": "לאחר שבעת הימים, מי המבול החלו לרדת על הארץ.",
  "7_11": "בשנת שש מאות לחיי נח, בחודש השני בשבעה עשר יום לחודש, ביום הזה נבקעו כל מעיינות התהום הגדול וארובות השמיים נפתחו.",
  "7_12": "הגשם העז ניתך על הארץ ארבעים יום וארבעים לילה.",
  "7_13": "בעצם היום הזה באו נח, ושם וחם ויפת בני נח, ואשת נח ושלוש נשי בניו איתם אל תוך התיבה.",
  "7_14": "הם וכל החיות למיניהן, כל הבהמות למיניהן, כל השרצים הרוחשים על הארץ למיניהם, וכל העופות למיניהם, כל ציפור וכל בעל כנף.",
  "7_15": "באו אל נח אל התיבה שניים שניים מכל בשר אשר בו רוח חיים.",
  "7_16": "והבאים זכר ונקבה מכל בשר באו כאשר ציווה אותו אלוהים, וסגר ה' את דלת התיבה בעדו.",
  "7_17": "היה המבול ארבעים יום על הארץ, גאו המים ונשאו את התיבה והיא התרוממה מעל הארץ.",
  "7_18": "התגברו המים והתרבו מאוד על הארץ, והתיבה שטה על פני המים.",
  "7_19": "המים גברו מאוד מאוד על הארץ, וכיסו את כל ההרים הגבוהים אשר תחת כל השמיים.",
  "7_20": "חמש עשרה אמות מעל ראשי ההרים גברו המים, וההרים כוסו לחלוטין.",
  "7_21": "גווע ומת כל בשר הרוחש על הארץ: בעופות, בבהמות, בחיות, בכל השרצים השורצים על הארץ וכל בני האדם.",
  "7_22": "כל אשר נשמת רוח חיים באפיו, מכל אשר ביבשה החרבה – מת.",
  "7_23": "נמחה כל היקום החי אשר על פני האדמה, מאדם ועד בהמה, שרצים ועופות השמיים נמחו מן הארץ, ונשאר רק נח ואשר איתו בתיבה.",
  "7_24": "גברו המים על פני הארץ מאה וחמישים יום.",
  "8_1": "זכר אלוהים ברחמים את נח ואת כל החיות ואת כל הבהמות אשר איתו בתיבה, והעביר אלוהים רוח מייבשת על הארץ ושככו המים.",
  "8_2": "נסכרו ונסגרו מעיינות התהום וארובות השמיים, ונכלא הגשם מן השמיים.",
  "8_3": "שבו המים ונסוגו מעל הארץ בהדרגה, וחסרו המים בסיום מאה וחמישים יום.",
  "8_4": "נחה התיבה בחודש השביעי, בשבעה עשר יום לחודש, על הרי אררט.",
  "8_5": "המים הלכו וחסרו בהדרגה עד החודש העשירי; בחודש העשירי באחד לחודש נראו ראשי ההרים.",
  "8_6": "בסוף ארבעים יום מאז שנראו ראשי ההרים, פתח נח את חלון התיבה אשר עשה.",
  "8_7": "שילח את העורב, והוא יצא הלוך ושוב עד שהתייבשו המים מעל הארץ.",
  "8_8": "שילח מאיתו את היונה, לראות האם קלו והתמעטו המים מעל פני האדמה.",
  "8_9": "לא מצאה היונה מקום מנוחה לכף רגלה ושבה אליו אל התיבה כי המים עוד כיסו את פני כל הארץ, הושיט ידו, לקח אותה והכניסה אליו אל התיבה.",
  "8_10": "המתין עוד שבעת ימים נוספים, ושוב שילח את היונה מן התיבה.",
  "8_11": "באה אליו היונה לעת ערב והנה עלה זית טרי תלוש בפיה, וכך ידע נח כי קלו המים מעל הארץ.",
  "8_12": "המתין עוד שבעת ימים נוספים ושילח את היונה, והיא לא שבה אליו עוד (כי מצאה מנוחה ביבשה).",
  "8_13": "בשנת שש מאות ואחת לחיי נח, בראשון לחודש הראשון, יבשו המים מעל הארץ; הסיר נח את מכסה התיבה וראה שהנה חרבו פני האדמה.",
  "8_14": "ובחודש השני, בעשרים ושבעה יום לחודש, יבשה הארץ לחלוטין.",
  "8_15": "דיבר אלוהים אל נח לאמור:",
  "8_16": "'צא מן התיבה, אתה ואשתך, בניך ונשי בניך איתך'.",
  "8_17": "'כל חיה מכל בשר אשר איתך: בעופות, בבהמות ובכל השרצים הזוחלים על הארץ – הוצא איתך, ויתרבו בארץ, יפרו וירבו עליה'.",
  "8_18": "יצא נח, ובניו, אשתו ונשי בניו איתו.",
  "8_19": "כל החיות, כל השרצים, כל העופות וכל הרוחש על הארץ יצאו למשפחותיהם מן התיבה.",
  "8_20": "בנה נח מזבח לה', לקח מכל הבהמות הטהורות ומכל העופות הטהורים, והעלה קורבנות עולה על המזבח.",
  "8_21": "הריח ה' את ריח הניחוח הנרצה, ואמר ה' בלבו: 'לא אוסיף עוד לקלל את האדמה בעבור האדם, כי יצר לב האדם רע מנעוריו, ולא אוסיף עוד להכות את כל החי כפי שעשיתי'.",
  "8_22": "'כל ימי עמידת הארץ: זריעה וקציר, קור וחום, קיץ וחורף, יום ולילה – לא ישבתו'.",
  "9_1": "בירך אלוהים את נח ואת בניו ואמר להם: 'פרו והתרבו ומלאו את הארץ'.",
  "9_2": "'מוראכם ופחדכם יהיה על כל חיית הארץ ועל כל עוף השמיים, בכל אשר רוחשת האדמה ובכל דגי הים – בידכם הם נמסרו'.",
  "9_3": "'כל רמש אשר הוא חי יהיה לכם למאכל (הותר בשר לראשונה), כפי שנתתי בעבר את עשב השדה הירוק נתתי לכם כעת את הכל'.",
  "9_4": "'אך בשר בעוד נפשו ודמו בו – לא תאכלו (איסור אבר מן החי ואכילת דם)'.",
  "9_5": "'ואולם את דמכם לנפשותיכם אדרוש: מיד כל חיה שתהרוג אדם אדרוש את דמו, ומיד האדם שירצח את אחיו אדרוש את נפש האדם'.",
  "9_6": "'השופך דם האדם – על ידי בית דין של אדם יישפך דמו, כי בצלם אלוהים עשה את האדם'.",
  "9_7": "'ואתם פרו והתרבו, שרצו בארץ והתרבו בה'.",
  "9_8": "אמר אלוהים אל נח ואל בניו איתו לאמור:",
  "9_9": "'ואני, הנני מקים את בריתי הנצחית איתכם ועם צאצאיכם אחריכם'.",
  "9_10": "'ועם כל נפש חיה אשר איתכם: בעופות, בבהמות ובכל חיות הארץ איתכם, מכל יוצאי התיבה לכל חיית הארץ'.",
  "9_11": "'והקמתי את בריתי איתכם: לא ייכרת עוד כל בשר ממי מבול, ולא יהיה עוד מבול לשחת את הארץ'.",
  "9_12": "אמר אלוהים: 'זהו אות הברית אשר אני נותן ביני וביניכם ובין כל נפש חיה אשר איתכם, לדורות עולם'.",
  "9_13": "'את קשתי בענן נתתי, והייתה לאות ברית ביני ובין הארץ'.",
  "9_14": "'והיה כאשר אביא עננים על הארץ, ותיראה הקשת בענן'.",
  "9_15": "'ואזכור את בריתי אשר ביני וביניכם ובין כל נפש חיה בכל בשר, ולא יהיו עוד המים למבול להשחית כל בשר'.",
  "9_16": "'ותהיה הקשת בענן וראיתיה, לזכור ברית עולם בין אלוהים ובין כל נפש חיה בכל בשר אשר על הארץ'.",
  "9_17": "אמר אלוהים אל נח: 'זאת אות הברית אשר הקמתי ביני ובין כל בשר אשר על הארץ'.",
  "9_18": "בני נח אשר יצאו מן התיבה היו שם, חם ויפת; וחם הוא אבי כנען.",
  "9_19": "שלושת אלה הם בני נח, ומאלה נפוצו בני האדם בכל חלקי הארץ.",
  "9_20": "החל נח להיות איש אדמה, ונטע כרם ענבים.",
  "9_21": "שתה מן היין והשתכר, והתערטל מגילוי גופו בתוך אוהלו.",
  "9_22": "ראה חם אבי כנען את ערוות אביו (ולא כיסהו), והלך וסיפר לשני אחיו בחוץ בלעג.",
  "9_23": "לקחו שם ויפת שמלה ושמו על כתפי שניהם, הלכו אחורנית וכיסו את ערוות אביהם, ופניהם היו מופנים לאחור וכך לא ראו את ערוות אביהם.",
  "9_24": "הקיץ נח מיינו, וידע את אשר עשה לו בנו הצעיר.",
  "9_25": "אמר: 'ארור כנען (זרע חם שחטא), עבד עבדים יהיה לאחיו'.",
  "9_26": "ואמר: 'ברוך ה' אלוהי שם, ויהי כנען עבד למו (לשם)'.",
  "9_27": "'ירחיב אלוהים ליפת וישכון באוהלי שם (בבתי המדרש והמקדש), ויהי כנען עבד למו'.",
  "9_28": "חי נח אחרי המבול שלוש מאות וחמישים שנה.",
  "9_29": "היו כל ימי נח תשע מאות וחמישים שנה, ואז נפטר.",
  "10_1": "אלה תולדות בני נח: שם, חם ויפת, ונולדו להם בנים אחרי המבול.",
  "10_2": "בני יפת: גומר, מגוג, מדי, יוון, תובל, משך ותירס.",
  "10_3": "ובני גומר: אשכנז, ריפת ותוגרמה.",
  "10_4": "ובני יוון: אלישה, תרשיש, כיתים ודודנים.",
  "10_5": "מאלה נפרדו איי העמים בארצותיהם, כל איש לפי לשונו, למשפחותיהם בגוייהם.",
  "10_6": "ובני חם: כוש, מצרים, פוט וכנען.",
  "10_7": "ובני כוש: סבא, חווילה, סבתה, רעמה וסבתכא; ובני רעמה: שבא ודדן.",
  "10_8": "וכוש הוליד את נמרוד; הוא החל להיות גיבור ציד ועריץ בארץ.",
  "10_9": "הוא היה גיבור ציד מורד לפני ה', על כן ייאמר הפתגם: 'כנמרוד גיבור ציד לפני ה''.",
  "10_10": "ראשית ממלכתו הייתה בבל, וארך, ואכד, וכלנה בארץ שנער.",
  "10_11": "מן הארץ ההיא יצא לאשור ובנה את נינווה, את רחובות עיר ואת כלח.",
  "10_12": "ואת רסן בין נינווה ובין כלח, היא העיר הגדולה.",
  "10_13": "ומצרים הוליד את לודים, את ענמים, את להבים ואת נפתוחים.",
  "10_14": "ואת פתרוסים, ואת כסלוחים אשר מהם יצאו פלשתים, ואת כפתורים.",
  "10_15": "וכנען הוליד את צידון בכורו ואת חת.",
  "10_16": "ואת היבוסי, את האמורי ואת הגרגשי.",
  "10_17": "ואת החיווי, את הערקי ואת הסיני.",
  "10_18": "ואת הארוודי, את הצמרי ואת החמתי, ואחר כך נפוצו משפחות הכנעני.",
  "10_19": "גבול הכנעני היה מצידון דרך גרר עד עזה, ועד סדום, עמורה, אדמה וצבועים עד לשע.",
  "10_20": "אלה בני חם לפי משפחותיהם, לשונותיהם, בארצותיהם ובגוייהם.",
  "10_21": "נולדו ילדים גם לשם, אבי כל בני עבר (העברים), אחיו הגדול של יפת.",
  "10_22": "בני שם: עילם, אשור, ארפכשד, לוד וארם.",
  "10_23": "ובני ארם: עוץ, חול, גתר ומש.",
  "10_24": "וארפכשד הוליד את שלח, ושלח הוליד את עבר.",
  "10_25": "ולעבר נולדו שני בנים: שם האחד פלג כי בימיו נפלגה ונחלקה הארץ (דור הפלגה), ושם אחיו יקטן.",
  "10_26": "ויקטן הוליד את אלמודד, את שלף, את חצרמוות ואת ירח.",
  "10_27": "ואת הדורם, את אוזל ואת דקלה.",
  "10_28": "ואת עובל, את אבימאל ואת שבא.",
  "10_29": "ואת אופיר, את חווילה ואת יובב; כל אלה הם בני יקטן.",
  "10_30": "מקום מושבם היה ממשא עד בואכה ספרה הר הקדם במזרח.",
  "10_31": "אלה בני שם לפי משפחותיהם, לשונותיהם, בארצותיהם לגוייהם.",
  "10_32": "אלה משפחות בני נח לפי תולדותיהם בגוייהם, ומאלה נפרדו והתפזרו העמים בארץ אחרי המבול.",
  "11_1": "כל תושבי הארץ דיברו אז שפה אחת (לשון הקודש) והיו להם דברים מאוחדים.",
  "11_2": "כאשר נדדו ממזרח, מצאו בקעה רחבה בארץ שנער והתיישבו שם.",
  "11_3": "אמרו איש אל רעהו: 'הבה נלבן לבנים ונשרוף אותן באש היטב', והיו להם הלבנים כאבן והחימר שימש להם כמלט.",
  "11_4": "אמרו: 'הבה נבנה לנו עיר ומגדל שראשו מגיע לשמיים, ונעשה לנו שם ותהילה, כדי שלא נתפזר על פני כל הארץ'.",
  "11_5": "ירד ה' להשגיח ולראות את העיר ואת המגדל אשר בנו בני האדם.",
  "11_6": "אמר ה': 'הנה עם אחד ושפה אחת לכולם, וזה מה שהחלו לעשות; כעת לא ייבצר ולא יימנע מהם כל מזימה אשר יזמו לעשות'.",
  "11_7": "'הבה נרד ונבלבל שם את שפתם, כדי שאיש לא יבין את שפת חברו'.",
  "11_8": "הפיץ אותם ה' משם על פני כל הארץ, והם חדלו מלבנות את העיר.",
  "11_9": "על כן נקרא שמה 'בבל', כי שם בלבל ה' את שפת כל הארץ, ומשם הפיצם ה' על פני כל הארץ.",
  "11_10": "אלה תולדות שם: שם היה בן מאה שנה כשהוליד את ארפכשד, שנתיים לאחר המבול.",
  "11_11": "חי שם אחרי שהוליד את ארפכשד חמש מאות שנה, והוליד בנים ובנות.",
  "11_12": "חי ארפכשד שלושים וחמש שנה, והוליד את שלח.",
  "11_13": "חי ארפכשד אחרי שהוליד את שלח ארבע מאות ושלוש שנים, והוליד בנים ובנות.",
  "11_14": "חי שלח שלושים שנה, והוליד את עבר.",
  "11_15": "חי שלח אחרי שהוליד את עבר ארבע מאות ושלוש שנים, והוליד בנים ובנות.",
  "11_16": "חי עבר שלושים וארבע שנה, והוליד את פלג.",
  "11_17": "חי עבר אחרי שהוליד את פלג ארבע מאות ושלושים שנה, והוליד בנים ובנות.",
  "11_18": "חי פלג שלושים שנה, והוליד את רעו.",
  "11_19": "חי פלג אחרי שהוליד את רעו מאתיים ותשע שנים, והוליד בנים ובנות.",
  "11_20": "חי רעו שלושים ושתים שנה, והוליד את שרוג.",
  "11_21": "חי רעו אחרי שהוליד את שרוג מאתיים ושבע שנים, והוליד בנים ובנות.",
  "11_22": "חי שרוג שלושים שנה, והוליד את נחור.",
  "11_23": "חי שרוג אחרי שהוליד את נחור מאתיים שנה, והוליד בנים ובנות.",
  "11_24": "חי נחור עשרים ותשע שנה, והוליד את תרח.",
  "11_25": "חי נחור אחרי שהוליד את תרח מאה ותשע עשרה שנה, והוליד בנים ובנות.",
  "11_26": "חי תרח שבעים שנה, והוליד את אברם, את נחור ואת הרן.",
  "11_27": "ואלה תולדות תרח: תרח הוליד את אברם, את נחור ואת הרן, והרן הוליד את לוט.",
  "11_28": "מת הרן בחיי תרח אביו, בארץ מולדתו באור כשדים.",
  "11_29": "לקחו אברם ונחור להם נשים: שם אשת אברם שרי, ושם אשת נחור מלכה בת הרן, שהיה אבי מלכה ואבי יסכה.",
  "11_30": "שרי הייתה עקרה, לא היה לה ולד.",
  "11_31": "לקח תרח את אברם בנו, ואת לוט בן הרן נכדו, ואת שרי כלתו אשת אברם בנו, ויצאו איתם מאור כשדים ללכת לכיוון ארץ כנען, ובאו עד חרן והתיישבו שם.",
  "11_32": "היו ימי תרח מאתיים וחמש שנים, ומת תרח בחרן.",
  "12_1": "אמר ה' אל אברם: 'לך לך מארצך, ממולדתך ומבית אביך אל הארץ אשר אראך'.",
  "12_2": "'ואעשה אותך לעם גדול, אברך אותך ואגדל את שמך, ותהיה מקור לברכה'.",
  "12_3": "'ואברך את מברכיך, ואת המקלל אותך אארור, ויתברכו בך כל משפחות האדמה'.",
  "12_4": "הלך אברם כפי שדיבר אליו ה', והלך איתו לוט; ואברם היה בן שבעים וחמש שנה בצאתו מחרן.",
  "12_5": "לקח אברם את שרי אשתו, את לוט בן אחיו, את כל רכושם אשר צברו ואת הנפשות אשר עשו וקירבו לאמונה בחרן, ויצאו ללכת לארץ כנען ובאו אל ארץ כנען.",
  "12_6": "עבר אברם בארץ עד מקום שכם, עד אלון מורה, והכנעני ישב אז בארץ.",
  "12_7": "נראה ה' אל אברם ואמר: 'לזרעך אתן את הארץ הזאת', ובנה שם מזבח לה' שנראה אליו.",
  "12_8": "העתיק משם את אוהלו אל ההר ממזרח לבית אל, ונטע אוהלו כשבית אל ממערב והעי ממזרח, בנה שם מזבח לה' והתפלל בשם ה'.",
  "12_9": "המשיך אברם במסעו הלוך ונסוע לעבר אזור הנגב (דרומה).",
  "12_10": "היה רעב כבד בארץ, וירד אברם למצרים לגור שם זמנית כי כבד הרעב בארץ כנען.",
  "12_11": "כאשר התקרב להיכנס למצרים, אמר אל שרי אשתו: 'הנה ידעתי כי אישה יפת מראה את'.",
  "12_12": "'והיה כי יראו אותך המצרים, יאמרו זו אשתו, ויהרגו אותי ואותך ישאירו בחיים'.",
  "12_13": "'אנא אמרי שאת אחותי, כדי שייטב לי בעבורך ותישאר נפשי בחיים בזכותך'.",
  "12_14": "כאשר בא אברם למצרים, ראו המצרים את האישה כי יפה היא מאוד.",
  "12_15": "ראו אותה שרי פרעה ושיבחו אותה אל פרעה, והאישה נלקחה אל בית פרעה.",
  "12_16": "ולאברם היטיב פרעה בעבורה, וניתנו לו צאן, בקר, חמורים, עבדים, שפחות, אתונות וגמלים.",
  "12_17": "הכה ה' את פרעה ואת ביתו נגעים ומחלות גדולות בגלל שרי אשת אברם.",
  "12_18": "קרא פרעה לאברם ואמר: 'מה זה עשית לי? למה לא הגדת לי כי אשתך היא?'",
  "12_19": "'מדוע אמרת אחותי היא, וכמעט לקחתי אותה לי לאישה? כעת, הנה אשתך – קח אותה ולך!'.",
  "12_20": "ציווה עליו פרעה אנשים לשומרו, ושילחו אותו ואת אשתו ואת כל אשר לו לשלום.",
  "13_1": "עלה אברם ממצרים, הוא ואשתו וכל אשר לו, ולוט עמו, לעבר הנגב.",
  "13_2": "ואברם היה עשיר מאוד במקנה (צאן ובקר), בכסף ובזהב.",
  "13_3": "הלך במסעותיו מן הנגב ועד בית אל, עד המקום שבו היה אוהלו בתחילה, בין בית אל ובין העי.",
  "13_4": "אל מקום המזבח אשר עשה שם בראשונה, וקרא שם אברם בשם ה'.",
  "13_5": "וגם ללוט שהלך עם אברם היו צאן, בקר ואוהלים רבים.",
  "13_6": "ולא יכלה הארץ לשאת אותם לשבת יחדיו, כי רכושם היה רב ולא יכלו לרעות באותו מקום.",
  "13_7": "היה ריב ומחלוקת בין רועי מקנה אברם ובין רועי מקנה לוט, והכנעני והפריזי ישבו אז בארץ.",
  "13_8": "אמר אברם אל לוט: 'אנא אל תהי מריבה ביני ובינך ובין רועי לרועיך, שהרי אנשים אחים אנחנו'.",
  "13_9": "'הלוא כל הארץ לפניך, אנא היפרד מעליי: אם תפנה לשמאל (צפון) אלך לימין (דרום), ואם תיטה לימין אפנה אני לשמאל'.",
  "13_10": "נשא לוט את עיניו וראה את כל כיכר הירדן כי כולה מושקית ומלאה מים, בטרם השחית ה' את סדום ואת עמורה, כגן ה' כארץ מצרים בואכה צוער.",
  "13_11": "בחר לו לוט את כל כיכר הירדן ונסע לוט מזרחה, ונפרדו איש מעל אחיו.",
  "13_12": "אברם ישב בארץ כנען, ולוט ישב בערי הכיכר והרחיב את אוהליו עד סדום.",
  "13_13": "ואנשי סדום היו רעים וחוטאים לה' מאוד במעשיהם ובאכזריותם.",
  "13_14": "וה' אמר אל אברם אחרי שנפרד לוט מעמו: 'שא נא עיניך וראה מן המקום אשר אתה שם, צפונה ונגבה (דרומה), קדמה (מזרחה) וימה (מערבה)'.",
  "13_15": "'כי את כל הארץ אשר אתה רואה – לך אתננה ולזרעך עד עולם'.",
  "13_16": "'ואשים את זרעך כעפר הארץ, עד שאם יוכל איש למנות את עפר הארץ – גם זרעך יימנה'.",
  "13_17": "'קום התהלך בארץ לאורכה ולרוחבה, כי לך אתננה'.",
  "13_18": "העתיק אברם את אוהלו, בא וישב באלוני ממרא אשר בחברון, ובנה שם מזבח לה'.",
  "14_1": "בימי אמרפל מלך שנער, אריוך מלך אלסר, כדרלעומר מלך עילם ותדעל מלך גוים.",
  "14_2": "עשו מלחמה עם ברע מלך סדום, ברשע מלך עמורה, שנאב מלך אדמה, שמאבר מלך צבויים, ומלך בלע היא צוער.",
  "14_3": "כל אלה התחברו אל עמק השדים, שהוא כיום ים המלח.",
  "14_4": "שתים עשרה שנה שירתו והעלו מס לכדרלעומר, ובשנה השלוש עשרה מרדו בו.",
  "14_5": "ובשנה הארבע עשרה בא כדרלעומר והמלכים אשר איתו, והכו את הרפאים בעשתרות קרניים, את הזוזים בהם, ואת האימים בשווה קריתיים.",
  "14_6": "ואת החורי בהררי שעיר, עד איל פארן אשר על המדבר.",
  "14_7": "שבו ובאו אל עין משפט היא קדש, והכו את כל שדה העמלקי וגם את האמורי היושב בחצצון תמר.",
  "14_8": "יצאו מלך סדום, מלך עמורה, מלך אדמה, מלך צבויים ומלך בלע היא צוער, וערכו איתם קרב בעמק השדים.",
  "14_9": "נגד כדרלעומר מלך עילם, תדעל מלך גוים, אמרפל מלך שנער ואריוך מלך אלסר – ארבעה מלכים מול החמישה.",
  "14_10": "ועמק השדים היה מלא בארות חמר (זפת דביקה), נסו מלכי סדום ועמורה ונפלו שם, והנשארים נמלטו אל ההר.",
  "14_11": "לקחו המנצחים את כל רכוש סדום ועמורה ואת כל מזונם, והלכו להם.",
  "14_12": "ולקחו בשבי גם את לוט בן אחי אברם ואת רכושו, והוא ישב בסדום, והלכו.",
  "14_13": "בא הפליט (עוג מלך הבשן שניצל) והגיד לאברם העברי, והוא שוכן באלוני ממרא האמורי, אחי אשכול ואחי ענר, שהיו בעלי ברית עם אברם.",
  "14_14": "שמע אברם כי נשבה קרובו (לוט), וחימש את חניכיו ילידי ביתו – שלוש מאות ושמונה עשר איש – ורדף אחריהם עד דן.",
  "14_15": "נחלק עליהם בלילה הוא ועבדיו והיכה אותם, ורדף אותם עד חובה שמצפון לדמשק.",
  "14_16": "השיב את כל הרכוש, וגם את לוט קרובו ואת רכושו השיב, וגם את הנשים ואת העם החזיר.",
  "14_17": "יצא מלך סדום לקראתו אחרי שובו מהכות את כדרלעומר ואת המלכים אשר איתו, אל עמק שווה הוא עמק המלך.",
  "14_18": "ומלכי צדק מלך שלם (ירושלים) הוציא לחם ויין, והוא היה כהן לאל עליון.",
  "14_19": "בירך אותו ואמר: 'ברוך אברם לאל עליון, קונה שמיים וארץ'.",
  "14_20": "'וברוך אל עליון אשר הסגיר את אויביך בידך', ונתן לו אברם מעשר מכל השלל.",
  "14_21": "אמר מלך סדום אל אברם: 'תן לי את הנפשות (האנשים), ואת הרכוש קח לעצמך כשלל'.",
  "14_22": "אמר אברם אל מלך סדום: 'הרימותי את ידי בשבועה אל ה' אל עליון, קונה שמיים וארץ'.",
  "14_23": "'אם מחוט ועד שרוך נעל אקח מכל אשר לך, כדי שלא תאמר: אני העשרתי את אברם'.",
  "14_24": "'בלעדיי – לא אקח דבר, רק את מה שאכלו הנערים, וחלק האנשים אשר הלכו איתי: ענר, אשכול וממרא, הם ייקחו את חלקם'.",
  "15_1": "אחר הדברים האלה היה דבר ה' אל אברם במראה הנבואה לאמור: 'אל תירא אברם, אנוכי מגן לך, שכרך יהיה רב מאוד'.",
  "15_2": "אמר אברם: 'ה' אלוהים, מה תיתן לי ואנוכי הולך ערירי (ללא בנים), ומנהל ביתי הוא דמשק אליעזר?'",
  "15_3": "אמר אברם: 'הנה לי לא נתת זרע, והנה בן ביתי (עבדי) יורש אותי'.",
  "15_4": "והנה דבר ה' אליו לאמור: 'לא יירש אותך זה, אלא מי שייצא ממעיך שלך – הוא יירש אותך'.",
  "15_5": "הוציא אותו החוצה ואמר: 'הבט נא השמיימה וספור את הכוכבים, אם תוכל לספור אותם', ואמר לו: 'כה יהיה זרעך'.",
  "15_6": "והאמין אברם בה', והחשיב לו ה' את האמונה הזאת לצדקה ולזכות גדולה.",
  "15_7": "אמר אליו: 'אני ה' אשר הוצאתיך מאור כשדים לתת לך את הארץ הזאת לרשת אותה'.",
  "15_8": "אמר אברם: 'ה' אלוהים, במה אדע כי אירשנה?'",
  "15_9": "אמר לו: 'קח לי עגלה משולשת (בת שלוש שנים), עז משולשת, איל משולש, תור וגוזל'.",
  "15_10": "לקח לו את כל אלה, חתך אותם בתווך ושם כל נתח מול רעהו, אך את הציפור לא חתך.",
  "15_11": "ירדו עופות דורסים על הפגרים, והבריח אותם אברם.",
  "15_12": "כאשר השמש עמדה לשקוע נפלה תרדמה עמוקה על אברם, והנה אימה וחשכה גדולה נופלת עליו.",
  "15_13": "אמר ה' לאברם: 'ידוע תדע כי גר יהיה זרעך בארץ לא להם, ויעבידו אותם ויענו אותם ארבע מאות שנה'.",
  "15_14": "'וגם את העם אשר יעבודו אשפוט אני בעונשים קשים, ואחרי כן ייצאו ברכוש גדול'.",
  "15_15": "'ואתה תבוא אל אבותיך בשלום, תיקבר בשיבה טובה'.",
  "15_16": "'ודור רביעי ישובו הנה לארץ כנען, כי לא שלם עדיין עוון האמורי להשמידם'.",
  "15_17": "כאשר שקעה השמש ונהייתה עלטה כבדה, והנה תנור עשן ולפיד אש אשר עבר בין הגזירים הללו (ברית בין הבתרים).",
  "15_18": "ביום ההוא כרת ה' עם אברם ברית לאמור: 'לזרעך נתתי את הארץ הזאת, מנהר מצרים ועד הנהר הגדול נהר פרת'.",
  "15_19": "'את ארץ הקיני, הקניזי ואת הקדמוני'.",
  "15_20": "'ואת החיתי, הפריזי ואת הרפאים'.",
  "15_21": "'ואת האמורי, הכנעני, הגרגשי ואת היבוסי'.",
  "16_1": "שרי אשת אברם לא ילדה לו בנים, והייתה לה שפחה מצרית ושמה הגר.",
  "16_2": "אמרה שרי אל אברם: 'הנה עצרני ה' מללדת, אנא בוא אל שפחתי, אולי אבנה ואזכה לבנים ממנה', ושמע אברם לקול שרי.",
  "16_3": "לקחה שרי אשת אברם את הגר המצרית שפחתה, מקץ עשר שנים לשבת אברם בארץ כנען, ונתנה אותה לאברם אישהּ לו לאישה.",
  "16_4": "בא אל הגר והיא הרתה; וכאשר ראתה כי הרתה, הקלה בכבודה של גבירתה שרי וזלזלה בה.",
  "16_5": "אמרה שרי אל אברם: 'העלבון והחמס שנעשה לי הוא באשמתך! אני נתתי שפחתי בחיקך, וכאשר ראתה כי הרתה קלתי בעיניה; ישפוט ה' ביני ובינך!'.",
  "16_6": "אמר אברם אל שרי: 'הנה שפחתך בידך, עשי לה כטוב בעיניך', ועינתה אותה שרי ביחס נוקשה, והגר ברחה מפניה.",
  "16_7": "מצא אותה מלאך ה' על עין המים במדבר, על המעיין בדרך שור (בדרך למצרים).",
  "16_8": "אמר המלאך: 'הגר שפחת שרי, מאיפה באת ולאן את הולכת?' אמרה: 'מפני שרי גבירתי אני בורחת'.",
  "16_9": "אמר לה מלאך ה': 'שובי אל גבירתך והתעני תחת ידיה'.",
  "16_10": "אמר לה מלאך ה': 'ארבה מאוד את זרעך, ולא ייספר מרוב'.",
  "16_11": "אמר לה מלאך ה': 'הנך הרה ויולדת בן, וקראת שמו ישמעאל, כי שמע ה' אל עונייך וצערך'.",
  "16_12": "'והוא יהיה פרא אדם (איש חופשי ופראי), ידו בכל ויד כל בו, ועל פני כל אחיו ישכון'.",
  "16_13": "קראה הגר את שם ה' הדובר אליה 'אתה אל רואי', כי אמרה: 'האם גם כאן ראיתי מלאך אחרי שראיתי בבית אברהם?'.",
  "16_14": "על כן נקרא הבאר 'באר לחי רואי', הנה היא בין קדש ובין ברד.",
  "16_15": "ילדה הגר לאברם בן, וקרא אברם את שם בנו אשר ילדה הגר ישמעאל.",
  "16_16": "ואברם היה בן שמונים ושש שנה כאשר ילדה הגר את ישמעאל לאברם.",
  "17_1": "כאשר היה אברם בן תשעים ותשע שנה, נראה אליו ה' ואמר לו: 'אני אל שדי, התהלך לפניי והיה שלם ותמים במעשיך'.",
  "17_2": "'ואתנה את בריתי ביני ובינך, וארבה אותך במאוד מאוד'.",
  "17_3": "נפל אברם על פניו ביראה, ודיבר איתו אלוהים לאמור:",
  "17_4": "'אני, הנה בריתי איתך, והיית לאב המון גויים'.",
  "17_5": "'ולא ייקרא עוד שמך אברם, והיה שמך אברהם, כי אב המון גויים נתתיך'.",
  "17_6": "'ופריתי אותך במאוד מאוד ונתתיך לעמים, ומלכים ממך ייצאו'.",
  "17_7": "'והקימותי את בריתי ביני ובינך ובין זרעך אחריך לדורותם לברית עולם, להיות לך לאלוהים ולזרעך אחריך'.",
  "17_8": "'ונתתי לך ולזרעך אחריך את ארץ מגוריך, את כל ארץ כנען לאחוזת עולם, והייתי להם לאלוהים'.",
  "17_9": "אמר אלוהים אל אברהם: 'ואתה את בריתי תשמור, אתה וזרעך אחריך לדורותם'.",
  "17_10": "'זאת בריתי אשר תשמרו ביני וביניכם ובין זרעך אחריך: יימול לכם כל זכר'.",
  "17_11": "'ונמלתם את בשר ערלתכם, והיה לאות ברית ביני וביניכם'.",
  "17_12": "'ובן שמונת ימים יימול לכם כל זכר לדורותיכם, יליד בית ומקנת כסף מכל בן נכר אשר לא מזרעך הוא'.",
  "17_13": "'הימול יימול יליד ביתך ומקנת כספך, והייתה בריתי בבשרכם לברית עולם'.",
  "17_14": "'וערל זכר אשר לא יימול את בשר ערלתו – ונכרתה הנפש ההיא מעמיה, את בריתי הפר'.",
  "17_15": "אמר אלוהים אל אברהם: 'שרי אשתך לא תקרא את שמה שרי, כי שרה שמה'.",
  "17_16": "'וברכתי אותה וגם נתתי ממנה לך בן, וברכתיה והייתה לגויים, מלכי עמים ממנה יהיו'.",
  "17_17": "נפל אברהם על פניו ושמח (או תמה), ואמר בלבו: 'האם לבן מאה שנה ייוולד ילד, ואם שרה בת תשעים שנה תלד?'.",
  "17_18": "אמר אברהם אל האלוהים: 'לו ישמעאל יחיה לפניך (שיזכה ללכת בדרכי ה')!'.",
  "17_19": "אמר אלוהים: 'אכן שרה אשתך יולדת לך בן, וקראת את שמו יצחק, והקימותי את בריתי איתו לברית עולם לזרעו אחריו'.",
  "17_20": "'ולגבי ישמעאל שמעתיך: הנה ברכתי אותו והפריתי אותו והרביתי אותו במאוד מאוד, שנים עשר נשיאים יוליד ונתתיו לגוי גדול'.",
  "17_21": "'ואת בריתי העיקרית אקים את יצחק, אשר תלד לך שרה למועד הזה בשנה הבאה'.",
  "17_22": "סיים לדבר איתו, ועלה אלוהים מעל אברהם.",
  "17_23": "לקח אברהם את ישמעאל בנו ואת כל ילידי ביתו ואת כל מקנת כספו, כל זכר באנשי בית אברהם, ומל את בשר ערלתם בעצם היום הזה כפי שדיבר איתו אלוהים.",
  "17_24": "ואברהם היה בן תשעים ותשע שנה בהימולו בשר ערלתו.",
  "17_25": "וישמעאל בנו היה בן שלוש עשרה שנה בהימולו את בשר ערלתו.",
  "17_26": "בעצם היום הזה נימול אברהם וישמעאל בנו.",
  "17_27": "וכל אנשי ביתו, ילידי בית ומקנת כסף מבן נכר, נימולו איתו.",
  "18_1": "נראה ה' אל אברהם באלוני ממרא (לבקרו ביום השלישי למילתו), והוא יושב בפתח האוהל כחום היום.",
  "18_2": "נשא עיניו וראה והנה שלושה אנשים (מלאכים בדמות אנשים) ניצבים מולו, ראה ורץ לקראתם מפתח האוהל והשתחווה ארצה.",
  "18_3": "אמר למלאך הראשי: 'אדוני, אם נא מצאתי חן בעיניך, אנא אל תעבור מעל עבדך'.",
  "18_4": "'ייקח נא מעט מים ורחצו רגליכם, והישענו תחת העץ'.",
  "18_5": "'ואקחה פת לחם וסעדו לבכם ואחר כך תעברו, כי על כן עברתם על עבדכם', ואמרו: 'כן תעשה כאשר דיברת'.",
  "18_6": "מיהר אברהם אל האוהל אל שרה ואמר: 'מהרי, לושי שלוש סאים קמח סולת משובח ועשי עוגות'.",
  "18_7": "ואל עדרי הבקר רץ אברהם, ולקח בן בקר רך וטוב ונתן אל הנער (ישמעאל) ומיהר להכין אותו.",
  "18_8": "לקח חמאה וחלב ואת בן הבקר אשר הכין, ושם לפניהם, והוא עומד עליהם תחת העץ לשרתם, והם אכלו (נראו כאוכלים).",
  "18_9": "אמרו אליו: 'איפה שרה אשתך?' ואמר: 'הנה באוהל בצניעות'.",
  "18_10": "אמר המלאך: 'שוב אשוב אליך כעת חיה בשנה הבאה, והנה בן לשרה אשתך', ושרה שומעת בפתח האוהל והוא מאחוריו.",
  "18_11": "ואברהם ושרה זקנים, באים בימים, פסק משרה אורח הנשים (הווסת הטבעי).",
  "18_12": "צחקה שרה בקרבה לאמור: 'אחרי שבלו איבריי האם תהיה לי עדנה (רעננות ללדת), ואדוני זקן?'.",
  "18_13": "אמר ה' אל אברהם: 'למה זה צחקה שרה לאמור: האף אמנם אלד ואני זקנתי?'.",
  "18_14": "'האם יפלא מה' דבר? למועד אשוב אליך כעת חיה ולשרה בן!'.",
  "18_15": "הכחישה שרה מפחדה ואמרה: 'לא צחקתי', ואמר לה: 'לא כי צחקת'.",
  "18_16": "קמו משם האנשים והשקיפו על פני סדום, ואברהם הלך איתם ללוותם.",
  "18_17": "וה' אמר: 'האם מכסה אני מאברהם את אשר אני עושה?'.",
  "18_18": "'ואברהם הרי יהיה לגוי גדול ועצום, ויתברכו בו כל גויי הארץ'.",
  "18_19": "'כי ידעתיו ואהבתיו, למען אשר יצווה את בניו ואת ביתו אחריו ושמרו דרך ה' לעשות צדקה ומשפט, למען הביא ה' על אברהם את אשר דיבר עליו'.",
  "18_20": "אמר ה': 'זעקת סדום ועמורה כי רבה, וחטאתם כי כבדה מאוד'.",
  "18_21": "'ארדה נא ואראה האם כצעקתה הבאה אליי עשו כליה, ואם לא – אדע'.",
  "18_22": "פנו משם האנשים והלכו לסדום, ואברהם עודנו עומד ומתפלל לפני ה'.",
  "18_23": "ניגש אברהם בתפילה ואמר: 'האם באמת תשמיד צדיק עם רשע?'.",
  "18_24": "'אולי יש חמישים צדיקים בתוך העיר, האם תשמיד ולא תישא ותסלח למקום למען חמישים הצדיקים אשר בקרבה?'.",
  "18_25": "'חלילה לך מעשות כדבר הזה להמית צדיק עם רשע והיה כצדיק כרשע, חלילה לך! השופט כל הארץ לא יעשה משפט?'.",
  "18_26": "אמר ה': 'אם אמצא בסדום חמישים צדיקים בתוך העיר – אסלח לכל המקום בעבורם'.",
  "18_27": "ענה אברהם ואמר: 'הנה נא הואלתי לדבר אל אדוני, ואנוכי עפר ואפר'.",
  "18_28": "'אולי יחסרו מחמישים הצדיקים חמישה (ויהיו 45), האם תשחית בגלל החמישה את כל העיר?' אמר: 'לא אשחית אם אמצא שם ארבעים וחמישה'.",
  "18_29": "הוסיף עוד לדבר אליו ואמר: 'אולי יימצאו שם ארבעים?' אמר: 'לא אעשה בעבור הארבעים'.",
  "18_30": "אמר: 'אנא אל יחר לאדוני ואדברה: אולי יימצאו שם שלושים?' אמר: 'לא אעשה אם אמצא שם שלושים'.",
  "18_31": "אמר: 'הנה נא הואלתי לדבר אל אדוני: אולי יימצאו שם עשרים?' אמר: 'לא אשחית בעבור העשרים'.",
  "18_32": "אמר: 'אל נא יחר לאדוני ואדברה רק הפעם הזאת: אולי יימצאו שם עשרה?' אמר ה': 'לא אשחית בעבור העשרה'.",
  "18_33": "הלך ה' כאשר כילה לדבר אל אברהם, ואברהם שב אל מקומו.",
  "19_1": "באו שני המלאכים לסדום לעת ערב ולוט יושב בשער סדום, ראה לוט וקם לקראתם והשתחווה אפים ארצה.",
  "19_2": "אמר: 'הנה נא אדוניי, סורו נא אל בית עבדכם ולינו ורחצו רגליכם, והשכמתם בבוקר והלכתם לדרככם', ואמרו: 'לא, כי ברחוב נלין'.",
  "19_3": "הפציר בהם מאוד, וסרו אליו ובאו אל ביתו; עשה להם משתה ומצות אפה, והם אכלו.",
  "19_4": "טרם ישכבו, ואנשי העיר אנשי סדום הקיפו את הבית, מנער ועד זקן, כל העם מכל קצה.",
  "19_5": "קראו אל לוט ואמרו לו: 'איפה האנשים אשר באו אליך הלילה? הוציאם אלינו ונדעה אותם (נפגע בהם בתועבה)'.",
  "19_6": "יצא אליהם לוט הפתחה, ואת הדלת סגר מאחוריו.",
  "19_7": "אמר: 'אנא אחיי אל תרעו'.",
  "19_8": "'הנה נא לי שתי בנות אשר לא ידעו איש, אוציא נא אותן אליכם ועשו להן כטוב בעיניכם, רק לאנשים האלה אל תעשו דבר כי באו בצל קורתי'.",
  "19_9": "אמרו לו: 'גש הלאה (התרחק)! האחד הזה בא לגור כאן וכבר שופט אותנו כשופט?! כעת נרע לך יותר מאשר להם!', ודחקו באיש בלוט מאוד וניגשו לשבור את הדלת.",
  "19_10": "שלחו האנשים (המלאכים) את ידם והכניסו את לוט אליהם הביתה, ואת הדלת סגרו.",
  "19_11": "ואת האנשים אשר בפתח הבית הכו בסנוורים מקטון ועד גדול, והתעייפו בניסיונם למצוא את הפתח.",
  "19_12": "אמרו האנשים אל לוט: 'מי עוד יש לך פה? חתן ובניך ובנותיך וכל אשר לך בעיר – הוצא מן המקום'.",
  "19_13": "'כי משחיתים אנחנו את המקום הזה, כי גדלה צעקתם את פני ה', וישלחנו ה' לשחתה'.",
  "19_14": "יצא לוט ודיבר אל חתניו לוקחי בנותיו ואמר: 'קומו צאו מן המקום הזה כי משחית ה' את העיר', והיה כמצחק ולועג בעיני חתניו.",
  "19_15": "וכאשר עלה השחר, האיצו המלאכים בלוט לאמור: 'קום קח את אשתך ואת שתי בנותיך הנמצאות פה, פן תיספה בעוון העיר'.",
  "19_16": "והתמהמה, והחזיקו האנשים בידו וביד אשתו וביד שתי בנותיו בחמלת ה' עליו, והוציאוהו והניחוהו מחוץ לעיר.",
  "19_17": "כאשר הוציאו אותם החוצה, אמר אחד המלאכים: 'הימלט על נפשך! אל תביט לאחוריך ואל תעמוד בכל רחבי הכיכר; הימלט אל ההר פן תיספה באסון'.",
  "19_18": "אמר לוט אליהם: 'אל נא אדוניי'.",
  "19_19": "'הנה נא מצא עבדך חן בעיניך ותגדל חסדך אשר עשית עימדי להחיות את נפשי, ואנוכי לא אוכל להימלט ההרה פן תדבקני הרעה ומותי'.",
  "19_20": "'הנה נא העיר הזאת קרובה לברוח שמה והיא קטנה, אמלטה נא שמה – הלוא מצער היא – ותחיה נפשי'.",
  "19_21": "אמר לו: 'הנה נשאתי פניך גם לדבר הזה, לבלתי הפוך את העיר אשר דיברת'.",
  "19_22": "'מהר הימלט שמה, כי לא אוכל לעשות דבר עד בואך שמה', על כן קרא שם העיר צוער.",
  "19_23": "השמש יצאה על הארץ, ולוט בא אל צוער.",
  "19_24": "וה' המטיר על סדום ועל עמורה גופרית ואש, מאת ה' מן השמיים.",
  "19_25": "והפך את הערים האלה ואת כל הכיכר ואת כל יושבי הערים וצמח האדמה.",
  "19_26": "הביטה אשתו מאחוריו בניגוד לציווי, והפכה לנציב מלח.",
  "19_27": "השכים אברהם בבוקר אל המקום אשר עמד שם את פני ה'.",
  "19_28": "השקיף על פני סדום ועמורה ועל פני כל ארץ הכיכר, וראה והנה עלה קיטור הארץ כקיטור כבשן האש.",
  "19_29": "כאשר השחית אלוהים את ערי הכיכר, זכר אלוהים את חסדו של אברהם, ושילח והציל את לוט מתוך ההפיכה כאשר הפך את הערים שבהן התגורר לוט.",
  "19_30": "לוט עלה מצוער והתיישב בהר יחד עם שתי בנותיו, כי פחד לגור בצוער; והוא התגורר במערה, הוא ושתי בנותיו.",
  "19_31": "אמרה הבכירה אל הצעירה: 'אבינו זקן, ואיש אין בארץ לבוא עלינו כדרך כל הארץ (חשבו שחרב כל העולם כבמבול)'.",
  "19_32": "'לכי נשקה את אבינו יין ונשכבה עמו, ונחיה זרע מאבינו'.",
  "19_33": "השקו את אביהן יין בלילה ההוא, ובאה הבכירה ושכבה עם אביה, והוא לא ידע בשכבה ובקומה.",
  "19_34": "למחרת אמרה הבכורה אל הצעירה: 'הנה שכבתי אמש עם אבינו; נשקה אותו יין גם הלילה, ובואי שכבי עמו כדי שנקים זרע וצאצאים מאבינו'.",
  "19_35": "השקו גם בלילה ההוא את אביהן יין, וקמה הצעירה ושכבה עמו, ולא ידע בשכבה ובקומה.",
  "19_36": "הרו שתי בנות לוט מאביהן.",
  "19_37": "ילדה הבכירה בן וקראה שמו מואב (מֵאָב), הוא אבי מואב עד היום.",
  "19_38": "והצעירה ילדה גם היא בן וקראה שמו בן עמי, הוא אבי בני עמון עד היום.",
  "20_1": "אברהם נסע משם לעבר חבל הנגב, והתיישב בין קדש לבין שור, והתגורר כגר בעיר גרר.",
  "20_2": "אמר אברהם אל שרה אשתו: 'אחותי היא', ושלח אבימלך מלך גרר ולקח את שרה.",
  "20_3": "בא אלוהים אל אבימלך בחלום הלילה ואמר לו: 'הנך מת על האישה אשר לקחת, והיא בעולת בעל (נשואה)'.",
  "20_4": "ואבימלך לא קרב אליה, ואמר: 'אדוני, האם גם גוי ועם צדיק תהרוג?'.",
  "20_5": "'הלוא הוא אמר לי אחותי היא, והיא גם היא אמרה אחי הוא; בתום לבבי ובניקיון כפיי עשיתי זאת!'.",
  "20_6": "אמר אליו האלוהים בחלום: 'גם אני ידעתי כי בתום לבבך עשית זאת, ואמנע גם אנוכי אותך מחטוא לי, על כן לא נתתיך לנגוע בה'.",
  "20_7": "'ועתה השב את אשת האיש כי נביא הוא ויתפלל בעדך וחיה, ואם אינך משיב – דע כי מות תמות אתה וכל אשר לך'.",
  "20_8": "השכים אבימלך בבוקר וקרא לכל עבדיו ודיבר את כל הדברים האלה באוזניהם, ויראו האנשים מאוד.",
  "20_9": "קרא אבימלך לאברהם ואמר לו: 'מה עשית לנו ומה חטאתי לך כי הבאת עליי ועל ממלכתי חטאה גדולה? מעשים אשר לא ייעשו עשית עמדי!'.",
  "20_10": "אמר אבימלך אל אברהם: 'מה ראית כי עשית את הדבר הזה?'.",
  "20_11": "אמר אברהם: 'כי אמרתי רק אין יראת אלוהים במקום הזה והרגוני על דבר אשתי'.",
  "20_12": "'וגם באמת אחותי בת אבי היא אך לא בת אמי (בת אחיו הרן), ותהי לי לאישה'.",
  "20_13": "'וכאשר הוליך אותי אלוהים בנדודים מבית אבי, אמרתי לה: זה החסד שתעשי עמי – בכל מקום שנגיע אליו, אמרי עליי: אחי הוא'.",
  "20_14": "לקח אבימלך צאן ובקר ועבדים ושפחות ונתן לאברהם, והשיב לו את שרה אשתו.",
  "20_15": "אמר אבימלך: 'הנה ארצי לפניך, בטוב בעיניך שב'.",
  "20_16": "ולשרה אמר: 'הנה נתתי אלף כסף לאחיך, הנה הוא לך כסות עיניים לכל אשר איתך ולכל, והוכחת בצדקתך'.",
  "20_17": "התפלל אברהם אל האלוהים, וריפא אלוהים את אבימלך ואת אשתו ואמהותיו וילדו.",
  "20_18": "כי עצור עצר ה' בעד כל רחם לבית אבימלך, על דבר שרה אשת אברהם.",
  "21_1": "וה' פקד את שרה כפי שאמר, ועשה ה' לשרה כאשר דיבר.",
  "21_2": "הרתה שרה וילדה לאברהם בן לזקוניו, למועד המדויק אשר דיבר איתו אלוהים.",
  "21_3": "קרא אברהם את שם בנו הנולד לו, אשר ילדה לו שרה – יצחק.",
  "21_4": "מל אברהם את יצחק בנו בהיותו בן שמונת ימים, כפי שציווה אותו אלוהים.",
  "21_5": "ואברהם היה בן מאה שנה כאשר נולד לו יצחק בנו.",
  "21_6": "אמרה שרה: 'צחוק ושמחה עשה לי אלוהים, כל השומע ישמח וירנן עמי'.",
  "21_7": "אמרה: 'מי היה מבשר לאברהם ששרה עוד תניק בנים? והנה ילדתי לו בן לזקוניו!'.",
  "21_8": "גדל הילד ונגמל מן היניקה, ועשה אברהם משתה גדול ביום שבו נגמל יצחק.",
  "21_9": "ראתה שרה את בן הגר המצרית אשר ילדה לאברהם כשהוא מצחק בלעג (או בחטאים).",
  "21_10": "אמרה לאברהם: 'גרש את האמה הזאת ואת בנה, כי לא יירש בן האמה הזאת עם בני, עם יצחק!'.",
  "21_11": "וירע הדבר מאוד בעיני אברהם, על אודות בנו ישמעאל.",
  "21_12": "אמר אלוהים אל אברהם: 'אל ירע בעיניך על הנער ועל אמתך, כל אשר תאמר אליך שרה שמע בקולה, כי ביצחק ייקרא לך זרע'.",
  "21_13": "'וגם את בן האמה לגוי אשימנו, כי זרעך הוא'.",
  "21_14": "השכים אברהם בבוקר ולקח לחם וחמת (נאד) מים ונתן אל הגר, שם על שכמה ואת הילד ושילחה, והיא הלכה ותעתה במדבר באר שבע.",
  "21_15": "כלו המים מן החמת, והשליכה את הילד תחת אחד השיחים.",
  "21_16": "הלכה וישבה לה מנגד במרחק כיריות קשת, כי אמרה: 'אל אראה במות הילד', וישבה מנגד ותישא את קולה ותבך.",
  "21_17": "שמע אלוהים את קול הנער, וקרא מלאך אלוהים אל הגר מן השמיים ואמר לה: 'מה לך הגר? אל תיראי, כי שמע אלוהים אל קול הנער באשר הוא שם'.",
  "21_18": "'קומי, שאי את הנער והחזיקי את ידך בו, כי לגוי גדול אשימנו'.",
  "21_19": "פקח אלוהים את עיניה ותרא באר מים, והלכה ומילאה את החמת מים והשקתה את הנער.",
  "21_20": "אלוהים ליווה את הנער והוא גדל, התיישב במדבר והפך ללוחם וצייד מיומן היורה בקשת.",
  "21_21": "ישב במדבר פארן, ולקחה לו אמו אישה מארץ מצרים.",
  "21_22": "באותה תקופה פנו אבימלך ופיכול שר צבאו אל אברהם ואמרו: 'אלוהים מלווה אותך ועוזר לך בכל מה שאתה עושה'.",
  "21_23": "'ועתה השבעה לי באלוהים הנה שלא תשקר לי ולניני ולנכדי; כחסד אשר עשיתי עמך תעשה עמדי ועם הארץ אשר גרת בה'.",
  "21_24": "אמר אברהם: 'אנוכי אשבע'.",
  "21_25": "והוכיח אברהם את אבימלך על אודות באר המים אשר גזלו עבדי אבימלך.",
  "21_26": "אמר אבימלך: 'לא ידעתי מי עשה את הדבר הזה, וגם אתה לא הגדת לי, וגם אנוכי לא שמעתי אלא היום'.",
  "21_27": "לקח אברהם צאן ובקר ונתן לאבימלך, וכרתו שניהם ברית.",
  "21_28": "הציב אברהם שבע כבשות צאן לבדן.",
  "21_29": "אמר אבימלך אל אברהם: 'מה הנה שבע כבשות האלה אשר הצבת לבדנה?'.",
  "21_30": "אמר: 'כי את שבע כבשות תיקח מידי, בעבור תהיה לי לעדה כי חפרתי את הבאר הזאת'.",
  "21_31": "על כן קרא למקום ההוא באר שבע, כי שם נשבעו שניהם.",
  "21_32": "כרתו ברית בבאר שבע, וקם אבימלך ופיכול שר צבאו ושבו אל ארץ פלשתים.",
  "21_33": "נטע אשל (פונדק ופרדס לאורחים) בבאר שבע, וקרא שם בשם ה' אל עולם.",
  "21_34": "וגר אברהם בארץ פלשתים ימים רבים.",
  "22_1": "לאחר האירועים האלה, העמיד אלוהים את אברהם במבחן אמוני גדול, וקרא אליו: 'אברהם!', והוא ענה: 'הנני, אני מוכן'.",
  "22_2": "אמר: 'קח נא את בנך, את יחידך אשר אהבת, את יצחק, ולך לך אל ארץ המוריה, והעלהו שם לעולה על אחד ההרים אשר אומר אליך'.",
  "22_3": "השכים אברהם בבוקר וחבש את חמורו, ולקח את שני נעריו איתו (ישמעאל ואליעזר) ואת יצחק בנו, ביקע עצי עולה וקם והלך אל המקום אשר אמר לו האלוהים.",
  "22_4": "ביום השלישי נשא אברהם את עיניו וראה את המקום (הר המוריה) מרחוק (ענן קשור על ההר).",
  "22_5": "אמר אברהם אל נעריו: 'שבו לכם פה עם החמור, ואני והנער נלכה עד כה, ונשתחווה ונשובה אליכם'.",
  "22_6": "לקח אברהם את עצי העולה ושם על יצחק בנו, ולקח בידו את האש ואת המאכלת (הסכין), והלכו שניהם יחדיו באותה כוונה.",
  "22_7": "יצחק פנה אל אברהם אביו ואמר: 'אבי!', והוא ענה: 'הנני בני, אני מקשיב'; שאל יצחק: 'הנה האש ועצי ההסקה, אך איפה השה שמיועד לעולה?'.",
  "22_8": "אמר אברהם: 'אלוהים יראה לו השה לעולה בני', והלכו שניהם יחדיו.",
  "22_9": "באו אל המקום אשר אמר לו האלוהים, ובנה שם אברהם את המזבח וערך את העצים, ועקד את יצחק בנו ושם אותו על המזבח ממעל לעצים.",
  "22_10": "שלח אברהם את ידו, ולקח את המאכלת לשחוט את בנו.",
  "22_11": "קרא אליו מלאך ה' מן השמיים ואמר: 'אברהם! אברהם!', והוא ענה: 'הנני'.",
  "22_12": "אמר: 'אל תשלח ידך אל הנער ואל תעש לו מאומה, כי עתה ידעתי כי ירא אלוהים אתה, ולא חשכת את בנך את יחידך ממני'.",
  "22_13": "נשא אברהם את עיניו וראה והנה איל אחר נאחז בסבך בקרניו, הלך אברהם ולקח את האיל והעלהו לעולה תחת בנו.",
  "22_14": "קרא אברהם שם המקום ההוא 'ה' יראה', אשר ייאמר היום: בהר ה' ייראה.",
  "22_15": "קרא מלאך ה' אל אברהם שנית מן השמיים.",
  "22_16": "אמר: 'בי נשבעתי נאום ה', כי יען אשר עשית את הדבר הזה ולא חשכת את בנך את יחידך'.",
  "22_17": "'כי ברך אברכך והרבה ארבה את זרעך ככוכבי השמיים וכחול אשר על שפת הים, ויירש זרעך את שער אויביו'.",
  "22_18": "'והתברכו בזרעך כל גויי הארץ, עקב אשר שמעת בקולי'.",
  "22_19": "אברהם שב אל נעריו הממתינים לו, והם קמו והלכו יחד לבאר שבע, ואברהם התיישב בבאר שבע.",
  "22_20": "לאחר הדברים הללו, הוגד ונמסר לאברהם: 'הנה גם מלכה ילדה בנים לנחור אחיך'.",
  "22_21": "את עוץ בכורו ואת בוז אחיו, ואת קמואל אבי ארם.",
  "22_22": "ואת כשד ואת חזו ואת פלדש ואת ידלף ואת בתואל.",
  "22_23": "ובתואל הוליד את רבקה; שמונה אלה ילדה מלכה לנחור אחי אברהם.",
  "22_24": "ופילגשו ושמה ראומה, וילדה גם היא את טבח ואת גחם ואת תחש ואת מעכה.",
  "23_1": "שרה חיה מאה עשרים ושבע שנים (127 שנים); אלה היו שנות חייה של שרה.",
  "23_2": "שרה נפטרה בקריית ארבע – שהיא חברון – בארץ כנען; אברהם הגיע לספוד לשרה ולבכות על מותה.",
  "23_3": "לאחר מכן קם אברהם מאבלו לצד אשתו המתה, ודיבר אל בני חת (תושבי חברון המקומיים) ואמר:",
  "23_4": "'אני גר ותושב זר בקרבכם; מכרו לי חלקת קבר בבעלותי ביניכם, כדי שאוכל לקבור את אשתי המתה'.",
  "23_5": "בני חת ענו לאברהם ואמרו לו בכבוד:",
  "23_6": "'שמע אותנו אדוננו: אתה מנהיג ונשיא נכבד מורם מעם בתוכנו! קבור את מתך במבחר קברותינו; איש מאיתנו לא ימנע ממך את חלקת קברו מלקבור את מתך'.",
  "23_7": "אברהם קם והשתחווה בהכרת תודה בפני אנשי המקום, בני חת.",
  "23_8": "הוא דיבר איתם ואמר: 'אם אתם אכן מסכימים בכל לב שאקבור כאן את אשתי, אנא הקשיבו לי ופנו עבורי אל עפרון בן צוחר'.",
  "23_9": "'שימכור לי את מערת המכפלה השייכת לו, הנמצאת בקצה שדהו; במחיר מלא ובכסף מלא שימכור לי אותה בתוככם לאחוזת קבר קבועה'.",
  "23_10": "ועפרון ישב אז בין בני חת במקום; עפרון החיתי ענה לאברהם בקול רם בנוכחות בני חת וכל הבאים בשער העיר:",
  "23_11": "'לא אדוני, הקשב לי: אני נותן לך את השדה במתנה, וגם את המערה שבתוכו אני מעניק לך; לנגד עיני בני עמי אני נותן לך אותה, קבור את מתך'.",
  "23_12": "אברהם השתחווה שוב לפני תושבי המקום.",
  "23_13": "הוא פנה לעפרון בנוכחות כולם ואמר: 'אך אם רק תסכים להקשיב לי – אני משלם כעת את מלוא ערכו של השדה בכסף; קח ממני את התשלום, ואז אקבור את מתי שם'.",
  "23_14": "עפרון ענה לאברהם ואמר לו:",
  "23_15": "'אדוני, הקשב לי: חלקת קרקע בשווי ארבע מאות שקלי כסף – מה היא כבר נחשבת ביני לבינך? קבור את מתך'.",
  "23_16": "אברהם הבין את רמיזתו של עפרון, שקל ומסר לו את הסכום שנקב בפני בני חת – ארבע מאות שקלי כסף מובחר וסחיר שעובר לסוחר.",
  "23_17": "כך עברה הקרקע של עפרון במכפלה שלפני ממרא – השדה, המערה שבו וכל העצים שבתוך גבולותיו מסביב – לבעלות מוחלטת,",
  "23_18": "ונקנתה על ידי אברהם כרכוש פרטי לעיני כל בני חת וכל הבאים בשער עירו.",
  "23_19": "לאחר הרכישה, קבר אברהם את שרה אשתו במערת שדה המכפלה שמול ממרא, היא חברון שבארץ כנען.",
  "23_20": "השדה והמערה שבו עברו רשמית מבני חת לבעלותו הבלעדית של אברהם כאחוזת קבר משפחתית.",
  "24_1": "אברהם כבר היה זקן ובא בימים, וה' בירך את אברהם בכל תחום.",
  "24_2": "אברהם אמר אל עבדו הבכיר ומנהל משק ביתו (אליעזר), שניהל את כל רכושו: 'הנח נא את ידך תחת ירכי (כשבועה חמורה)'.",
  "24_3": "'ואשביע אותך בה' אלוהי השמיים ואלוהי הארץ, שלא תיקח אישה לבני מבנות הכנענים שאני מתגורר בקרבם'.",
  "24_4": "'אלא תלך אל מולדתי ואל משפחתי בארם, ומשם תיקח אישה לבני ליצחק'.",
  "24_5": "שאל העבד: 'ומה אם האישה לא תסכים ללכת אחריי לארץ הזאת? האם עליי לקחת את בנך ולהחזיר אותו לארץ שממנה יצאת?'.",
  "24_6": "אברהם השיב לו בנחרצות: 'הישמר לך והיזהר מאוד שלא להחזיר את בני לשם!'",
  "24_7": "'ה' אלוהי השמיים שלקח אותי מבית אבי ומארץ מולדתי, והבטיח לי בשבועה: לזרעך אתן את הארץ הזאת – הוא ישלח את מלאכו לפניך ואתה תיקח אישה לבני משם'.",
  "24_8": "'ואם האישה לא תרצה ללכת אחריך – תהיה פטור לחלוטין משבועתי זו; רק אל תחזיר את בני לשם בשום אופן'.",
  "24_9": "העבד הניח את ידו תחת ירך אברהם אדוניו ונשבע לו על כך.",
  "24_10": "העבד לקח עשרה גמלים מתוך גמלי אדוניו, יחד עם מבחר מיטב המתנות והחפצים היקרים של אדוניו, ויצא לדרך אל ארם נהריים, אל עיר מגוריו של נחור.",
  "24_11": "הוא הוריד את הגמלים לברכיים ליד באר המים מחוץ לעיר לקראת ערב, בשעה שנשות העיר נוהגות לצאת לשאוב מים.",
  "24_12": "הוא התפלל ואמר: 'ה' אלוהי אדוני אברהם, אנא זמן לי היום הצלחה ועשה חסד עם אדוני אברהם'.",
  "24_13": "'הנה אני עומד כאן ליד מעיין המים, ובנות תושבי העיר יוצאות לשאוב מים'.",
  "24_14": "'והנערה שאומר אליה: הטי נא את כדך ואשתה מעט, והיא תשיב: שתה, וגם את גמליך אשקה – היא תהיה הנערה שייעדת לעבדך יצחק, ודרכה אדע שעשית חסד עם אדוני'.",
  "24_15": "עוד לפני שסיים את תפילתו בלבו, יצאה רבקה עם כד המים על כתפה; היא הייתה בתו של בתואל בן מלכה, אשת נחור אחי אברהם.",
  "24_16": "הנערה הייתה יפת תואר במיוחד, בתולה תמימה שאיש לא נגע בה; היא ירדה אל המעיין, מילאה את כדה ועלתה חזרה.",
  "24_17": "העבד רץ לקראתה ואמר: 'אנא, תני לי ללגום מעט מים מכדך'.",
  "24_18": "היא ענתה מיד בנועם: 'שתה אדוני', מיהרה והורידה את הכד אל ידה והשקתה אותו.",
  "24_19": "כאשר סיימה להשקותו, אמרה ביוזמתה: 'אשאב מים גם עבור כל גמליך עד שישתו די צורכם'.",
  "24_20": "היא מיהרה ושפכה את המים מכדה אל שוקת השתייה, רצה שוב ושוב אל הבאר לשאוב, והשקתה את כל עשרת גמליו.",
  "24_21": "האיש התבונן בה בהשתאות ובדממה, כדי לבחון האם ה' אכן הצליח את דרכו ושליחותו.",
  "24_22": "כאשר הגמלים סיימו לשתות, הוציא האיש נזם זהב במשקל בקע (מחצית השקל) ושני צמידי זהב במשקל עשרה שקלים לידיה.",
  "24_23": "הוא שאל אותה: 'בת מי את? הגידי לי בבקשה, והאם יש בבית אביך מקום עבורנו ללון הלילה?'.",
  "24_24": "היא ענתה לו: 'אני בתו של בתואל בן מלכה, שילדה לנחור'.",
  "24_25": "והוסיפה: 'יש אצלנו שפע של תבן ומספוא לגמלים, וגם מקום מרווח ללינה'.",
  "24_26": "האיש כרע על ברכיו והשתחווה בהתרגשות ובהודיה לה'.",
  "24_27": "הוא אמר: 'ברוך ה' אלוהי אדוני אברהם שלא הפסיק את חסדו ונאמנותו מאדוני; ה' הנחה אותי ישירות בדרך הנכונה אל בית משפחתו של אדוני'.",
  "24_28": "הנערה רצה לבית אמה וסיפרה את כל מה שקרה.",
  "24_29": "לרבקה היה אח ושמו לבן; לבן רץ מיד החוצה אל האיש שעמד ליד המעיין.",
  "24_30": "בראותו את נזם הזהב ואת הצמידים על ידי אחותו ובשומעו את דברי רבקה: 'כך אמר לי האיש', הוא ניגש אל האיש שעמד לצד הגמלים ליד המעיין.",
  "24_31": "לבן אמר לו: 'בוא היכנס, ברוך ה'! למה תעמוד בחוץ? פיניתי עבורך את הבית והכנתי מקום מסודר לגמלים'.",
  "24_32": "האיש נכנס לבית ופרק את המשא מעל הגמלים; לבן נתן תבן ומזון לגמלים ומים לרחיצת רגליו ורגלי האנשים שהתלוו אליו.",
  "24_33": "הגישו לפניו אוכל, אך הוא אמר: 'לא אטעם דבר עד שאספר את שליחותי ודבריי'; לבן אמר: 'דבר'.",
  "24_34": "הוא פתח ואמר: 'אני עבדו של אברהם'.",
  "24_35": "'ה' בירך את אדוני בשפע רב והוא הפך לאדם גדול ועשיר מאוד; ה' העניק לו צאן, בקר, כסף, זהב, עבדים, שפחות, גמלים וחמורים'.",
  "24_36": "'ושרה אשת אדוני ילדה לו בן בזקנותה, ואדוני העביר לו את כל רכושו'.",
  "24_37": "'אדוני השביע אותי ואמר: אל תיקח אישה לבני מבנות הכנענים שאני מתגורר בארצם'.",
  "24_38": "'אלא תלך אל בית אבי ואל משפחתי, ומשם תיקח אישה לבני'.",
  "24_39": "'שאלתי את אדוני: ומה אם האישה לא תסכים לבוא איתי?'",
  "24_40": "'והוא ענה לי: ה' אשר התהלכתי לפניו ישלח את מלאכו איתך ויצליח את דרכך, ואתה תיקח אישה לבני ממשפחתי ומבית אבי'.",
  "24_41": "'רק אם תגיע למשפחתי והם יסרבו לתת אותה – תהיה נקי ופטור משבועתי'.",
  "24_42": "'היום הגעתי אל עין המים והתפללתי: ה' אלוהי אדוני אברהם, אם ברצונך להצליח את הדרך שבה אני הולך'.",
  "24_43": "'הנה אני עומד ליד המעיין; והנערה שתצא לשאוב ואבקש ממנה מעט מים מכדה'.",
  "24_44": "'והיא תענה לי: שתה אתה, וגם לגמליך אשאב – היא תהיה האישה שה' הועיד לבן אדוני'.",
  "24_45": "'עוד בטרם סיימתי להרהר בכך בלבי, הנה יצאה רבקה עם כדה על כתפה, ירדה למעיין ושאבה מים; ביקשתי ממנה לשתות'.",
  "24_46": "'היא מיהרה להוריד את כדה ואמרה ברוחב לב: שתה, וגם את גמליך אשקה; שתיתי, והיא השקתה גם את הגמלים'.",
  "24_47": "'שאלתי אותה בת מי את, והיא ענתה: בתו של בתואל בן נחור ומלכה; ענדתי את הנזם על אפה ואת הצמידים על ידיה'.",
  "24_48": "'כרעתי ברך והודיתי לה' אלוהי אדוני אברהם שהנחה אותי ישירות בדרך הנכונה לקחת את בת אחי אדוני עבור בנו'.",
  "24_49": "'וכעת, אם אתם מתכוונים לנהוג בחסד ובנאמנות כלפי אדוני – אמרו לי; ואם לא – הגידו לי, ואדע לפנות לדרך אחרת, ימינה או שמאלה'.",
  "24_50": "לבן ובתואל ענו יחד ואמרו: 'העניין הזה יצא ישירות מאת ה', ואין ביכולתנו לומר דבר נגדו, לא לרע ולא לטוב'.",
  "24_51": "'הנה רבקה עומדת לפניך: קח אותה ולך, והיא תהיה אישה לבן אדונך כפי שה' קבע'.",
  "24_52": "כאשר עבד אברהם שמע את דבריהם, הוא השתחווה עד הקרקע לה' בהודיה עמוקה.",
  "24_53": "העבד הוציא תכשיטי כסף, תכשיטי זהב ובגדים מפוארים והעניק לרבקה, ונתן מתנות יקרות ערך לאחיה ולאמה.",
  "24_54": "הוא והאנשים שהיו עימו אכלו ושתו ולנו שם את הלילה; בבוקר קם העבד ואמר: 'שלחו אותי חזרה לאדוני'.",
  "24_55": "אחיה ואמה של רבקה ביקשו: 'תן לנערה להישאר איתנו עוד כמה ימים או עשרה חודשים, ולאחר מכן תלך'.",
  "24_56": "אך הוא הפציר בהם: 'אל תעכבו אותי, שהרי ה' הצליח את שליחותי; שלחו אותי ואלך לאדוני'.",
  "24_57": "הם אמרו: 'נקרא לנערה ונשמע את דעתה שלה'.",
  "24_58": "הם קראו לרבקה ושאלו אותה: 'האם את מוכנה ללכת עכשיו עם האיש הזה?', והיא השיבה בביטחון: 'אלך'.",
  "24_59": "הם ליוו ושילחו את רבקה אחותם יחד עם המינקת שלה, עם עבד אברהם ועם אנשיו.",
  "24_60": "הם בירכו את רבקה באהבה ואמרו לה: 'אחותנו, שתזכי להיות לאם של רבבות צאצאים, ושזרעך יגבר וינצח את שער אויביו'.",
  "24_61": "רבקה ונערותיה קמו, רכבו על הגמלים והלכו אחרי האיש; העבד לקח את רבקה ויצא לדרך.",
  "24_62": "ויצחק הגיע באותה עת מדרך באר לחי רואי, כיוון שהתגורר באזור הנגב.",
  "24_63": "יצחק יצא להתבודד ולהתפלל בשדה לקראת ערב; הוא נשא את עיניו וראה מרחוק שיירת גמלים מתקרבת.",
  "24_64": "רבקה נשאה את עיניה וראתה את יצחק, וירדה ביראת כבוד מעל הגמל.",
  "24_65": "היא שאלה את העבד: 'מי האיש הזה שצועד בשדה לקראתנו?', והעבד ענה: 'זהו אדוני'; היא לקחה את הצעיף והתכסתה בצניעות.",
  "24_66": "העבד סיפר ליצחק את כל השתלשלות האירועים והניסים שקרו.",
  "24_67": "יצחק הביא אותה אל אוהל שרה אמו, נשא את רבקה לאישה ואהב אותה מאוד; ובכך מצא יצחק נחמה לאחר פטירת אמו.",
  "25_1": "אברהם לקח אישה נוספת (הגר שחזרה) ושמה קטורה.",
  "25_2": "היא ילדה לו את זמרן, את יקשן, את מדן, את מדין, את ישבק ואת שוח.",
  "25_3": "ויקשן הוליד את שבא ואת דדן; ובני דדן התפתחו לשבטים: אשורים, לטושים ולאומים.",
  "25_4": "בני מדין היו: עיפה, עפר, חנוך, אבידע ואלדעה; כל אלה היו צאצאי קטורה.",
  "25_5": "אברהם העניק את כל רכושו ונחלתו העיקרית ליצחק בנו.",
  "25_6": "ולבני הפילגשים של אברהם הוא נתן מתנות כספיות, ושילח אותם מעל יצחק בנו בעודו חי מזרחה, אל ארצות המזרח.",
  "25_7": "אלה היו ימי שנות חייו של אברהם: מאה שבעים וחמש שנים (175 שנים).",
  "25_8": "אברהם גווע ונפטר בשיבה טובה, זקן ושבע ימים מרוצים, ונאסף אל אבותיו.",
  "25_9": "בניו יצחק וישמעאל קברו אותו במערת המכפלה, בשדה עפרון בן צוחר החיתי שמול ממרא.",
  "25_10": "באותו שדה שאברהם קנה מבני חת – שם נקברו אברהם ושרה אשתו.",
  "25_11": "לאחר מות אברהם בירך אלוהים את יצחק בנו, ויצחק התיישב סמוך לבאר לחי רואי.",
  "25_12": "ואלה תולדות משפחת ישמעאל בן אברהם, שילדה הגר המצרית שפחת שרה לאברהם.",
  "25_13": "אלה שמות בני ישמעאל לפי סדר תולדותיהם: בכור ישמעאל נביות, ואחריו קדר, אדבאל ומבשם.",
  "25_14": "משמע, דומה ומשא.",
  "25_15": "חדד, תימא, יטור, נפיש וקדמה.",
  "25_16": "אלה היו בני ישמעאל ואלה שמותיהם ביישוביהם ובמבצריהם – שנים עשר נשיאים לשנים עשר עמיהם.",
  "25_17": "ואלה שנות חיי ישמעאל: מאה שלושים ושבע שנים (137 שנים); הוא גווע, נפטר ונאסף אל עמיו.",
  "25_18": "צאצאיו התיישבו בשטח הנפרש מחווילה ועד שור שליד מצרים בכיוון אשור; הם שכנו בעוצמה על פני כל אחיהם.",
  "25_19": "ואלה תולדות משפחת יצחק בן אברהם: אברהם הוליד את יצחק.",
  "25_20": "יצחק היה בן ארבעים שנה כאשר נשא לאישה את רבקה, בתו של בתואל הארמי מפדן ארם ואחותו של לבן הארמי.",
  "25_21": "יצחק התפלל והעתיר לה' בנוכחות אשתו כי היא הייתה עקרה; ה' נענה לתפילתו, ורבקה אשתו הרתה.",
  "25_22": "העוברים נאבקו והתרוצצו בתוך בטנה, והיא אמרה מתוך כאב ותמיהה: 'אם זה כך, מדוע ייחלתי להריון הזה?'; והיא הלכה לדרוש את דבר ה' בנבואה.",
  "25_23": "ה' אמר לה בנבואה: 'שני עמים שונים נמצאים בבטנך, ושתי אומות מקרבך ייפרדו; אומה אחת תהיה חזקה מחברתה, והבכור ישתעבד לצעיר'.",
  "25_24": "כאשר הגיע מועד הלידה, התברר שאכן יש תאומים בבטנה.",
  "25_25": "התינוק הראשון יצא אדמוני, כולו מכוסה שיער כמו מעיל פרווה, וקראו את שמו עשו (על שם שנראה שלם ועשוי כבוגר).",
  "25_26": "לאחר מכן יצא אחיו כאשר ידו אוחזת בעקבו של עשו, וקראו את שמו יעקב; יצחק היה בן שישים שנה בעת לידתם.",
  "25_27": "הנערים גדלו: עשו הפך לאיש שדה מיומן בציד, ואילו יעקב היה איש תם ושקט, השוקד באוהלי הלימוד.",
  "25_28": "יצחק העדיף את עשו כי אהב לאכול מצידו, ואילו רבקה אהבה את יעקב.",
  "25_29": "יום אחד בישל יעקב נזיד עדשים אדומות; עשו חזר מן השדה כשהוא עייף ומותש לחלוטין מרעב.",
  "25_30": "עשו אמר אל יעקב: 'הלעיט אותי מהר מן התבשיל האדום הזה כי אני גמור מעייפות ורעב'; לכן נקרא שמו גם 'אדום'.",
  "25_31": "יעקב ענה לו: 'מכור לי עכשיו את זכות הבכורה שלך בתמורה'.",
  "25_32": "עשו אמר: 'הרי אני בסכנת חיים מתמדת בציד וקרוב למות, אז מה תועיל לי הבכורה?'.",
  "25_33": "יעקב אמר: 'הישבע לי עכשיו!'; עשו נשבע לו ומכר את בכורתו ליעקב.",
  "25_34": "אז נתן יעקב לעשו לחם ונזיד עדשים; הוא אכל, שתה, קם והלך לדרכו – ובכך הפגין עשו זלזול מוחלט בזכות הבכורה.",
  "26_1": "רעב כבד שרר בארץ, מלבד הרעב הראשון שהיה בימי אברהם; יצחק הלך אל אבימלך מלך פלשתים לגרר.",
  "26_2": "ה' נראה אליו ואמר: 'אל תרד למצרים; הישאר והתגורר בארץ אשר אומר אליך'.",
  "26_3": "'התגורר בארץ הזאת כגר ואהיה איתך ואברך אותך, כי לך ולצאצאיך אתן את כל הארצות הללו, ואקיים את השבועה שנשבעתי לאברהם אביך'.",
  "26_4": "'ארבה את צאצאיך ככוכבי השמיים, אתן להם את כל הארצות האלה, וכל עמי הארץ יתברכו בזרעך'.",
  "26_5": "'כל זה בזכות שאברהם שמע בקולי, ושמר את משמרתי: מצוותיי, חוקיי ותורותיי'.",
  "26_6": "יצחק נשאר להתגורר בגרר.",
  "26_7": "כאשר אנשי המקום שאלו אותו על אשתו, הוא אמר: 'היא אחותי', כיוון שחשש לומר 'אשתי', שמא יהרגו אותו אנשי המקום בגלל יופייה של רבקה.",
  "26_8": "לאחר שחלף זמן רב, השקיף אבימלך מלך פלשתים בעד החלון וראה את יצחק מתנהג באינטימיות ובחיבה עם רבקה אשתו.",
  "26_9": "אבימלך קרא ליצחק ואמר לו בתרעומת: 'הרי היא בבירור אשתך! כיצד אמרת שהיא אחותך?'; יצחק הסביר: 'חששתי פן איהרג בגללה'.",
  "26_10": "אבימלך אמר: 'מה הדבר הזה שעשית לנו? עוד מעט היה אחד מנכבדי העם שוכב עם אשתך, והיית מביא עלינו אשמה כבדה!'.",
  "26_11": "אבימלך הוציא צו חמור לכל העם: 'כל מי שיפגע באיש הזה או באשתו יומת מיד'.",
  "26_12": "יצחק זרע תבואה באותה ארץ, ובאותה שנה הפיק יבול של פי מאה מהמשוער, כי ה' בירך אותו בשפע.",
  "26_13": "האיש הלך והתעשר, והמשיך לצבור נכסים עד שהפך לעשיר מופלג מאוד.",
  "26_14": "היה לו מקנה עצום של צאן ובקר וצוות עבדים גדול, והפלשתים החלו לקנא בו.",
  "26_15": "את כל בארות המים שחפרו עבדי אביו בימי אברהם סתמו הפלשתים ומילאו אותן בעפר.",
  "26_16": "לבסוף אמר אבימלך אל יצחק: 'עזוב אותנו, כי נהיית חזק ועשיר מאיתנו בהרבה'.",
  "26_17": "יצחק עזב משם, הקים את מחנהו בנחל גרר והתיישב שם.",
  "26_18": "יצחק שב וחפר את בארות המים שחפרו בימי אברהם אביו ואשר הפלשתים סתמו לאחר מות אברהם, וקרא להן באותם שמות שקרא להן אביו.",
  "26_19": "עבדי יצחק חפרו בנחל ומצאו שם באר עם מעיין מים חיים שופע.",
  "26_20": "רועי גרר רבו עם רועי יצחק וטענו: 'המים שייכים לנו!'; לכן קרא יצחק לבאר 'עֵשֶׂק', כי התקוטטו איתו עליה.",
  "26_21": "הם חפרו באר נוספת, ורבו גם עליה; לכן קרא לה 'שִׂטְנָה' (על שם העוינות והשנאה).",
  "26_22": "הוא העתיק את מקומו משם וחפר באר אחרת, ועליה כבר לא רבו; הוא קרא לה 'רְחוֹבוֹת' ואמר: 'כי עתה הרחיב ה' לנו מקום ונפרה ונתפתח בארץ'.",
  "26_23": "משם עלה יצחק לבאר שבע.",
  "26_24": "ה' נראה אליו באותו לילה ואמר: 'אני אלוהי אברהם אביך; אל תירא כי אני איתך, אברך אותך וארבה את זרעך בזכות אברהם עבדי'.",
  "26_25": "יצחק בנה שם מזבח והתפלל בשם ה', נטה שם את אוהלו, ועבדיו כרו שם באר מים.",
  "26_26": "אבימלך הגיע אליו מגרר יחד עם אחזת יועצו ופיכול מפקד צבאו.",
  "26_27": "יצחק שאל אותם: 'מדוע באתם אליי, אחרי ששנאתם אותי וגירשתם אותי מקרבכם?'.",
  "26_28": "הם ענו: 'ראינו בבירור שה' נמצא איתך ומברך אותך, ואמרנו: ראוי שתהיה שבועת ברית בינינו לבינך, ונכרות ברית שלום איתך'.",
  "26_29": "'שלא תעשה איתנו שום רעה, כשם שאנו לא פגענו בך, עשינו איתך רק טוב ושילחנו אותך בשלום; הרי אתה כעת מבורך ה''.",
  "26_30": "יצחק ערך לכבודם סעודת משתה, והם אכלו ושתו.",
  "26_31": "הם קמו מוקדם בבוקר ונשבעו הדדית לברית שלום; יצחק ליווה אותם והם נפרדו ממנו בידידות.",
  "26_32": "באותו יום באו עבדי יצחק ובישרו לו על אודות הבאר שחפרו: 'מצאנו מים בשפע!'.",
  "26_33": "הוא קרא לה 'שִׁבְעָה' (על שם השבועה); לכן נקרא שם העיר באר שבע עד היום הזה.",
  "26_34": "כאשר עשו היה בן ארבעים שנה, הוא נשא לאישה את יהודית בת בארי החיתי ואת בשמת בת אילון החיתי.",
  "26_35": "הנשים הללו גרמו צער ומורת רוח עמוקה ליצחק ולרבקה בגלל עבודת האלילים ומעשיהן הרעים.",
  "27_1": "כאשר יצחק הזדקן ועיניו כהו מראות, הוא קרא לעשו בנו הגדול ואמר לו: 'בני!', ועשו ענה: 'הנני'.",
  "27_2": "יצחק אמר: 'הנה זקנתי, ואינני יודע מתי יגיע יום מותי'.",
  "27_3": "'לכן קח עכשיו את כלי הציד שלך, את אשפת החצים ואת קשתך, צא לשדה וצוד עבורי ציד'.",
  "27_4": "'והכן לי מטעמים טעימים כמו שאני אוהב והבא לי לאכול, כדי שנפשי תברך אותך לפני שאמות'.",
  "27_5": "ורבקה שמעה את הדברים שיצחק אמר לעשו בנו; ועשו יצא לשדה לצוד ציד ולהביאו לאביו.",
  "27_6": "רבקה פנתה מיד אל יעקב בנה ואמרה: 'שמעתי את אביך אומר לעשו אחיך:'",
  "27_7": "'הבא לי ציד והכן לי מטעמים כדי שאוכל ואברך אותך לפני ה' בטרם מותי'.",
  "27_8": "'ועכשיו בני, הקשב היטב לקולי ועשה בדיוק מה שאני מצווה עליך:'",
  "27_9": "'לך מיד אל עדר הצאן וקח לי משם שני גדיי עיזים מובחרים, ואני אכין מהם מטעמים משובחים לאביך כמו שהוא אוהב'.",
  "27_10": "'אתה תביא אותם לאביך שיאכל, כדי שהוא יברך אותך לפני מותו'.",
  "27_11": "יעקב חשש ואמר לאמו: 'אבל עשו אחי הוא איש שעיר מאוד, ואני אדם בעל עור חלק'.",
  "27_12": "'שמא ימשש אותי אבי ואיראה בעיניו כנוכל ומתעתע, ואביא על עצמי קללה במקום ברכה!'.",
  "27_13": "אמו הרגיעה אותו ואמרה: 'עליי תחול קללתך אם תהיה, בני; רק הקשב לקולי, לך והבא לי את הגדיים'.",
  "27_14": "הוא הלך, לקח והביא אותם לאמו, ואמו הכינה מטעמים בדיוק בטעם שאביו אהב.",
  "27_15": "רבקה לקחה את בגדי החמודות המפוארים של עשו בנה הגדול, שהיו שמורים אצלה בבית, והלבישה בהם את יעקב בנה הצעיר.",
  "27_16": "את עורות גדיי העיזים הלבישה על ידיו ועל חלקת צווארו החלק כדי לדמות שיער.",
  "27_17": "היא נתנה ביד יעקב בנה את המטעמים המשובחים ואת הלחם שאפתה.",
  "27_18": "הוא נכנס אל אביו ואמר: 'אבי!', ויצחק שאל: 'הנני, מי אתה בני?'.",
  "27_19": "יעקב אמר לאביו: 'אני עשו בכורך, עשיתי בדיוק כפי שביקשת; קום נא, שב ואכול מן הציד שלי כדי שתברך אותי נפשך'.",
  "27_20": "יצחק תמה ושאל: 'איך הצלחת למצוא ציד כל כך מהר, בני?', ויעקב השיב: 'כי ה' אלוהיך זימן זאת לפניי בהצלחה'.",
  "27_21": "יצחק אמר ליעקב: 'גש נא אליי ואמשש אותך, בני, כדי לוודא האם אתה אכן בני עשו או לא'.",
  "27_22": "יעקב ניגש ליצחק אביו, ויצחק מישש אותו ואמר מופתע: 'הקול נשמע כקולו של יעקב, אך הידיים מחוספסות כידי עשו'.",
  "27_23": "הוא לא זיהה אותו כי ידיו היו שעירות כידי עשו אחיו, ועמד לברך אותו.",
  "27_24": "הוא שאל אותו שוב ליתר ביטחון: 'אתה באמת בני עשו?', ויעקב השיב: 'אני'.",
  "27_25": "יצחק אמר: 'הגש לי ואוכל מציד בני, כדי שתברך אותך נפשי'; יעקב הגיש לו והוא אכל, והביא לו יין והוא שתה.",
  "27_26": "יצחק אביו אמר לו: 'גש נא אליי ונשק לי, בני'.",
  "27_27": "הוא ניגש ונישק לו; יצחק הריח את ריח בגדיו ובירך אותו בהתרגשות: 'ראו, ריח בני רענן ומבורך כריח שדה פורה שה' בירך אותו'.",
  "27_28": "'וייתן לך האלוהים משפע טל השמיים ומפוריות שמני האדמה, ושפע רב של תבואת דגן ויין תירוש'.",
  "27_29": "'עמים רבים ישרתו אותך ואומות ישתחוו לך; תהיה אדון ושליט לאחיך, ובני אמך ישתחוו לך; כל מקלליך יהיו ארורים, וכל מברכיך יהיו ברוכים'.",
  "27_30": "אך סיים יצחק לברך את יעקב, ורק אך יצא יעקב מנוכחות יצחק אביו – ועשו אחיו חזר מצידו.",
  "27_31": "גם עשו הכין מטעמים והביא לאביו, ואמר: 'יקום נא אבי ויאכל מציד בנו, כדי שנפשך תברך אותי'.",
  "27_32": "יצחק אביו נדהם ושאל אותו: 'מי אתה?', והוא ענה: 'אני בנך בכורך עשו'.",
  "27_33": "יצחק נתקף חרדה ורעדה עמוקה מאוד, ואמר בקול רועד: 'אם כן מי הוא זה שצד ציד והביא לי הרגע, ואכלתי מכל המטעמים לפני שבאת ובירכתי אותו? ואכן – מבורך הוא יישאר!'.",
  "27_34": "כששמע עשו את דברי אביו, פרץ בצעקה גדולה, מרה ומזעזעת, והתחנן לאביו: 'ברך גם אותי, אבי!'.",
  "27_35": "יצחק אמר בכאב: 'אחיך בא בפיקחות ועורמה ולקח את ברכתך'.",
  "27_36": "עשו אמר בזעם: 'האם לא במקרה שמו יעקב? הרי הוא רימה ועקף אותי כבר פעמיים: לקח את בכורתי, והנה עכשיו לקח גם את ברכתי!'; ושאל: 'האם לא שמרת ברכה גם עבורי?'.",
  "27_37": "יצחק ענה לעשו: 'הרי שמתי אותו לשליט עליך, את כל אחיו נתתי לו לעבדים, ובירכתי אותו בשפע של תבואה ויין; אז מה עוד אוכל לעשות עבורך, בני?'.",
  "27_38": "עשו התחנן ובכה בייאוש: 'האם ברכה אחת בלבד יש לך, אבי? ברך גם אותי, אבי!', ועשו הרים את קולו ובכה בדמעות שליש.",
  "27_39": "יצחק אביו ענה לו ברחמים: 'הנה גם מקום מגוריך יהיה מאזורי שמני הארץ ומטל השמיים מלמעלה'.",
  "27_40": "'אך על חרבך תחיה ולאחיך תהיה כפוף; אולם כאשר ירדו צאצאיו מדרך הישר, תוכל לפרוק את עולו מעל צווארך'.",
  "27_41": "עשו שנא ונטר איבה עמוקה ליעקב על הברכה שאביו בירך אותו, ואמר בלבו: 'ימי האבל על מות אבי קרבים, ומיד לאחר מכן אהרוג את יעקב אחי'.",
  "27_42": "דברי עשו בנה הבכור הגיעו לאוזני רבקה; היא קראה מיד ליעקב בנה הצעיר ואמרה לו: 'הנה עשו אחיך מתנחם במחשבה להרוג אותך'.",
  "27_43": "'ועכשיו בני, הקשב לעצתי: קום וברח מיד אל לבן אחי לחרן'.",
  "27_44": "'והישאר אצלו זמן מה, עד שיחלוף זעמו של אחיך'.",
  "27_45": "'עד שיירגע כעסו של אחיך ממך והוא ישכח את מה שעשית לו, ואז אשלח שליח לקרוא לך חזרה; למה שאאבד את שניכם ביום אחד?'.",
  "27_46": "רבקה פנתה ליצחק בטענה אחרת ואמרה: 'מאסתי בחיי בגלל נשות חת המקומיות של עשו; אם יעקב ייקח אישה מבנות חת כמו אלה, בשביל מה לי לחיות?'.",
  "28_1": "יצחק קרא ליעקב, בירך אותו וציווה עליו באזהרה: 'אל תיקח אישה מבנות כנען'.",
  "28_2": "'קום ולך לפדן ארם, אל בית בתואל אבי אמך, וקח לך משם אישה מבנות לבן אחי אמך'.",
  "28_3": "'ואל שדי יברך אותך, יפרה אותך וירבה אותך, ותהפוך לקהל של עמים רבים'.",
  "28_4": "'וייתן לך את ברכת אברהם – לך ולזרעך איתך – כדי שתרש את ארץ מגוריך שאלוהים הבטיח לאברהם'.",
  "28_5": "יצחק שילח את יעקב בברכה, והוא יצא לדרך אל פדן ארם אל לבן בן בתואל הארמי, אחי רבקה אם יעקב ועשו.",
  "28_6": "עשו ראה שיצחק בירך את יעקב ושילח אותו לפדן ארם לשאת שם אישה, וציווה עליו: 'לא תיקח אישה מבנות כנען'.",
  "28_7": "וראה שיעקב שמע בקול אביו ואמו ויצא לפדן ארם.",
  "28_8": "עשו הבין עד כמה בנות כנען רעות ושנואות בעיני יצחק אביו.",
  "28_9": "לכן הלך עשו אל בית ישמעאל, ולקח בנוסף לנשותיו גם את מחלת בת ישמעאל בן אברהם, אחות נביות, לו לאישה.",
  "28_10": "יעקב יצא מבאר שבע והלך בכיוון חרן.",
  "28_11": "הוא הגיע למקום מסוים (הר המוריה) ולן שם כי כבר שקעה השמש; הוא לקח כמה מאבני המקום, הניח אותן סביב ראשו להגנה, ושכב לישון באותו מקום.",
  "28_12": "הוא חלם, והנה סולם מוצב על הארץ וראשו מגיע עד השמיים, ומלאכי אלוהים עולים ויורדים בו.",
  "28_13": "והנה ה' ניצב מעליו ואמר לו: 'אני ה' אלוהי אברהם אביך ואלוהי יצחק; את האדמה שאתה שוכב עליה – אתן לך ולצאצאיך'.",
  "28_14": "'צאצאיך יהיו רבים כעפר הארץ, ותתפשט בעוצמה מערבה, מזרחה, צפונה ודרומה; וכל משפחות האדמה יתברכו בך ובזרעך'.",
  "28_15": "'והנה אני איתך, אשמור עליך בכל אשר תלך ואחזיר אותך אל האדמה הזאת; לא אעזוב אותך עד שאקיים במלואו את כל מה שהבטחתי לך'.",
  "28_16": "יעקב התעורר משנתו ואמר בהתפעלות: 'אכן ה' נוכח במקום הזה, ואני לא ידעתי זאת!'.",
  "28_17": "הוא התמלא יראה עמוקה ואמר: 'כמה מלא הוד וקדושה המקום הזה! אין זה אלא בית משכן לאלוהים וזהו שער הכניסה לשמיים'.",
  "28_18": "יעקב השכים מוקדם בבוקר, לקח את האבן ששם ליד ראשו והעמיד אותה כמצבת זיכרון, ויצק שמן על ראשה להקדשה.",
  "28_19": "הוא קרא למקום ההוא 'בֵּית אֵל', אף שקודם לכן נקראה העיר הסמוכה 'לוז'.",
  "28_20": "יעקב נדר נדר ואמר: 'אם אלוהים יהיה איתי, ישמור עליי בדרך הזו שבה אני צועד, וייתן לי לחם לאכול ובגד ללבוש'.",
  "28_21": "'ואשוב בשלום לבית אבי – אז אקבל על עצמי שיהיה ה' לי לאלוהים בעבודה מוחלטת'.",
  "28_22": "'והאבן הזו שהצבתי כמצבה תהיה מקום של עבודת אלוהים; ומכל מה שתעניק לי – אפריש מעשר לעבודתך'.",
  "29_1": "יעקב המשיך בדרכו ברגליים קלות ושמחות, והגיע לארץ בני המזרח.",
  "29_2": "הוא הביט וראה באר בשדה, ושלושה עדרי צאן רובצים לצידה כי מאותה באר נהגו להשקות את העדרים, ואבן כבדה וגדולה מונחת על פי הבאר.",
  "29_3": "רק כאשר התאספו לשם כל העדרים, גללו הרועים יחד את האבן מעל פי הבאר, השקו את הצאן, והחזירו את האבן למקומה על פי הבאר.",
  "29_4": "יעקב פנה לרועים ושאל: 'אחיי, מאיזה מקום אתם?', והם ענו: 'אנחנו מחרן'.",
  "29_5": "הוא שאל אותם: 'האם אתם מכירים את לבן בן נחור?', והם ענו: 'אנחנו מכירים אותו היטב'.",
  "29_6": "הוא שאל: 'האם שלומו טוב?', והם ענו: 'שלומו מצוין, והנה רחל בתו מגיעה בדיוק עם עדר הצאן'.",
  "29_7": "יעקב אמר להם: 'הרי אמצע היום עוד רחוק, וטרם הגיע הזמן לאסוף את המקנה ללינה; השקו את הצאן ולכו לרעות אותן עוד בשדה'.",
  "29_8": "הם השיבו: 'איננו יכולים לעשות זאת לבדנו, עד שיתאספו כל הרועים ויגללו יחד את האבן הכבדה מפי הבאר, ורק אז נשקה את הצאן'.",
  "29_9": "בעודו משוחח איתם, הגיעה רחל עם הצאן של אביה, כי היא הייתה רועת צאן.",
  "29_10": "כאשר ראה יעקב את רחל בת לבן אחי אמו ואת צאנו של לבן אחי אמו, ניגש יעקב וגלל בעוצמה את האבן הכבדה מעל פי הבאר בקלות (כמו פקק מבקבוק), והשקה את צאן לבן אחי אמו.",
  "29_11": "יעקב נשק לרחל (נשיקת קרובים לשלום), והרים את קולו ובכה מהתרגשות והקלה.",
  "29_12": "יעקב סיפר לרחל שהוא קרוב משפחה של אביה ושהוא בנה של רבקה; היא רצה מיד ובישרה לאביה.",
  "29_13": "כששמע לבן את השמועה על בוא יעקב בן אחותו, רץ לקראתו, חיבק אותו, נישק לו והביא אותו לביתו; ויעקב סיפר ללבן את כל קורותיו.",
  "29_14": "לבן אמר לו בחום: 'אכן אתה בן משפחתי, עצמי ובשרי ממש!'; ויעקב התגורר אצלו חודש ימים.",
  "29_15": "לבן אמר ליעקב: 'האם בגלל שאתה קרוב משפחתי תעבוד אצלי בחינם? הגד לי מהו השכר שאתה מבקש'.",
  "29_16": "וללבן היו שתי בנות: שם הגדולה לאה ושם הצעירה רחל.",
  "29_17": "עיניה של לאה היו עדינות ורכות (מרוב בכי ותפילה שלא תינשא לעשו הרשע), ואילו רחל הייתה יפת תואר ובעלת מראה מושלם.",
  "29_18": "יעקב אהב את רחל, ואמר ללבן: 'אעבוד אצלך שבע שנים תמורת רחל בתך הצעירה'.",
  "29_19": "לבן הסכים ואמר: 'עדיף שאתן אותה לך מאשר שאתן אותה לאיש זר; הישאר ועבוד אצלי'.",
  "29_20": "יעקב עבד שבע שנים תמורת רחל, ובשל אהבתו העמוקה אליה הן נראו בעיניו כימים ספורים בלבד.",
  "29_21": "בתום התקופה אמר יעקב ללבן: 'תן לי את אשתי כי השלמתי את ימי עבודתי, ואכנס לחיי נישואין איתה'.",
  "29_22": "לבן כינס את כל אנשי המקום וערך משתה חתונה גדול.",
  "29_23": "בערב, לקח לבן בחשיכה את לאה בתו והכניס אותה אל יעקב, ויעקב לא הבחין בכך ובא אליה.",
  "29_24": "לבן נתן ללאה בתו את זלפה שפחתו, שתשרת אותה כשפחה אישית.",
  "29_25": "בבוקר התברר ליעקב שהאישה היא לאה! הוא בא בכעס ללבן ואמר: 'מה הדבר הזה שעשית לי? הרי תמורת רחל עבדתי אצלך, אז מדוע רימית אותי?'.",
  "29_26": "לבן התחמק וענה: 'לא נהוג במקומנו להשיא את הצעירה לפני הבכירה'.",
  "29_27": "'חגוג שבעה ימי משתה עם זו, ואז ניתן לך גם את רחל, בתמורה לשבע שנות עבודה נוספות שתעבוד אצלי'.",
  "29_28": "יעקב הסכים, השלים את שבעת ימי המשתה עם לאה, ולבן השיא לו גם את רחל בתו לאישה.",
  "29_29": "לבן נתן לרחל בתו את בלהה שפחתו, שתהיה לה לשפחה אישית.",
  "29_30": "יעקב בא גם אל רחל ואהב את רחל יותר מאשר את לאה, והמשיך לעבוד אצל לבן שבע שנים נוספות.",
  "29_31": "ה' ראה שלאה פחות אהובה, פתח את רחמה והעניק לה ילדים, ואילו רחל נותרה עקרה.",
  "29_32": "לאה הרתה וילדה בן וקראה לו ראובן, כי אמרה: 'ה' ראה את צערי, ועכשיו בעלי יאהב אותי'.",
  "29_33": "היא הרתה שוב וילדה בן ואמרה: 'ה' שמע שאני פחות אהובה ולכן נתן לי גם את הבן הזה', וקראה לו שמעון.",
  "29_34": "היא הרתה שוב וילדה בן ואמרה: 'הפעם בעלי יתחבר וייקשר אליי בחיבה כי ילדתי לו שלושה בנים', ולכן נקרא שמו לוי.",
  "29_35": "היא הרתה שוב וילדה בן ואמרה: 'הפעם אודה במיוחד לה'', ולכן קראה לו יהודה; ואז פסקה מללדת לזמן מה.",
  "30_1": "רחל ראתה שאינה יולדת בנים ליעקב וקינאה בזכויותיה של אחותה, ואמרה ליעקב בכאב: 'התפלל והבא לי בנים, ואם לא – אני נחשבת כמתה!'.",
  "30_2": "יעקב כעס על דבריה ואמר: 'האם אני עומד במקום אלוהים שמנע ממך פרי בטן?'.",
  "30_3": "היא אמרה: 'הנה שפחתי בלהה; שכב איתה, היא תלד ילד על ברכיי ואזכה גם אני להיבנות ולהקים משפחה דרכה'.",
  "30_4": "היא נתנה לו את בלהה שפחתה לאישה, ויעקב בא אליה.",
  "30_5": "בלהה הרתה וילדה ליעקב בן.",
  "30_6": "רחל אמרה: 'אלוהים שפט אותי בצדק וגם שמע לתפילתי ונתן לי בן', ולכן קראה לו דן.",
  "30_7": "בלהה שפחת רחל הרתה שוב וילדה בן שני ליעקב.",
  "30_8": "רחל אמרה: 'תפילות עזות ועקשניות הפצרתי באלוהים להשתוות לאחותי ואף הצלחתי', וקראה לו נפתלי.",
  "30_9": "לאה ראתה שהפסיקה ללדת, לקחה את זלפה שפחתה ונתנה אותה ליעקב לאישה.",
  "30_10": "זלפה שפחת לאה ילדה ליעקב בן.",
  "30_11": "לאה אמרה: 'בא מזל טוב והצלחה!', וקראה לו גד.",
  "30_12": "זלפה שפחת לאה ילדה בן שני ליעקב.",
  "30_13": "לאה אמרה: 'איזה אושר ושמחה, כי כל הנשים ישבחו את מזלי הטוב!', וקראה לו אשר.",
  "30_14": "בימי קציר החיטים הלך ראובן ומצא צמחי דודאים (פרחים ריחניים המועילים לפוריות) בשדה והביא אותם ללאה אמו; רחל פנתה ללאה וביקשה: 'תני לי בבקשה מדודאי בנך'.",
  "30_15": "לאה הטיחה בה בכאב: 'האם מעט הדבר שלקחת את בעלי, שאת רוצה לקחת עכשיו גם את דודאי בני?'; רחל השיבה: 'אם כך, הוא ישכב איתך הלילה תמורת דודאי בנך'.",
  "30_16": "כשיעקב חזר מהשדה לקראת ערב, יצאה לאה לקראתו ואמרה: 'אליי תבוא הלילה, כי שכרתי את זכותך תמורת הדודאים של בני'; והוא שכב איתה באותו לילה.",
  "30_17": "אלוהים שמע לתפילת לאה, היא הרתה וילדה ליעקב בן חמישי.",
  "30_18": "לאה אמרה: 'אלוהים נתן לי את שכרי על כך שמסרתי את שפחתי לבעלי', וקראה לו יששכר.",
  "30_19": "לאה הרתה שוב וילדה בן שישי ליעקב.",
  "30_20": "לאה אמרה: 'אלוהים העניק לי מתנה נהדרת; מעתה יקבע בעלי את עיקר משכנו אצלי כי ילדתי לו שישה בנים', וקראה לו זבולון.",
  "30_21": "לאחר מכן ילדה בת, וקראה לה דינה.",
  "30_22": "אלוהים זכר את צדקתה של רחל, שמע לתפילותיה ופתח את רחמה.",
  "30_23": "היא הרתה וילדה בן, ואמרה בשמחה: 'אלוהים הסיר את חרפת עקרותי'.",
  "30_24": "היא קראה לו יוסף ואמרה בתפילה: 'שיוסיף לי ה' עוד בן נוסף'.",
  "30_25": "לאחר שרחל ילדה את יוסף, פנה יעקב ללבן ואמר: 'שלח אותי ואלך חזרה למקומי ולארצי'.",
  "30_26": "'תן לי את נשיי ואת ילדיי שעבדתי עבורם אצלך ואלך, שהרי אתה יודע היטב באיזו מסירות ונאמנות שירתתי אותך'.",
  "30_27": "לבן אמר לו: 'אם מצאתי חן בעיניך, אנא הישאר; הרי בדקתי בניחוש וראיתי בבירור שה' מברך אותי אך ורק בזכותך'.",
  "30_28": "והוסיף: 'קבע בעצמך את השכר שאתה דורש ממני, ואתן לך'.",
  "30_29": "יעקב אמר לו: 'אתה יודע כיצד עבדתי אצלך ואיך שגשג והתרבה הצאן שלך בהשגחתי'.",
  "30_30": "'כי הרכוש המועט שהיה לך לפני בואי גדל לשפע עצום, וה' בירך אותך בכל אשר עשיתי; ועכשיו, מתי אדאג גם אני לביתי ולמשפחתי?'.",
  "30_31": "לבן שאל: 'מה תרצה שאתן לך?'; יעקב ענה: 'אל תיתן לי שום תשלום מראש; אם תסכים לתנאי הבא, אמשיך לרעות ולשמור את צאנך:'",
  "30_32": "'אעבור היום בכל עדרי הצאן שלך, נוציא משם כל שה נקוד, טלוא או חום בכבשים, וכל עז טלואה או נקודה – וכל ולד כזה שייוולד מעתה והלאה יהיה שכרי'.",
  "30_33": "'ויושרי וצדקתי יעידו עליי בבירור בעתיד כשתבוא לבדוק את שכרי: כל עז שאינה נקודה או טלואה וכל כבש שאינו חום שיימצא אצלי – ייחשב כגנוב'.",
  "30_34": "לבן שמח על התנאי ואמר: 'מצוין, שיהיה בדיוק כדבריך!'.",
  "30_35": "בו ביום בודד לבן בעצמו את כל התישים העקודים והטלואים, את כל העיזים הנקודות והטלואות ואת כל הכבשים החומים, ומסר אותם לידי בניו.",
  "30_36": "הוא הרחיק אותם מרחק שלושת ימי הליכה מיעקב, ויעקב רעה את שאר צאנו של לבן (שכולן היו חלקות ופשוטות).",
  "30_37": "יעקב לקח ענפים לחים של עץ לבנה, לוז וערמון, וקילף בהם פסים לבנים כדי לחשוף את הלובן שמתחת לקליפה.",
  "30_38": "הוא הציב את המקלות המקולפים בתוך שקתות המים שבהן שתה הצאן, מול עיני הצאן, כך שכאשר באו לשתות הן התחממו להזדווג.",
  "30_39": "הצאן הזדווגו למראה המקלות, והמליטו ולדות עקודים (מפוספסי רגליים), נקודים וטלואים (בעלי כתמים).",
  "30_40": "את הכבשים הפריד יעקב וכיוון את מבטם אל הצאן העקוד והחום של לבן; כך בנה לעצמו עדרים נפרדים ולא ערבב אותם בעדרי לבן.",
  "30_41": "בכל פעם שהזדווג הצאן החזק והבריא (בבכירות), הניח יעקב את המקלות מול עיניהם בשקתות כדי שייוולדו חזקים ומנומרים לטובתו;",
  "30_42": "וכאשר הזדווג הצאן החלש והמאוחר, לא הניח את המקלות; כך יצאו החלשים עבור לבן והחזקים עבור יעקב.",
  "30_43": "האיש התעשר והתפתח במהירות עצומה, והיו לו עדרים רבים מאוד, שפחות, עבדים, גמלים וחמורים.",
  "31_1": "יעקב שמע את בני לבן אומרים בקנאה: 'יעקב לקח את כל מה שהיה שייך לאבינו, ומנכסי אבינו צבר את כל העושר והכבוד הזה'.",
  "31_2": "יעקב גם הבחין בהתנהגותו של לבן, וראה שפניו אינן מאירות אליו כפי שהיו בעבר.",
  "31_3": "ה' אמר אל יעקב: 'שוב לארץ אבותיך ולמולדתך, ואני אהיה איתך'.",
  "31_4": "יעקב שלח לקרוא לרחל וללאה אל השדה, אל מקום מרעה צאנו.",
  "31_5": "הוא אמר להן: 'אני רואה שפני אביכן אינן כתמול שלשום כלפיי, אך אלוהי אבי עומד לצידי'.",
  "31_6": "'ואתן יודעות היטב שבכל כוחי ומרצי שירתתי את אביכן'.",
  "31_7": "'ואביכן היתל בי ושינה את תנאי שכרי עשרות פעמים, אך אלוהים לא איפשר לו לפגוע בי'.",
  "31_8": "'אם הוא אמר: נקודים יהיו שכרך – המליטו כל הצאן נקודים; ואם אמר: עקודים יהיו שכרך – המליטו כל הצאן עקודים'.",
  "31_9": "'כך הציל אלוהים את רכוש אביכן והעניק אותו לי'.",
  "31_10": "'בעונת ייחום הצאן נשאתי את עיניי וראיתי בחלום והנה התישים המרביעים את הצאן כולם עקודים, נקודים וברודים'.",
  "31_11": "'מלאך האלוהים פנה אליי בחלום ואמר: יעקב!, ועניתי: הנני'.",
  "31_12": "'הוא אמר: הבט וראה שכל התישים עקודים, נקודים וברודים, כי ראיתי את כל העוול שלבן מעולל לך'.",
  "31_13": "'אני האל שנגלה אליך בבית אל, ששם משחת מצבה ונדרת לי נדר; כעת קום, צא מן הארץ הזאת ושוב אל ארץ מולדתך'.",
  "31_14": "רחל ולאה ענו לו ביחד: 'האם נותר לנו עוד חלק או נחלה בבית אבינו?'.",
  "31_15": "'הרי כמו נוכריות וזרות נחשבנו בעיניו, שהרי מכר אותנו ואפילו את כספנו ומוהרנו בלע לעצמו!'.",
  "31_16": "'כל העושר שאלוהים לקח מאבינו שייך בדין לנו ולבנינו; לכן עשה עכשיו בדיוק את כל מה שאלוהים ציווה עליך'.",
  "31_17": "יעקב קם, הרכיב את בניו ואת נשיו על הגמלים,",
  "31_18": "והנהיג את כל מקנהו ואת כל הרכוש העצום שצבר בפדן ארם, כדי לחזור אל יצחק אביו לארץ כנען.",
  "31_19": "לבן יצא באותה עת לגזוז את צאנו; רחל ניצלה את היעדרו ולקחה את פסלי התרפים של אביה (כדי לגמול אותו מעבודת אלילים).",
  "31_20": "יעקב נהג בערמומיות כלפי לבן הארמי בכך שלא הודיע לו על כוונתו לצאת לדרך.",
  "31_21": "הוא ברח עם כל אשר לו, קם וחצה את נהר פרת, ופנה לכיוון הרי הגלעד.",
  "31_22": "רק ביום השלישי נודע ללבן שיעקב ברח.",
  "31_23": "הוא לקח איתו את קרוביו ורדף אחריו במשך שבעה ימים, והשיג אותו בהר הגלעד.",
  "31_24": "אלוהים נגלה אל לבן הארמי בחלום הלילה והזהיר אותו בתקיפות: 'הישמר לך שלא להזיק ליעקב, ואל תדבר איתו מטוב ועד רע באיומים'.",
  "31_25": "לבן השיג את יעקב; יעקב תקע את אוהלו בהר, ולבן ואנשיו חנו אף הם בהר הגלעד.",
  "31_26": "לבן פנה אל יעקב ושאל: 'מה עשית? רימית אותי והובלת את בנותיי כאילו היו שבויות במלחמה!'.",
  "31_27": "'מדוע ברחת בסתר בלי לספר לי? הרי הייתי משלח אותך בשמחה, בשירים, בתוף ובכינור!'.",
  "31_28": "'אפילו לא איפשרת לי לנשק לשלום לנכדיי ולבנותיי; נהגת בטיפשות רבה'.",
  "31_29": "'יש בידי כוח ועוצמה להרע לכם, אלא שאלוהי אביכם דיבר אליי אמש ואמר: הישמר לך מלדבר עם יעקב מטוב ועד רע'.",
  "31_30": "'ועכשיו, גם אם הלכת בגלל געגועיך העזים לבית אביך – מדוע גנבת את אלוהיי ופסליי?'.",
  "31_31": "יעקב ענה ללבן: 'ברחתי כי פחדתי, וחששתי שמא תגזול את בנותיך ממני בכוח'.",
  "31_32": "'אבל מי שאצלו תמצא את אלוהיך – לא יחיה! בפני אחינו בדוק וזהה מה משלך נמצא אצלי וקח לך'; ויעקב לא ידע שרחל לקחה אותם.",
  "31_33": "לבן נכנס וחיפש באוהל יעקב, באוהל לאה ובאוהל שתי השפחות ולא מצא דבר; הוא יצא מאוהל לאה ונכנס לאוהל רחל.",
  "31_34": "ורחל לקחה את התרפים, הטמינה אותם בתוך כר הגמל וישבה עליהם; לבן מישש וחיפש בכל האוהל ולא מצא מאומה.",
  "31_35": "היא אמרה לאביה: 'אל יכעס אדוני שאינני יכולה לקום לכבודך, כי אני בזמן וסת הנשים'; הוא חיפש ביסודיות ולא מצא את התרפים.",
  "31_36": "יעקב כעס מאוד והתעמת עם לבן בתרעומת: 'מהו פשעי ומה חטאי שרדפת אחריי בכזה זעם?'.",
  "31_37": "'הרי חיפשת ומיששת את כל חפציי – מה מצאת מכל כלי ביתך? שים זאת כאן מול קרוביי וקרוביך, ושישפטו בינינו!'.",
  "31_38": "'זה עשרים שנה אני אצלך: כבשייך ועזיך מעולם לא הפילו את ולדותיהן, ומעולם לא שחטתי ולא אכלתי איל מעדריך'.",
  "31_39": "'בהמה שנטרפה לא הבאתי אליך כהפסד – אני שילמתי עליה מכיסי; דרשת ממני פיצוי על כל מה שנגנב ביום או בלילה'.",
  "31_40": "'סבלתי קשות: ביום ייבש אותי החום הלוהט ובלילה הקור העז, והשינה נדדה מעיניי מרוב שמירה'.",
  "31_41": "'זה היה חלקי עשרים שנה בביתך: עבדתי אצלך ארבע עשרה שנה תמורת שתי בנותיך ושש שנים תמורת צאנך, ואתה שינית את שכרי עשרות פעמים'.",
  "31_42": "'אלמלא אלוהי אבי, אלוהי אברהם ופחד יצחק, עמד לצידי – היית משלח אותי עכשיו בידיים ריקות לחלוטין! אך אלוהים ראה את עמלי ויגיע כפיי והוכיח אותך אמש'.",
  "31_43": "לבן ענה ליעקב: 'הבנות הן בנותיי, הילדים הם נכדיי, הצאן הוא צאני וכל מה שאתה רואה כאן שייך לי; אך מה אוכל לעשות היום לבנותיי אלה או לילדים שילדו?'.",
  "31_44": "'בוא עכשיו ונכרות ברית שלום, אני ואתה, והיא תהיה לעדות ביני לבינך'.",
  "31_45": "יעקב לקח אבן גדולה והעמיד אותה כמצבה.",
  "31_46": "יעקב אמר לקרוביו: 'אספו אבנים'; הם אספו אבנים והקימו גל אבנים, ואכלו שם יחד סעודת ברית על הגל.",
  "31_47": "לבן קרא לגל בארמית 'יְגַר שָׂהֲדוּתָא' (גל העדות), ויעקב קרא לו בעברית 'גַּלְעֵד'.",
  "31_48": "לבן אמר: 'גל האבנים הזה משמש עדות ביני ובינך היום', לכן נקרא שמו גלעד.",
  "31_49": "וכן נקרא המקום 'המצפה', כי אמר לבן: 'ה' יצפה וישמור ביני ובינך כשנהיה רחוקים זה מזה'.",
  "31_50": "'שלא תענה את בנותיי ושלא תיקח נשים נוספות על בנותיי; אין איתנו שום אדם שרואה, אך אלוהים הוא עד ביני ובינך'.",
  "31_51": "לבן הוסיף ואמר ליעקב: 'הנה גל האבנים הזה והנה המצבה שהצבתי ביני ובינך'.",
  "31_52": "'עדים הם גל האבנים והמצבה הזו: אני לא אעבור את הגל הזה לעברך, ואתה לא תעבור את הגל והמצבה הזו לעברי כדי להרע'.",
  "31_53": "'אלוהי אברהם ואלוהי נחור ישפטו בינינו, אלוהי אביהם'; ויעקב נשבע ביראת אביו יצחק.",
  "31_54": "יעקב זבח זבחי שלמים בהר והזמין את קרוביו לסעודת לחם; הם אכלו ולנו בהר.",
  "32_1": "לבן קם מוקדם בבוקר, נישק לנכדיו ולבנותיו ובירך אותם באהבה, ויצא לדרכו ושב למקומו.",
  "32_2": "ויעקב המשיך בדרכו, ופגשו אותו מלאכי אלוהים שבאו ללוותו.",
  "32_3": "כאשר ראה אותם יעקב, אמר: 'זהו מחנה של צבא אלוהים!', וקרא למקום ההוא 'מַחֲנָיִם' (שני מחנות מלאכים: של חו\"ל ושל ארץ ישראל).",
  "32_4": "יעקב שלח שליחים לפניו אל עשו אחיו, אל אזור שעיר שבחבל אדום.",
  "32_5": "הוא ציווה עליהם לומר: 'כך תאמרו לאדוני לעשו: כה אמר עבדך יעקב: התגוררתי כגר אצל לבן והתעכבתי שם עד עתה'.",
  "32_6": "'ורכשתי שוורים, חמורים, צאן, עבדים ושפחות; ואני שולח להודיע זאת לאדוני כדי למצוא חן בעיניך'.",
  "32_7": "השליחים חזרו אל יעקב והודיעו בדאגה: 'באנו אל אחיך עשו, והוא כבר צועד לקראתך מלווה בארבע מאות לוחמים חמושים'.",
  "32_8": "יעקב נתקף פחד וחרדה עמוקה; הוא חילק את האנשים שאיתו ואת הצאן, הבקר והגמלים לשני מחנות נפרדים.",
  "32_9": "הוא חשב: 'אם עשו יתקוף מחנה אחד ויכה אותו – המחנה השני יוכל להימלט ולהינצל'.",
  "32_10": "יעקב התפלל: 'אלוהי אבי אברהם ואלוהי אבי יצחק, ה' שאמרת אליי: שוב לארצך ולמולדתך ואיטיב איתך'.",
  "32_11": "'אני מרגיש כה קטן ואיני ראוי לכל החסדים והנאמנות שהרעפת על עבדך; הרי במקלי בלבד חציתי את הירדן הזה, ועכשיו הפכתי לשני מחנות גדולים'.",
  "32_12": "'הצל נא אותי מיד אחי, מיד עשו, כי אני מפחד ממנו שמא יבוא ויכה אותי ואת האמהות והילדים ללא רחם'.",
  "32_13": "'והרי אתה הבטחת לי במפורש: איטיב איתך מאוד, ואשים את זרעך כחול שעל שפת הים שאי אפשר לספור אותו מרוב כמותו'.",
  "32_14": "הוא לן שם באותו לילה, ולקח מנחה נדיבה מתוך רכושו כדי לפייס את עשו אחיו:",
  "32_15": "מאתיים עיזים ועשרים תיישים, מאתיים כבשות ועשרים אילים,",
  "32_16": "שלושים גמלים מיניקות עם בכריהן, ארבעים פרות ועשרה פרים, עשרים אתונות ועשרה עיירים.",
  "32_17": "הוא מסר אותם לידי עבדיו, כל עדר בנפרד, והורה להם: 'עברו לפניי ושמרו על רווח ומרווח מכובד בין עדר לעדר'.",
  "32_18": "הוא הנחה את מוביל העדר הראשון: 'כאשר יפגוש אותך עשו אחי וישאל אותך: למי אתה שייך, לאן אתה הולך ולמי שייך העדר הזה שלפניך?'",
  "32_19": "'תענה לו: לעבדך יעקב; זוהי מנחת כבוד שנשלחה לאדוני לעשו, והנה יעקב עצמו מגיע מאחורינו'.",
  "32_20": "כך ציווה גם על מוביל העדר השני, השלישי וכל שאר המובילים: 'בנוסח הזה בדיוק דברו אל עשו כאשר תפגשו אותו'.",
  "32_21": "'והוסיפו והדגישו: הנה גם עבדך יעקב מגיע מאחורינו'; כי יעקב אמר בלבו: 'אפייס את כעסו במנחה המקדימה אותי, ורק לאחר מכן אפגוש אותו פנים אל פנים, אולי יתרצה ויקבל אותי בשלום'.",
  "32_22": "משלחת המנחה עברה לפניו, והוא נשאר ללון באותו לילה במחנה.",
  "32_23": "באמצע הלילה קם יעקב, לקח את שתי נשיו, שתי שפחותיו ואת אחד עשר בניו, והעביר אותם את מעבר נחל יבוק.",
  "32_24": "הוא העביר אותם את הנחל, והעביר גם את כל רכושו.",
  "32_25": "יעקב נשאר לבדו מאחור (כדי לבדוק שלא נשכחו פכים קטנים), ונאבק איתו איש מסתורי (שרו של עשו, המלאך) עד עלות השחר.",
  "32_26": "כאשר ראה המלאך שאינו יכול להכריע את יעקב, נגע במפרק ירכו, ופרק הירך של יעקב ננקע תוך כדי המאבק איתו.",
  "32_27": "המלאך אמר: 'שחרר אותי כי עלה השחר (וזמני לומר שירה למעלה)'; יעקב השיב בעוז: 'לא אשחרר אותך אלא אם כן תברך אותי ותודה בזכותי לברכות'.",
  "32_28": "שאל אותו המלאך: 'מה שמך?', והוא ענה: 'יעקב'.",
  "32_29": "המלאך אמר: 'לא יעקב (מלשון עקבה ומרמה) ייקרא עוד שמך אלא יִשְׂרָאֵל, כי נאבקת ונלחמת עם מלאכי אלוהים ועם בני אדם ויכולת להם'.",
  "32_30": "יעקב שאל: 'הגד לי בבקשה מה שמך?'; המלאך ענה: 'מדוע זה אתה שואל לשמי?', ובירך אותו שם.",
  "32_31": "יעקב קרא למקום ההוא 'פְּנִיאֵל', כי אמר: 'ראיתי מלאך אלוהים פנים אל פנים ונפשי ניצלה בחיים'.",
  "32_32": "השמש זרחה והאירה לו כשרפאה אותו כשעבר את פנואל, והוא צלע על ירכו.",
  "32_33": "לכן בני ישראל אינם אוכלים עד היום הזה את גיד הנשה שנמצא על מפרק הירך, משום שהמלאך פגע בגיד הנשה שבירך יעקב.",
  "33_1": "יעקב נשא את עיניו וראה והנה עשו מתקרב עם ארבע מאות אנשיו; הוא חילק את הילדים והפקיד אותם בידי לאה, רחל ושתי השפחות.",
  "33_2": "הוא הציב את השפחות וילדיהן ראשונות, את לאה וילדיה אחריהן, ואת רחל ויוסף אחרונים מכולם כדי להגן עליהם ביותר.",
  "33_3": "והוא עצמו עבר לפניהם בראש, והשתחווה ארצה שבע פעמים של כבוד עד שניגש לאחיו.",
  "33_4": "עשו רץ לקראתו בהתרגשות, חיבק אותו, נפל על צווארו ונישק אותו, ושניהם בכו מהתרגשות.",
  "33_5": "עשו נשא את עיניו, ראה את הנשים והילדים ושאל: 'מי אלה שלידך?'; יעקב השיב בענווה: 'אלה הילדים שאלוהים חנן בהם בחסדו את עבדך'.",
  "33_6": "השפחות וילדיהן ניגשו ראשונות והשתחוו.",
  "33_7": "לאחר מכן ניגשו גם לאה וילדיה והשתחוו, ולבסוף ניגשו יוסף ורחל והשתחוו.",
  "33_8": "עשו שאל: 'מה מטרת כל שיירת העדרים הזו שפגשתי בדרך?'; יעקב השיב: 'זו מנחה כדי למצוא חן וחסד בעיני אדוני'.",
  "33_9": "עשו אמר: 'יש לי רכוש ושפע רב, אחי; שיהיה שלך מה ששייך לך'.",
  "33_10": "אך יעקב הפציר בו: 'אל נא, אם מצאתי חן בעיניך אנא קבל את מנחתי מידי; הרי לראות את פניך הפייסניות היה בעיניי כמו לראות פני מלאך אלוהים, ואתה קיבלת אותי ברצון'.",
  "33_11": "'קח נא את מתנת הברכה שהובאה לכבודך, כי אלוהים חנן אותי ויש לי כל מה שאני צריך'; הוא הפציר בו שוב ושוב, ועשו הסכים ולקח.",
  "33_12": "עשו הציע: 'בוא נצא יחד לדרך, ואני אצעד לצידך'.",
  "33_13": "יעקב ענה לו בנימוס: 'אדוני יודע שהילדים עדינים ורכים, והצאן והבקר המניקים זקוקים להשגחתי; אם יזרזו אותם בדהירה אפילו יום אחד – כל הצאן עלול למות'.",
  "33_14": "'יעבור נא אדוני לפני עבדו, ואני אתקדם בנחת ובאיטיות לפי קצב ההליכה של המקנה ולפי יכולת הילדים, עד שאגיע אל אדוני לשעיר'.",
  "33_15": "עשו הציע: 'אשאיר איתך לפחות חלק מהלוחמים שנמצאים איתי להגנה'; יעקב אמר: 'אין בכך צורך, העיקר שמצאתי חן בעיני אדוני'.",
  "33_16": "באותו יום שב עשו לדרכו לשעיר.",
  "33_17": "ויעקב נסע לסוכות, בנה לעצמו בית ולמקנהו עשה סוכות מחסה; לכן נקרא שם המקום סוכות.",
  "33_18": "יעקב הגיע שלם ובריא בגופו וברכושו אל העיר שכם שבארץ כנען בבואו מפדן ארם, וחנה מול שערי העיר.",
  "33_19": "הוא קנה את חלקת השדה שבה נטה את אוהלו מידי בני חמור אבי שכם במאה קשיטות (מטבעות יקרות).",
  "33_20": "הוא הקים שם מזבח, וקרא לו להודיה: 'אֵל אֱלֹהֵי יִשְׂרָאֵל'.",
  "34_1": "דינה, בתם של יעקב ולאה, יצאה לסייר ולהכיר את בנות המקום.",
  "34_2": "שכם בן חמור החיווי, שהיה נשיא ושליט האזור, ראה אותה; הוא חטף אותה, שכב איתה בכפייה ועינה אותה.",
  "34_3": "נפשו נקשרה בדינה בת יעקב בעוצמה, הוא התאהב בנערה ודיבר על לבה דברי פיתוי וחיבה.",
  "34_4": "שכם פנה אל חמור אביו ואמר לו: 'קח לי את הנערה הזאת לאישה'.",
  "34_5": "יעקב שמע ששכם חילל וטימא את דינה בתו; אך כיוון שבניו היו עם המקנה בשדה, שתק יעקב עד שחזרו.",
  "34_6": "חמור אבי שכם יצא אל יעקב כדי לדבר איתו ולהציע הסדר.",
  "34_7": "בני יעקב שבו מן השדה כשנודע להם הדבר; האנשים נתקפו זעזוע וכעס עצום, כי מעשה נבלה שפל וחסר מוסר נעשה בישראל לשכב עם בת יעקב, ומעשה כזה אסור שייעשה.",
  "34_8": "חמור פנה אליהם ואמר: 'שכם בני מאוהב בכל לבו בבתכם; אנא תנו לו אותה לאישה'.",
  "34_9": "'והבה נתחתן אלה באלה: את בנותיכם תשיאו לנו, ואת בנותינו תיקחו לכם'.",
  "34_10": "'תתגוררו איתנו והארץ תהיה פתוחה לפניכם: התיישבו בה, סחרו בה ורכשו בה נכסים ואחוזות'.",
  "34_11": "שכם עצמו פנה אל אביה ואל אחיה ואמר: 'רק אמצא חן בעיניכם, וכל מה שתדרשו ממני אתן'.",
  "34_12": "'קבעו מוהר גבוה ומתנות רבות ככל שתרצו ואתן כדבריכם, ורק תנו לי את הנערה לאישה'.",
  "34_13": "בני יעקב ענו לשכם ולחמור אביו בעורמה ובחוכמה, כיוון שטימא את דינה אחותם.",
  "34_14": "הם אמרו להם: 'איננו יכולים לעשות דבר כזה ולתת את אחותנו לאיש ערל שאינו נימול, כי זהו אות קלון וחרפה עבורנו'.",
  "34_15": "'נסכים להצעתכם רק בתנאי אחד: אם תהיו כמונו, ותמולו את כל הזכרים שבקרבכם'.",
  "34_16": "'אז נשיא את בנותינו לכם ואת בנותיכם ניקח לנו, נתגורר יחד ונהפוך לעם אחד מאוחד'.",
  "34_17": "'ואם לא תשמעו בקולנו ולא תימולו – ניקח את בתנו ונלך מכאן מיד'.",
  "34_18": "ההצעה נראתה הוגנת וטובה בעיני חמור ובעיני שכם בנו.",
  "34_19": "הצעיר לא השתהה לבצע את התנאי מיד כי חשק מאוד בבת יעקב, והוא היה הנכבד והמשפיע ביותר בכל בית אביו.",
  "34_20": "חמור ושכם בנו באו לשער עירם ופנו אל כל תושבי העיר:",
  "34_21": "'האנשים האלה שוחרי שלום הם כלפינו; הבה ניתן להם להתיישב בארץ ולסחור בה, שהרי הארץ רחבת ידיים ומרווחת; ניקח את בנותיהם לנו לנשים ואת בנותינו ניתן להם'.",
  "34_22": "'אך האנשים מסכימים להתאחד איתנו לעם אחד רק בתנאי זה: שכל זכר בינינו יימול כפי שהם נימולים'.",
  "34_23": "'הרי כל מקניהם, רכושם ובהמותיהם יהיו בסופו של דבר חלק מאיתנו; הבה נסכים לתנאם והם יתיישבו בתוכנו'.",
  "34_24": "כל אנשי העיר הבאים בשערה השתכנעו מדברי חמור ושכם בנו, וכל הגברים והזכרים בעיר נימולו.",
  "34_25": "ביום השלישי לברית המילה, כאשר כאב הפצע היה עז ומשתק במיוחד, לקחו שני בני יעקב – שמעון ולוי, אחי דינה – איש את חרבו, פשטו בביטחון על העיר המשותקת והרגו את כל הזכרים.",
  "34_26": "את חמור ואת שכם בנו הרגו לפי חרב, חילצו את דינה מביתו של שכם ויצאו.",
  "34_27": "שאר בני יעקב נכנסו אל העיר בעקבות ההרוגים ובזזו את העיר שבה חוללה אחותם.",
  "34_28": "את צאנם, בקרם, חמוריהם וכל מה שהיה בעיר ובשדות לקחו כשלל.",
  "34_29": "את כל הונם, את נשיהם ואת ילדיהם לקחו בשבי ובזזו את כל תכולת הבתים.",
  "34_30": "יעקב אמר בתוכחה קשה לשמעון וללוי: 'הבאתם עליי אסון והשמצתם את שמי בקרב יושבי הארץ – הכנענים והפריזים; והרי אנשיי מועטים, ואם יתאחדו נגדי ויתקפו אותי, נישמד אני וכל משפחתי!'.",
  "34_31": "אך הם השיבו בנחרצות: 'האם כאישה מופקרת וזונה יפקיר איש את אחותנו?!'.",
  "35_1": "אלוהים אמר ליעקב: 'קום, עלה לבית אל והתיישב שם, ובנה שם מזבח לאל שנגלה אליך כאשר ברחת מפני עשו אחיך'.",
  "35_2": "יעקב הורה לבני ביתו ולכל הנלווים אליו: 'הסירו את כל פסלי האלילים הזרים שנמצאים בקרבכם, היטהרו והחליפו את בגדיכם בבגדים נקיים'.",
  "35_3": "'נקום ונעלה לבית אל, ואבנה שם מזבח לאל שענה לתפילתי ביום צרתי וליווה אותי לאורך כל הדרך שבה הלכתי'.",
  "35_4": "הם מסרו ליעקב את כל פסלי האלילים שברשותם ואת הנזמים שהיו באוזניהם (ששימשו לעבודה זרה), ויעקב הטמין וקבר אותם תחת עץ האלה שליד שכם.",
  "35_5": "הם יצאו למסעם, ואימת אלוהים ופחד גדול נפלו על כל הערים שמסביב, ואף אחד לא העז לרדוף אחרי בני יעקב.",
  "35_6": "יעקב הגיע ללוז שבארץ כנען – היא בית אל – הוא וכל האנשים שהיו איתו.",
  "35_7": "הוא בנה שם מזבח וקרא למקום 'אֵל בֵּית אֵל', כי שם נגלה אליו אלוהים כאשר ברח מפני אחיו.",
  "35_8": "דבורה מינקת רבקה נפטרה שם, ונקברה מתחת לבית אל תחת עץ האלון; ויעקב קרא למקום 'אַלּוֹן בָּכוּת' מרוב בכי ואבל.",
  "35_9": "אלוהים נראה שוב אל יעקב לאחר שובו מפדן ארם, ובירך אותו.",
  "35_10": "אלוהים אמר לו: 'שמך עד כה היה יעקב; לא ייקרא עוד שמך רק יעקב אלא יִשְׂרָאֵל יהיה שמך', וקרא את שמו ישראל.",
  "35_11": "אלוהים הוסיף ואמר: 'אני אל שדי; פרה ורבה, עם וקהל אומות ייצאו ממך, ומלכים מקרב חלציך ייצאו'.",
  "35_12": "'ואת הארץ שהבטחתי לאברהם וליצחק – לך אתן אותה, וגם לצאצאיך אחריך אתן את הארץ הזאת'.",
  "35_13": "ועלה מעליו כבוד אלוהים במקום שבו דיבר איתו.",
  "35_14": "יעקב העמיד מצבת אבן במקום שבו דיבר איתו אלוהים, ניסך עליה נסך יין ויצק עליה שמן להקדשה.",
  "35_15": "ויעקב חידש וקרא את שם המקום שבו דיבר איתו אלוהים 'בֵּית אֵל'.",
  "35_16": "הם נסעו מבית אל, וכאשר נותר עוד כברת דרך קצרה להגיע לאפרת (בית לחם), כרעה רחל ללדת והלידה הייתה קשה ומסוכנת במיוחד.",
  "35_17": "בשיא הקושי של צירי הלידה אמרה לה המיילדת לעודדה: 'אל תפחדי, כי גם התינוק הזה הוא בן זכר עבורך'.",
  "35_18": "כאשר יצאה נפשה והיא נטתה למות, קראה את שמו ברגעיה האחרונים 'בֶּן אוֹנִי' (בן צערי וכאבי), אך אביו קרא לו 'בִּנְיָמִין' (בן ימין – בן כוח ודרום).",
  "35_19": "רחל נפטרה ונקברה לצד הדרך לאפרת, היא בית לחם.",
  "35_20": "יעקב הציב מצבה על קברה; זוהי מצבת קבורת רחל העומדת עד היום.",
  "35_21": "ישראל המשיך במסעו ונטה את אוהלו מעבר למגדל עדר.",
  "35_22": "כאשר התגורר ישראל באותו אזור, הלך ראובן ובלבל את יצועי בלהה פילגש אביו (כדי למחות על הפגיעה בכבוד אמו לאה), וישראל שמע על כך והקפיד; ובני יעקב היו שנים עשר.",
  "35_23": "בני לאה: ראובן בכור יעקב, שמעון, לוי, יהודה, יששכר וזבולון.",
  "35_24": "בני רחל: יוסף ובנימין.",
  "35_25": "בני בלהה שפחת רחל: דן ונפתלי.",
  "35_26": "ובני זלפה שפחת לאה: גד ואשר; אלה הם שנים עשר בני יעקב שנולדו לו בפדן ארם.",
  "35_27": "יעקב הגיע לבסוף אל יצחק אביו לממרא בקריית ארבע – שהיא חברון – שבה התגוררו אברהם ויצחק.",
  "35_28": "שנות חייו של יצחק היו מאה ושמונים שנה (180 שנה).",
  "35_29": "יצחק גווע ונפטר בשיבה טובה, זקן ושבע ימים מרוצים, ונאסף אל אבותיו; ובניו עשו ויעקב קברו אותו בכבוד במערת המכפלה.",
  "36_1": "ואלה תולדות משפחת עשו, הוא אדום.",
  "36_2": "עשו לקח את נשיו מקרב בנות כנען: את עדה בת אילון החיתי, ואת אוהליבמה בת ענה בת צבעון החיווי.",
  "36_3": "ואת בשמת בת ישמעאל, אחות נביות.",
  "36_4": "עדה ילדה לעשו את אליפז, ובשמת ילדה את רעואל.",
  "36_5": "ואוהליבמה ילדה את יעיש, את יעלאם ואת קורח; אלה בני עשו שנולדו לו בארץ כנען.",
  "36_6": "עשו לקח את נשיו, בניו, בנותיו, כל בני ביתו, מקנהו, בהמותיו וכל רכושו שצבר בארץ כנען, והיגר לארץ אחרת כדי להתרחק מיעקב אחיו.",
  "36_7": "כי רכוש שניהם היה רב מכדי שיוכלו לגור יחד באותו אזור, וארץ מגוריהם לא יכלה לשאת את עומס המרעה של מקניהם.",
  "36_8": "עשו התיישב בהר שעיר; עשו הוא המכונה אדום.",
  "36_9": "ואלה תולדות צאצאי עשו, אבי ממלכת אדום, בהר שעיר:",
  "36_10": "אלה שמות בני עשו: אליפז בן עדה אשת עשו, ורעואל בן בשמת אשת עשו.",
  "36_11": "בני אליפז היו: תימן, אומר, צפו, געתם וקנז.",
  "36_12": "ותמנע הייתה פילגש לאליפז בן עשו, והיא ילדה לאליפז את עמלק; אלה היו צאצאי עדה אשת עשו.",
  "36_13": "ואלה בני רעואל: נחת, זרח, שמה ומיזה; אלה היו צאצאי בשמת אשת עשו.",
  "36_14": "ואלה היו בני אוהליבמה בת ענה בת צבעון, אשת עשו: היא ילדה לעשו את יעיש, יעלאם וקורח.",
  "36_15": "אלה מנהיגי ואלופי שבטי בני עשו: בני אליפז בכור עשו: אלוף תימן, אלוף אומר, אלוף צפו, אלוף קנז,",
  "36_16": "אלוף קורח, אלוף געתם ואלוף עמלק; אלה ראשי השבטים של אליפז בארץ אדום, מצאצאי עדה.",
  "36_17": "ואלה אלופי בני רעואל בן עשו: אלוף נחת, אלוף זרח, אלוף שמה ואלוף מיזה; אלה אלופי רעואל בארץ אדום, מצאצאי בשמת אשת עשו.",
  "36_18": "ואלה אלופי בני אוהליבמה אשת עשו: אלוף יעיש, אלוף יעלאם ואלוף קורח; אלה אלופי אוהליבמה בת ענה אשת עשו.",
  "36_19": "אלה היו בני עשו ואלה מנהיגיהם ואלופיהם, הוא עם אדום.",
  "36_20": "אלה בני שעיר החורי, התושבים המקוריים של הארץ: לוטן, שובל, צבעון וענה,",
  "36_21": "ודישון, אצר ודישן; אלה אלופי שבטי החורי בני שעיר בארץ אדום.",
  "36_22": "בני לוטן היו חורי והימם, ואחות לוטן הייתה תמנע.",
  "36_23": "ואלה בני שובל: עלוון, מנחת, עיבל, שפו ואונם.",
  "36_24": "ואלה בני צבעון: איה וענה; זהו ענה שהכליא ומצא לראשונה את הפרדים (יֵימִם) במדבר בעת שרעה את חמורי צבעון אביו.",
  "36_25": "ואלה בני ענה: דישון, ואוהליבמה בת ענה.",
  "36_26": "ואלה בני דישן: חמדן, אשבן, יתרן וכרן.",
  "36_27": "אלה בני אצר: בלהן, זעוון ועקן.",
  "36_28": "אלה בני דישן: עוץ וארן.",
  "36_29": "אלה אלופי החורי: אלוף לוטן, אלוף שובל, אלוף צבעון, אלוף ענה,",
  "36_30": "אלוף דישון, אלוף אצר ואלוף דישן; אלה היו מנהיגי החורי לפי נחלותיהם בארץ שעיר.",
  "36_31": "ואלה המלכים ששלטו בארץ אדום עוד לפני שמלך מלך כלשהו בבני ישראל:",
  "36_32": "באדום מלך בלע בן בעור, ושם עיר בירתו הייתה דינהבה.",
  "36_33": "בלע מת, ותחתיו מלך יובב בן זרח מהעיר בצרה.",
  "36_34": "יובב מת, ותחתיו מלך חושם מחבל ארץ התימני.",
  "36_35": "חושם מת, ותחתיו מלך הדד בן בדד שהביס והכה את מדין בשדה מואב, ושם עיר בירתו עווית.",
  "36_36": "הדד מת, ותחתיו מלך שמלה מהעיר משרקה.",
  "36_37": "שמלה מת, ותחתיו מלך שאול מהעיר רחובות שעל שפת הנהר.",
  "36_38": "שאול מת, ותחתיו מלך בעל חנן בן עכבור.",
  "36_39": "בעל חנן בן עכבור מת, ותחתיו מלך הדר ושם עירו פעו; ושם אשתו היה מהיטבאל בת מטרד בת מי זהב.",
  "36_40": "ואלה שמות אלופי ומנהיגי עשו לפי משפחותיהם, מקומות מושבם ושמותיהם: אלוף תמנע, אלוף עלווה, אלוף יתת,",
  "36_41": "אלוף אוהליבמה, אלוף אלה, אלוף פינון,",
  "36_42": "אלוף קנז, אלוף תימן, אלוף מבצר,",
  "36_43": "אלוף מגדיאל ואלוף עירם; אלה ראשי ואלופי אדום לפי יישוביהם בארץ נחלתם, הוא עשו אבי אדום.",
  "37_1": "יעקב התיישב בארץ שבה התגורר אביו, בארץ כנען.",
  "37_2": "אלה תולדות משפחת יעקב: יוסף היה נער בן שבע עשרה שנה, שרעה את הצאן יחד עם אחיו; הוא התרועע במיוחד עם בני בלהה ובני זלפה נשות אביו, ויוסף נהג לספר לאביהם דיווחים רעים על מעשיהם.",
  "37_3": "וישראל (יעקב) אהב את יוסף מכל שאר בניו כי הוא נולד לו לעת זקנתו, ותפר עבורו כותנת פסים מיוחדת ומפוארת (בגד משי מובחר).",
  "37_4": "אחיו ראו שאביהם מעדיף ואוהב אותו מכל אחיו, ושנאו אותו על כך; הם אפילו לא היו מסוגלים לדבר איתו לשלום בנימוס.",
  "37_5": "יוסף חלם חלום וסיפר אותו לאחיו, והם הוסיפו לשנוא אותו עוד יותר.",
  "37_6": "הוא אמר להם: 'הקשיבו בבקשה לחלום שחלמתי:'",
  "37_7": "'והנה אנחנו קושרים אלומות שיבולים בתוך השדה, והנה אלומתי קמה והתייצבה זקופה, ואלומותיכם הקיפו את אלומתי והשתחוו לה'.",
  "37_8": "אחיו ענו לו בכעס: 'האם אתה באמת חושב שתמלוך עלינו ותשלוט בנו?!'; והם הוסיפו לשנוא אותו עוד יותר על חלומותיו ועל דיבוריו.",
  "37_9": "הוא חלם חלום נוסף וסיפר אותו לאחיו, ואמר: 'הנה חלמתי עוד חלום, והפעם השמש, הירח ואחד עשר כוכבים משתחווים לי'.",
  "37_10": "הוא סיפר זאת לאביו ולאחיו; אביו נזף בו ואמר: 'מה זה החלום הזה שחלמת? האם באמת נבוא אני, אמך (בלהה שגידלה אותו) ואחיך להשתחוות לך עד הקרקע?!'.",
  "37_11": "אחיו קינאו בו מאוד, אך אביו שמר את הדבר בלבו וציפה לראות כיצד יתגשם.",
  "37_12": "האחים הלכו לרעות את צאן אביהם בשכם.",
  "37_13": "ישראל אמר ליוסף: 'הרי אחיך רועים כעת בשכם; בוא ואשלח אותך לבדוק מה שלומם', ויוסף השיב בציות: 'הנני, אני מוכן'.",
  "37_14": "יעקב אמר לו: 'לך נא ראה מה שלום אחיך ומה שלום הצאן, וחזור לדווח לי'; הוא שילח אותו מעמק חברון, ויוסף הגיע לשכם.",
  "37_15": "איש אחד (המלאך גבריאל בדמות אדם) מצא אותו כשהוא תועה ומחפש בשדה, ושאל אותו: 'מה אתה מחפש?'.",
  "37_16": "יוסף ענה: 'אני מחפש את אחיי; הגד לי בבקשה איפה הם רועים את הצאן'.",
  "37_17": "האיש אמר: 'הם עזבו מכאן, כי שמעתי אותם אומרים: נלך לדותן'; יוסף המשיך בעקבות אחיו ומצא אותם בדותן.",
  "37_18": "הם הבחינו בו מרחוק, ועוד לפני שהספיק להתקרב אליהם הם רקמו מזימה להרוג אותו.",
  "37_19": "הם אמרו איש לאחיו בלעג: 'הנה בעל החלומות ההוא מתקרב!'.",
  "37_20": "'בואו עכשיו ונהרוג אותו, נשליך אותו לאחד הבורות, ונאמר שחיית טרף רעה טרפה אותו; ונראה מה יֵצֵא מחלומותיו הגדולים!'.",
  "37_21": "ראובן שמע זאת וניסה להציל אותו מידיהם; הוא אמר: 'בואו לא נכה אותו עד מוות'.",
  "37_22": "ראובן הוסיף ואמר להם: 'אל תשפכו דם; השליכו אותו אל הבור הזה שבמדבר ואל תשלחו בו יד ישירה' – מתוך כוונה להציל אותו מידם ולהחזיר אותו שלם אל אביו.",
  "37_23": "כאשר יוסף הגיע אל אחיו, הם הפשיטו אותו מיד מכותנתו, מאותה כותנת פסים מפוארת שלבש.",
  "37_24": "הם לקחו אותו והשליכו אותו לתוך הבור; הבור היה ריק לחלוטין ללא מים (אך נחשים ועקרבים היו בו).",
  "37_25": "לאחר מכן ישבו לאכול לחם; הם נשאו את עיניהם וראו שיירת סוחרים ישמעאלים מגיעה מן הגלעד, כשגמליהם עמוסים בשמי נכאת, צרי ולוט (תבלינים ובשמים יקרים), בדרכם להוריד את הסחורה למצרים.",
  "37_26": "יהודה אמר לאחיו: 'איזו תועלת תצמח לנו אם נהרוג את אחינו ונכסה את דמו בסתר?'.",
  "37_27": "'בואו נמכור אותו לישמעאלים במקום שידינו תפגע בו, שהרי אחינו ובשרנו הוא'; ואחיו השתכנעו והסכימו.",
  "37_28": "כאשר עברו סוחרים מדיינים, משכו האחים והעלו את יוסף מתוך הבור, ומכרו את יוסף לישמעאלים בעשרים שקלי כסף; והסוחרים לקחו את יוסף והורידו אותו למצרים.",
  "37_29": "ראובן (שלא היה נוכח במכירה) חזר לבור וראה שיוסף איננו בבור; הוא קרע את בגדיו באבל כבד.",
  "37_30": "הוא חזר לאחיו ואמר בייאוש: 'הילד איננו! ואני, לאן אוליך את חרפתי ואת כאבו של אבי?!'.",
  "37_31": "הם לקחו את כותנתו של יוסף, שחטו גדי עיזים וטבלו את הכותנת בדמו.",
  "37_32": "הם שלחו את כותנת הפסים המגואלת בדם והביאו אותה אל אביהם, ואמרו: 'את הבגד הזה מצאנו; זהה נא האם זו כותנת בנך או לא'.",
  "37_33": "יעקב זיהה אותה מיד וזעק בשברון לב: 'זוהי כותנת בני! חיית טרף רעה טרפה אותו, יוסף נטרף לחלוטין!'.",
  "37_34": "יעקב קרע את בגדיו, חגר שק על מותניו, והתאבל על בנו ימים רבים.",
  "37_35": "כל בניו וכל בנותיו קמו לנסות לנחם אותו, אך הוא סירב להתנחם ואמר: 'אני ארד אל בני אבל ודואב עד לקבר'; ואביו המשיך לבכות עליו במרירות.",
  "37_36": "ובינתיים במצרים, המדיינים מכרו את יוסף לפוטיפר, שהיה קצין בכיר אצל פרעה ומפקד שומרי הראש (שר הטבחים).",
  "38_1": "באותה תקופה ירד יהודה מעם אחיו (משום שהאשימו אותו במכירת יוסף), ונטה להתגורר ליד איש עדולמי ושמו חירה.",
  "38_2": "יהודה ראה שם את בתו של סוחר כנעני ושמו שוע; הוא נשא אותה לאישה ובא אליה.",
  "38_3": "היא הרתה וילדה בן, והוא קרא לו עֵר.",
  "38_4": "היא הרתה שוב וילדה בן, וקראה לו אוֹנָן.",
  "38_5": "היא הוסיפה וילדה בן שלישי וקראה לו שֵׁלָה; ויהודה היה באותה עת בעיר כזיב כאשר ילדה אותו.",
  "38_6": "יהודה לקח אישה עבור ער בכורו, ושמה תמר.",
  "38_7": "ער בכור יהודה חטא והיה רע בעיני ה', וה' המית אותו.",
  "38_8": "יהודה אמר לאונן: 'בוא אל אשת אחיך, קיים איתה מצוות ייבום והקם זרע שייקרא על שם אחיך המת'.",
  "38_9": "אונן ידע שהצאצא לא ייקרא על שמו, ולכן בכל פעם שבא אל אשת אחיו השחית את זרעו על הארץ כדי שלא לתת זרע לאחיו.",
  "38_10": "מעשהו האגואיסטי היה רע וחמור בעיני ה', וה' המית גם אותו.",
  "38_11": "יהודה אמר לתמר כלתו: 'הישארי כאלמנה בבית אביך עד שבני שלה יגדל', כי חשש בלבו: 'שמא ימות גם הוא כמו שני אחיו'; תמר הלכה והתגוררה בבית אביה.",
  "38_12": "לאחר שנים רבות נפטרה בת שוע אשת יהודה; כאשר הסתיימו ימי אבלו של יהודה, עלה לתמנה יחד עם חירה רעהו העדולמי כדי לפקח על גוזזי צאנו.",
  "38_13": "הודיעו לתמר ואמרו לה: 'הנה חמיך עולה לתמנה לגזוז את צאנו'.",
  "38_14": "תמר הסירה מעליה את בגדי אלמנותה, התכסתה בצעיף והתעטפה בצניעות, והתיישבה בצומת פתח עיניים שעל הדרך לתמנה; כי ראתה ששלה כבר גדל והיא לא ניתנה לו לאישה כמובטח.",
  "38_15": "יהודה ראה אותה וחשב בטעות שהיא אישה מופקרת, כיוון שכיסתה את פניה לחלוטין.",
  "38_16": "הוא סטה מן הדרך לעברה ואמר: 'הבה אבוא אלייך', כי לא ידע שהיא כלתו; היא שאלה: 'מה תיתן לי כשכר אם תבוא אליי?'.",
  "38_17": "הוא אמר: 'אשלח לך גדי עיזים מן הצאן'; היא אמרה: 'בתנאי שתשאיר אצלי ערבון עד שתשלח את הגדי'.",
  "38_18": "הוא שאל: 'איזה ערבון את מבקשת שאשאיר אצלך?'; היא ענתה: 'את טבעת החותם שלך, את פתיל החגורה שלך ואת המקל שבידך'; הוא נתן לה את חפציו, בא אליה והיא הרתה לו.",
  "38_19": "היא קמה והלכה, הסירה את צעיפה וחזרה ללבוש את בגדי אלמנותה.",
  "38_20": "יהודה שלח את גדי העיזים באמצעות חברו העדולמי כדי לקבל חזרה את הערבון מידי האישה, אך חברו לא מצא אותה.",
  "38_21": "הוא שאל את תושבי המקום: 'איפה נמצאת האישה המופקרת שישבה כאן בצומת פתח עיניים על הדרך?', והם השיבו: 'מעולם לא הייתה כאן אישה כזאת'.",
  "38_22": "הוא חזר ליהודה ואמר: 'לא מצאתי אותה, וגם אנשי המקום אמרו שמעולם לא הייתה שם קדשה'.",
  "38_23": "יהודה אמר: 'שתשמור את החפצים לעצמה כדי שלא נהפוך ללעג ולבוז בעיני הבריות; הרי שלחתי את הגדי כפי שהבטחתי, ואתה פשוט לא מצאת אותה'.",
  "38_24": "כעבור כשלושה חודשים הודיעו ליהודה: 'תמר כלתך זנתה, והנה היא בהריון כתוצאה מכך!'; יהודה פסק בכעס: 'הוציאו אותה להורג כדי שתישרף (כבת כהן שזנתה)'.",
  "38_25": "כאשר הובילו אותה להורג, היא שלחה מסר לחמיה מבלי לביישו ברבים ואמרה: 'לאיש שחפצים אלה שייכים לו אני בהריון'; והוסיפה: 'זהה נא בבקשה למי שייכים החותם, הפתילים והמקל האלה!'.",
  "38_26": "יהודה זיהה את חפציו והודה באומץ וביושר: 'היא צודקת ממני! הרי נהגה כך משום שלא נתתי אותה לשלה בני'; ומאז לא הוסיף לשכב איתה.",
  "38_27": "כאשר הגיע מועד לידתה, התברר שיש תאומים בבטנה.",
  "38_28": "במהלך הלידה הושיט אחד התינוקות את ידו החוצה; המיילדת מיהרה וקשרה חוט שני אדום על ידו ואמרה: 'זה יצא ראשון'.",
  "38_29": "אך כאשר החזיר את ידו פנימה, יצא לפתע אחיו; המיילדת קראה בהפתעה: 'איזו פירצה פרצת לעצמך!'; ולכן נקרא שמו פֶּרֶץ (שממנו צמחה שושלת דוד המלך והמשיח).",
  "38_30": "ולאחר מכן יצא אחיו שעל ידו נקשר חוט השני האדום, וקראו לו זָרַח.",
  "39_1": "יוסף הורד למצרים, ופוטיפר – שהיה קצין מצרי בכיר אצל פרעה ומפקד שומרי הראש – קנה אותו מידי הישמעאלים שהורידו אותו לשם.",
  "39_2": "ה' ליווה את יוסף והוא הפך לאיש מצליח ומבורך בכל מעשיו, והוא שירת בבית אדונו המצרי.",
  "39_3": "אדונו ראה בבירור שה' נמצא איתו, ושכל מה שיוסף עושה – ה' מצליח בידו.",
  "39_4": "יוסף מצא חן וחסד בעיני אדונו ושירת אותו בנאמנות; פוטיפר מינה אותו למנהל הראשי של כל ביתו והפקיד את כל רכושו בידיו.",
  "39_5": "מרגע שמינה אותו לנהל את ביתו ואת כל נכסיו, בירך ה' את בית המצרי בזכות יוסף; ברכת ה' שרתה בכל מה שהיה לו, הן בבית והן בשדות.",
  "39_6": "פוטיפר הפקיד את כל רכושו בידי יוסף באופן עיוור, ולא התערב בשום דבר מלבד האוכל שאכל; ויוסף היה יפה תואר ובעל מראה מושלם ומרשים.",
  "39_7": "לאחר זמן מה, נתנה אשת אדונו את עיניה ביוסף ודרשה ממנו בחוצפה: 'שכב איתי!'.",
  "39_8": "אך הוא סירב בתוקף ואמר לאשת אדונו: 'הרי אדוני סומך עליי לחלוטין ואינו בודק מה נעשה בבית, ואת כל רכושו נתן בידי'.",
  "39_9": "'אין איש בעל מעמד גדול ממני בבית הזה, והוא לא מנע ממני שום דבר חוץ מאותך – משום שאת אשתו החוקית; אז כיצד אבצע מעשה נבלה כה גדול ורע, ואחטא לאלוהים?!'.",
  "39_10": "היא המשיכה להפציר ביוסף ולפתות אותו יום אחרי יום, אך הוא סירב בעקביות לשמוע לה, לשכב איתה או אפילו לשהות בקרבתה.",
  "39_11": "יום אחד נכנס יוסף לבית לעשות את מלאכתו השגרתית, ובמקרה לא נכח באותה שעה איש מאנשי הבית בפנים.",
  "39_12": "היא תפסה אותו בבגדו ודרשה: 'שכב איתי עכשיו!'; אך הוא השאיר את בגדו בידה, נמלט במהירות ויצא החוצה.",
  "39_13": "כאשר ראתה שהשאיר את בגדו בידה וברח החוצה,",
  "39_14": "היא קראה בקול לאנשי ביתה ורקמה עלילה שקרית: 'ראו! בעלי הביא לנו עבד עברי כדי להתעלל בנו ולצחוק עלינו; הוא התפרץ אליי כדי לאנוס אותי, וצעקתי בקול גדול'.",
  "39_15": "'וכאשר הוא שמע שהרמתי את קולי וצעקתי, הוא עזב את בגדו אצלי, נמלט וברח החוצה'.",
  "39_16": "היא הניחה את הבגד לצידה כראיה מזויפת, עד שבעלה חזר הביתה.",
  "39_17": "היא סיפרה לו את אותו סיפור שקרי: 'העבד העברי שהבאת לנו ניגש אליי כדי לתקוף אותי ולצחוק בי'.",
  "39_18": "'אך ברגע שהרמתי את קולי וצעקתי, הוא עזב את בגדו אצלי וברח החוצה'.",
  "39_19": "כאשר שמע בעלה את דברי אשתו שטוענת: 'כך וכך עשה לי עבדך', התלקח כעסו מאוד.",
  "39_20": "אדוניו של יוסף תפס אותו והשליך אותו אל בית הסוהר המלכותי – המקום שבו נכלאו אסירי המלך; וכך ישב יוסף בבית הסוהר.",
  "39_21": "אך ה' ליווה את יוסף גם שם, הרעיף עליו חסד, וגרם לו למצוא חן מיוחד בעיני מנהל בית הסוהר.",
  "39_22": "מנהל בית הסוהר הפקיד בידי יוסף את כל האסירים שהיו כלואים שם, וכל מה שנעשה ונוהל שם – נעשה על פי הוראתו של יוסף.",
  "39_23": "מנהל בית הסוהר לא היה צריך לפקח על שום דבר שהיה תחת אחריותו של יוסף, משום שה' היה איתו, וכל מה שיוסף עשה – ה' הצליח בידו.",
  "40_1": "לאחר הדברים האלה, חטאו שר המשקים ושר האופים של מלך מצרים לאדונם מלך מצרים (נמצא זבוב בכוס היין של המלך ואבן בלחמו).",
  "40_2": "פרעה קצף וכעס מאוד על שני שריו הבכירים – על שר המשקים ועל שר האופים.",
  "40_3": "הוא השליך אותם למאסר בבית מפקד שומרי הראש, באותו בית סוהר שבו היה כלוא יוסף.",
  "40_4": "מפקד המשמר מינה את יוסף לשרת אותם ולהשגיח עליהם, והם שהו במאסר תקופה מסוימת.",
  "40_5": "שניהם חלמו חלום באותו לילה – כל אחד חלום מיוחד בעל משמעות ופתרון מדויק משלו, שר המשקים ושר האופים הכלואים בבית הסוהר.",
  "40_6": "יוסף נכנס אליהם בבוקר והתבונן בהם, וראה שהם נסערים, מודאגים ומדוכדכים.",
  "40_7": "הוא שאל את שרי פרעה שהיו איתו במאסר בבית אדונו: 'מדוע פניכם נראות כל כך עצובות ומוטרדות היום?'.",
  "40_8": "הם השיבו לו: 'חלמנו חלום, ואין כאן איש שיודע לפתור אותו'; יוסף אמר להם בביטחון: 'הרי פתרונות החלומות שייכים לאלוהים! ספרו לי בבקשה את חלומותיכם'.",
  "40_9": "שר המשקים סיפר ראשון את חלומו ליוסף ואמר לו: 'בחלומי ראיתי גפן הניצבת לפניי'.",
  "40_10": "'בגפן היו שלושה ענפים; היא החלה ללבלב, מיד עלו ניצניה ופרחיה, ואשכולותיה הבשילו לענבים עסיסיים'.",
  "40_11": "'כוס היין של פרעה הייתה בידי; לקחתי את הענבים, סחטתי אותם לתוך כוס פרעה, והגשתי את הכוס ישירות על כף ידו של פרעה'.",
  "40_12": "יוסף פתר לו מיד ואמר: 'זהו פתרון החלום: שלושת הענפים מסמלים שלושה ימים'.",
  "40_13": "'בעוד שלושה ימים פרעה יזכור אותך לטובה, יחזיר אותך לתפקידך הרם, ואתה תגיש את כוס פרעה בידו בדיוק כפי שנהגת בעבר כששירת כשר המשקים שלו'.",
  "40_14": "'רק אנא זכור אותי לטובה כאשר ייטב לך, ועשה איתי חסד: הזכר אותי בפני פרעה ופעל להוציא אותי מבית הסוהר הזה'.",
  "40_15": "'כי נחטפתי ונגנבתי בעוול מארץ העברים, וגם כאן במצרים לא עשיתי שום פשע שהצדיק את כליאתי בבור הכלא הזה'.",
  "40_16": "שר האופים ראה שיוסף פתר פתרון מוצלח וחיובי, ופנה גם הוא אל יוסף ואמר: 'גם אני ראיתי בחלומי, והנה שלושה סלי קש עם מאפים לבנים מונחים על ראשי'.",
  "40_17": "'ובסל העליון היו מכל מיני מאכלים מובחרים מעשה ידי אופה עבור שולחן פרעה, ועופות השמיים אכלו אותם מתוך הסל שעל ראשי'.",
  "40_18": "יוסף ענה בצער ואמר: 'זהו הפתרון: שלושת הסלים מסמלים שלושה ימים'.",
  "40_19": "'בעוד שלושה ימים יסיר פרעה את ראשך מעליך ויתלה אותך על עץ, ועופות השמיים ינקרו ויאכלו את בשרך מעליך'.",
  "40_20": "ביום השלישי חל יום הולדתו של פרעה, והוא ערך משתה חגיגי לכל שריו ועבדיו; הוא ערך מפקד לשני שריו הבכירים בקרב עבדיו – לשר המשקים ולשר האופים.",
  "40_21": "הוא החזיר את שר המשקים למעמדו ולתפקידו, והוא שב להגיש את הכוס על כף ידו של פרעה.",
  "40_22": "ואילו את שר האופים תלה, בדיוק כפי שיוסף פתר להם מראש.",
  "40_23": "אך שר המשקים לא זכר את יוסף כשהשתחרר, ושכח אותו לחלוטין (משום שיוסף תלה את מבטחו באדם במקום רק בה').",
  "41_1": "בדיוק בתום שנתיים ימים למאסר יוסף, חלם פרעה חלום: הוא עומד על גדת נהר הנילוס (היאור).",
  "41_2": "והנה מתוך הנהר עולות שבע פרות יפות תואר, בריאות ושמנות בשר, והן רעו בנחת בצמחיית האחו שעל שפת המים.",
  "41_3": "מיד אחריהן עלו מן הנהר שבע פרות אחרות – כעורות מראה, כחושות ורזות מאוד, והן נעמדו ליד הפרות הבריאות על שפת הנהר.",
  "41_4": "הפרות הכעורות והרזות בלעו וטרפו את שבע הפרות הבריאות ויפות התואר; ואז התעורר פרעה בבהלה.",
  "41_5": "הוא נרדם שוב וחלם חלום שני: שבע שיבולים מלאות, בריאות וטובות צומחות מקנה תבואה יחיד.",
  "41_6": "ואחריהן צמחו שבע שיבולים דקות, מצומקות ושדופות, שנצרבו ויבשו מרוח קדים מזרחית לוהטת.",
  "41_7": "השיבולים הדקות בלעו את שבע השיבולים המלאות והבריאות; פרעה התעורר והבין שזה היה חלום נבואי.",
  "41_8": "בבוקר הייתה רוחו של פרעה סוערת ומודאגת ביותר; הוא שלח לקרוא לכל מכשפי מצרים ולכל חכמיה, סיפר להם את חלומותיו, אך אף אחד מהם לא הצליח לתת פתרון שהניח את דעתו של פרעה.",
  "41_9": "אז פנה שר המשקים אל פרעה ואמר: 'אני נזכר ומתוודה היום על חטאיי ומשגי עברי:'",
  "41_10": "'פרעה כעס בעבר על עבדיו, וכלא אותי בבית הסוהר של מפקד המשמר – אותי ואת שר האופים'.",
  "41_11": "'ושנינו חלמנו חלום באותו לילה – כל אחד חלום עם משמעות ופתרון שונה ומדויק'.",
  "41_12": "'והיה שם איתנו נער עברי צעיר, משרתו של מפקד המשמר; סיפרנו לו את חלומותינו, והוא פתר לכל אחד מאיתנו את פשר חלומו המדויק'.",
  "41_13": "'ובדיוק כפי שהוא פתר לנו, כך קרה במציאות: אותי החזיר פרעה לתפקידי, ואת שר האופים תלה'.",
  "41_14": "פרעה שלח מיד לקרוא ליוסף, והריצו אותו במהירות מתוך בור הכלא; גילחו את שערותיו, החליפו את בגדיו בבגדים מכובדים, והוא הובא לפני פרעה.",
  "41_15": "פרעה אמר ליוסף: 'חלמתי חלום ואין איש שמסוגל לפתור אותו; ושמעתי עליך שאתה רק שומע חלום ויודע מיד לפענח אותו'.",
  "41_16": "יוסף ענה לפרעה בענווה וביראת שמיים: 'זה אינו בכוחי שלי כלל! אלוהים הוא שיענה ויבשר תשובה של שלום וטובה לפרעה'.",
  "41_17": "פרעה סיפר ליוסף: 'בחלום ראיתי את עצמי עומד על שפת הנילוס'.",
  "41_18": "'ומן הנהר עלו שבע פרות בריאות בשר, יפות מראה, ורעו בעשב האחו'.",
  "41_19": "'ואחריהן עלו שבע פרות אחרות – דלות, כחושות ומכוערות ביותר; מעולם לא ראיתי כיעור ורזון כזה בכל ארץ מצרים!'.",
  "41_20": "'והפרות הרזות והרעות אכלו ובלעו את שבע הפרות הראשונות הבריאות'.",
  "41_21": "'אך גם לאחר שנכנסו לקרבן לא ניכר כלל שהן אכלו משהו, ומראיהן נשאר רע ומכוער כבתחילה; ואז התעוררתי'.",
  "41_22": "'לאחר מכן ראיתי בחלומי שבע שיבולים מלאות ושמנות עולות בקנה אחד'.",
  "41_23": "'ואחריהן צמחו שבע שיבולים צנומות, דקיקות ויבשות מצריבת רוח מזרחית'.",
  "41_24": "'והשיבולים הדקות בלעו את שבע השיבולים הטובות; סיפרתי זאת לחרטומים, ואף אחד מהם לא ידע לומר לי מה משמעות הדבר'.",
  "41_25": "יוסף אמר לפרעה: 'שני חלומותיו של פרעה הם בעצם עניין אחד שלם: את מה שהאלוהים עומד לעשות בקרוב בעולם הוא גילה והודיע לפרעה'.",
  "41_26": "'שבע הפרות הטובות מייצגות שבע שנים, ושבע השיבולים הטובות מייצגות שבע שנים; זהו חלום אחיד ומקביל'.",
  "41_27": "'ושבע הפרות הרזות והרעות שעלו אחריהן מייצגות שבע שנים, וכן שבע השיבולים הריקות והשדופות מרוח קדים – הן שבע שנות רעב כבד'.",
  "41_28": "'זהו בדיוק הדבר שאמרתי לפרעה: את מה שהאלוהים עומד להביא, הוא הראה עכשיו לפרעה'.",
  "41_29": "'הנה עומדות להגיע שבע שנים של שפע תבואה ושובע אדיר בכל ארץ מצרים'.",
  "41_30": "'אך מיד אחריהן יבואו שבע שנות רעב קשות כל כך, שכל השובע והשפע יישכחו לחלוטין בארץ מצרים, והרעב הכבד יכלה את יושבי הארץ'.",
  "41_31": "'אפילו זכר לשפע הקודם לא יורגש בארץ מפני חומרת הרעב שיבוא, כי הוא יהיה כבד וקיצוני מאוד'.",
  "41_32": "'והעובדה שהחלום נשנה לפרעה פעמיים מראה שהגזירה נקבעה ונחתמה סופית מאת האלוהים, ושאלוהים ממהר להוציא אותה לפועל בקרוב'.",
  "41_33": "'ועכשיו, מוטב שפרעה יאתר איש נבון, חכם ובעל כושר ארגון מעולה, וימנה אותו לנהל את כל ארץ מצרים'.",
  "41_34": "'על פרעה לפעול במרץ ולמנות פקידים ומפקחים ברחבי הארץ, שיגבו כמס חמישית מכל יבולי התבואה בארץ מצרים במשך שבע שנות השפע'.",
  "41_35": "'הם יאגרו ויאספו את כל עודפי המזון של השנים הטובות הללו, יצברו תבואת דגן תחת סמכותו של פרעה במחסני חירום בכל עיר ועיר, וישמרו עליהם היטב'.",
  "41_36": "'והמזון הזה ישמש כמאגר חירום לאומי עבור תושבי הארץ לקראת שבע שנות הרעב שיפקדו את מצרים, וכך הארץ לא תושמד ברעב'.",
  "41_37": "ההסבר והתוכנית המעשית מצאו חן רב בעיני פרעה ובעיני כל שריו ועבדיו.",
  "41_38": "פרעה שאל את יועציו: 'האם נוכל למצוא אדם כזה, שניחן ברוח חוכמה אלוהית עליונה?!'.",
  "41_39": "פרעה פנה אל יוסף ואמר: 'מאחר שאלוהים גילה לך את כל הדבר הזה, אין בכל הממלכה אדם חכם ונבון כמוך'.",
  "41_40": "'אתה תנהל את ארמון מלכותי, ועל פי פקודתך יתנהל כל עמי; רק בכיסא המלוכה עצמו אהיה עליון ממך'.",
  "41_41": "פרעה הכריז רשמית בפני יוסף: 'ראה, מיניתי אותך למשנה למלך ולשליט על כל ארץ מצרים'.",
  "41_42": "פרעה הסיר את טבעת החותם המלכותית מידו וענד אותה על ידו של יוסף, הלביש אותו בגדי פשתן מובחרים (שש מלכותי), וענד שרשרת זהב מפוארת על צווארו.",
  "41_43": "הוא הרכיב אותו במרכבת המשנה השמורה לשליט השני בממלכה, והכרוזים קראו לפניו: 'אַבְרֵךְ!' (אב בחכמה ושליט מורם מעם); וכך הוצב כשליט בלעדי על כל ארץ מצרים.",
  "41_44": "פרעה הדגיש בפני יוסף: 'אני פרעה המלך, אך בלעדי אישורך והוראתך לא ירים איש את ידו או את רגלו (לא יעשה שום צעד) בכל רחבי מצרים'.",
  "41_45": "פרעה העניק ליוסף שם מצרי של כבוד: 'צָפְנַת פַּעְנֵחַ' (מפענח צפונות ונסתרות), והשיא לו לאישה את אסנת בת פוטי פרע, שהיה כהן ונסיך העיר און; ויוסף יצא לפקח על כל ארץ מצרים.",
  "41_46": "יוסף היה בן שלושים שנה כאשר התייצב בפני פרעה מלך מצרים; יוסף יצא מלפני פרעה וסייר בכל רחבי מצרים לארגן את האגירה.",
  "41_47": "במשך שבע שנות השפע הניבה האדמה כמויות תבואה אדירות ועצומות במלוא הקומצים.",
  "41_48": "יוסף אסף את כל עודפי המזון של שבע השנים הללו במצרים ואחסן את המזון בערים; את תבואת השדות שהקיפו כל עיר אגר במחסניה הפנימיים.",
  "41_49": "יוסף צבר תבואת בר בכמות אדירה כמו חול שפת הים, עד שבסופו של דבר הפסיקו לספור ולרשום כי הכמות הייתה בלתי ניתנת למדידה.",
  "41_50": "עוד בטרם החלה שנת הרעב הראשונה, נולדו ליוסף שני בנים מאסנת בת פוטי פרע כהן און.",
  "41_51": "יוסף קרא לבכור מְנַשֶּׁה ואמר: 'כי אלוהים השכיח ממני (נַשַּׁנִי) את כל סבלי ואת כל בית אבי'.",
  "41_52": "ולבן השני קרא אֶפְרָיִם ואמר: 'כי אלוהים הפרה אותי והצליח אותי בארץ גלותי ועוניי'.",
  "41_53": "שבע שנות השפע והשובע שהיו בארץ מצרים הגיעו לסיומן.",
  "41_54": "ושבע שנות הרעב החלו לפקוד את העולם בדיוק כפי שחזה יוסף; רעב כבד השתרר בכל הארצות השכנות, אך בכל ארץ מצרים היה לחם ומזון שמור.",
  "41_55": "כאשר אזל המזון הפרטי של תושבי מצרים והם רעבו, זעק העם אל פרעה ללחם; פרעה ענה לכל המצרים: 'לכו אל יוסף, ועשו בדיוק כל מה שיאמר לכם'.",
  "41_56": "והרעב התפשט על פני כל שטח הארץ; יוסף פתח את כל מחסני התבואה ומכר תבואה למצרים, והרעב הלך והחמיר בכל רחבי מצרים.",
  "41_57": "תושבי כל הארצות השכנות הגיעו למצרים כדי לקנות תבואה מיוסף, כיוון שהרעב היה כבד וקשה בכל העולם.",
  "42_1": "יעקב ראה שיש אספקת תבואה הנמכרת במצרים, ואמר לבניו: 'מדוע אתם יושבים ומביטים זה בזה בחוסר אונים (או נראים שבעים מול השכנים)?'.",
  "42_2": "הוא אמר: 'הנה שמעתי שמוכרים תבואה במצרים; רדו לשם וקנו עבורנו מזון, כדי שנחיה ולא נמות ברעב'.",
  "42_3": "עשרת אחי יוסף ירדו למצרים כדי לקנות דגן.",
  "42_4": "אך את בנימין, אחיו של יוסף מאותה אם, לא שלח יעקב עם אחיו כי חשש בלבו: 'שמא יקרה לו אסון בדרך'.",
  "42_5": "בני ישראל הגיעו לקנות תבואה בין שאר השיירות שהגיעו, משום שהרעב שרר בכבדות גם בארץ כנען.",
  "42_6": "ויוסף היה השליט העליון על כל הארץ, והוא שפיקח על חלוקת ומכירת התבואה לכל האנשים; אחי יוסף נכנסו והשתחוו לפניו אפיים ארצה.",
  "42_7": "יוסף ראה את אחיו וזיהה אותם מיד, אך התנהג אליהם כזר ודיבר איתם בנוקשות; הוא שאל אותם: 'מאין הגעתם?', והם השיבו: 'מארץ כנען, כדי לקנות אוכל'.",
  "42_8": "יוסף הכיר את אחיו היטב, אך הם לא זיהו אותו כלל (כי עזבם כנער ללא זקן, וכעת עמד לפניהם כשליט מצרי עטור הוד מלכות).",
  "42_9": "יוסף נזכר בחלומות שחלם עליהם בעבר, ורצה להביא אותם לתשובה; הוא אמר להם בתקיפות: 'מרגלים אתם! באתם לבדוק את נקודות התורפה והגבולות החשופים של הארץ!'.",
  "42_10": "הם התגוננו ואמרו: 'בשום אופן לא, אדוני! עבדיך באו אך ורק לקנות מזון למשפחותינו'.",
  "42_11": "'כולנו בנים של איש אחד; אנשים ישרים והגונים אנחנו, ועבדיך מעולם לא היו מרגלים'.",
  "42_12": "אך הוא התעקש ואמר להם: 'לא נכון! באתם כדי לחפש את חולשות הארץ'.",
  "42_13": "הם הסבירו בפירוט: 'אנחנו שנים עשר אחים, עבדיך, בני איש אחד בארץ כנען; הצעיר נמצא כעת עם אבינו בבית, ואחד האחים נעלם ואיננו בין החיים'.",
  "42_14": "יוסף אמר להם: 'זה בדיוק מה שטענתי כלפיכם כשקבעתי שאתם מרגלים'.",
  "42_15": "'בדרך הזו תיבחנו: בחיי פרעה! לא תצאו מן המקום הזה אלא אם כן יגיע אחיכם הצעיר לכאן!'.",
  "42_16": "'שלחו אחד מכם שילך ויביא את אחיכם, ואתם תישארו במעצר; כך ייבדקו דבריכם אם אמת בפיכם, ואם לא – בחיי פרעה, מרגלים אתם!'.",
  "42_17": "הוא הכניס את כולם למשמר בבית הכלא לשלושה ימים.",
  "42_18": "ביום השלישי פנה אליהם יוסף ואמר: 'עשו את הדבר הבא וכך תישארו בחיים, שהרי אני אדם ירא אלוהים ומקפיד על צדק:'",
  "42_19": "'אם אנשים ישרים אתם – יישאר אחד מאחיכם אסור כאן בבית המעצר, ואתם שאר האחים קחו את התבואה שקניתם להשביע את רעבון משפחותיכם'.",
  "42_20": "'ואת אחיכם הצעיר תביאו אליי, וכך יאומתו דבריכם ולא תוצאו להורג'; והם הסכימו לתנאי.",
  "42_21": "האחים אמרו איש אל רעהו בחרטה עמוקה: 'אכן אשמים אנחנו על מה שעוללנו לאחינו יוסף! ראינו את מצוקתו הנפשית הקשה כשהתחנן אלינו בדמעות ולא הקשבנו לו, ולכן פקדה אותנו הצרה הנוראה הזאת'.",
  "42_22": "ראובן אמר להם בתוכחה: 'הלוא אמרתי לכם אז: אל תחטאו בילד! אך אתם סירבתם להקשיב; והנה עכשיו נדרש מאיתנו דין דמו!'.",
  "42_23": "הם לא העלו על דעתם שיוסף מבין את שפתם, משום שהמתורגמן (מנשה בנו) תיווך ביניהם.",
  "42_24": "יוסף פנה הצידה מהם ובכה מהתרגשות; לאחר מכן חזר אליהם, דיבר איתם, לקח מביניהם את שמעון ואסר אותו באזיקים לנגד עיניהם.",
  "42_25": "יוסף הורה בחשאי למלא את שקיהם בתבואה, להחזיר את כספו של כל אחד לתוך שקו, ולספק להם צידה לדרך; וכך עשו עבורם.",
  "42_26": "הם העמיסו את שקי התבואה על חמוריהם ויצאו לדרך.",
  "42_27": "בחניון הלילה פתח אחד מהם את שקו כדי לתת מספוא לחמורו, ונדהם לראות את כספו מונח ממש בפתח השק.",
  "42_28": "הוא קרא בבהלה לאחיו: 'הכסף שלי הוחזר, והנה הוא כאן בתוך שקי!'; לבם נפל מרוב פחד והם רעדו ואמרו איש לרעהו: 'מה הדבר הזה שאלוהים מעולל לנו?!'.",
  "42_29": "הם הגיעו אל יעקב אביהם לארץ כנען, וסיפרו לו בפרוטרוט את כל מה שעבר עליהם:",
  "42_30": "'האיש שהוא שליט הארץ דיבר איתנו בנוקשות רבה, והאשים אותנו בריגול אחרי הארץ'.",
  "42_31": "'ענינו לו: אנשים ישרים אנחנו ומעולם לא עסקנו בריגול'.",
  "42_32": "'שנים עשר אחים אנחנו בני אבינו; אחד נעלם, והצעיר נמצא כעת עם אבינו בארץ כנען'.",
  "42_33": "'אמר לנו האיש אדוני הארץ: כך אדע שאתם דוברי אמת: השאירו אצלי אח אחד, קחו מזון לרעבון בתיכם ולכו לדרככם'.",
  "42_34": "'והביאו את אחיכם הצעיר אליי כדי שאדע שאינכם מרגלים אלא אנשים ישרים; אז אחזיר לכם את אחיכם ותוכלו לנוע ולסחור בחופשיות בארץ'.",
  "42_35": "כאשר רוקנו את שקיהם, גילה כל אחד מהם שצרור כספו מונח בתוך שקו; הם ואביהם ראו את צרורות הכסף ונתקפו פחד גדול.",
  "42_36": "יעקב אביהם הטיח בהם בכאב נורא: 'אותי השכלתם מילדיי! יוסף איננו, שמעון שבוי במצרים, ועכשיו אתם רוצים לקחת גם את בנימין?! כל הצרות האלה נופלות אך ורק עליי!'.",
  "42_37": "ראובן ניסה להרגיע את אביו ואמר: 'תוכל להמית את שני בניי אם לא אחזיר אותו אליך; הפקד אותו בידי ואני ערב להחזיר אותו שלם אליך'.",
  "42_38": "אך יעקב סירב בתוקף ואמר: 'בני לא ירד איתכם בשום אופן! הרי אחיו מת והוא נשאר לבדו מאמו; אם יקרה לו אסון בדרך שבה תלכו – תורידו את שיבתי ביגון ובאבל כבד אל הקבר'.",
  "43_1": "והרעב המשיך להכביד קשות בכל ארץ כנען.",
  "43_2": "כאשר כילו לאכול את כל התבואה שהביאו ממצרים, אמר להם אביהם: 'חזרו למצרים וקנו לנו מעט אוכל'.",
  "43_3": "יהודה אמר לו בנחרצות: 'האיש השליט הזהיר אותנו במפורש בהתראה חמורה: לא תורשו לראות את פניי אם אחיכם הצעיר לא יבוא איתכם'.",
  "43_4": "'אם אתה מסכים לשלוח את אחינו איתנו – נרד ברצון ונקנה עבורך אוכל'.",
  "43_5": "'אך אם אינך שולח אותו – לא נרד! כי האיש הבהיר לנו: לא תראו את פניי ללא אחיכם איתכם'.",
  "43_6": "ישראל אמר בצער: 'מדוע גרמתם לי רעה כה גדולה כשסיפרתם לאיש שיש לכם עוד אח?'.",
  "43_7": "הם ענו: 'האיש חקר ודרש ביסודיות עלינו ועל משפחתנו ושאל: האם אביכם עדיין בחיים? האם יש לכם עוד אח?; וענינו לו בתמימות לפי שאלותיו; האם יכולנו לחזות מראש שהוא ידרוש: הורידו את אחיכם למצרים?!'.",
  "43_8": "יהודה פנה בתקיפות ובאחריות לישראל אביו ואמר: 'שלח את הנער תחת השגחתי, ונקום ונצא מיד לדרך, כדי שנחיה כולנו ולא נגווע ברעב – אנחנו, אתה וכל טפנו הקטנים'.",
  "43_9": "'אני מקבל על עצמי ערבות אישית מוחלטת עליו, ומידי תדרוש דין וחשבון; אם לא אחזיר אותו אליך ואציב אותו חי ובריא לפניך – אהיה נחשב כחוטא כלפיך כל ימי חיי'.",
  "43_10": "'הרי אלמלא התעכבנו והשתהינו כל כך, כבר היינו יכולים לחזור פעמיים עם מזון!'.",
  "43_11": "ישראל אביהם נכנע ואמר להם: 'אם זה המצב ואין ברירה, עשו כך: קחו ממיטב פירות ותוצרת הארץ המובחרת בכליכם והורידו לאיש כמנחת כבוד: מעט צרי, מעט דבש, בשמי נכאת ולוט, בוטנים (פיסטוקים) ושקדים'.",
  "43_12": "'קחו בידכם סכום כפול של כסף, ואת הכסף שהוחזר בפי שקיכם החזירו בידכם במלואו – אולי הייתה זו רק טעות שנפלה'.",
  "43_13": "'וקחו את אחיכם בנימין, קומו ושובו אל האיש'.",
  "43_14": "'ואל שדי ירעיף עליכם רחמים לפני האיש, ויגרום לו לשחרר עבורכם את אחיכם השני (שמעון) ואת בנימין; ואני, אם נגזר עליי להישאר שכול מילדיי – שכול אהיה'.",
  "43_15": "האנשים לקחו את המנחה היקרה, לקחו בידם כסף כפול, ולקחו את בנימין; הם קמו, ירדו למצרים והתייצבו מול יוסף.",
  "43_16": "יוסף ראה את בנימין איתם, והורה מיד למנהל ביתו: 'הכנס את האנשים האלה אל הבית, שחט בשר בקר והכן סעודה גדולה, כי האנשים האלה יסעדו איתי בצהריים'.",
  "43_17": "האיש ביצע בדיוק את פקודת יוסף, והכניס את האחים אל ביתו הפרטי של יוסף.",
  "43_18": "האחים נתקפו פחד וחרדה על שהוכנסו לתוך בית יוסף, ואמרו איש לרעהו: 'בגלל הכסף שהוחזר בשקינו בפעם הקודמת מביאים אותנו לכאן – כדי לעלול עלינו עלילה, להתנפל עלינו, לקחת אותנו כעבדים ולהחרים את חמורינו!'.",
  "43_19": "הם ניגשו אל מנהל משק ביתו של יוסף, ושוחחו איתו בדאגה כבר בפתח הבית.",
  "43_20": "הם אמרו לו בהתנצלות: 'סלח לנו אדוני! ירדנו בפעם הראשונה אך ורק במטרה לקנות מזון'.",
  "43_21": "'וכאשר הגענו לחניון הלילה ופתחנו את שקינו, גילינו שכל כספו של כל אחד מאיתנו מונח במלואו ובמשקלו בפתח שקו; והנה הבאנו אותו כעת חזרה בידינו להשיבו'.",
  "43_22": "'וכן הבאנו בידנו כסף נוסף לקניית אוכל; אין לנו שום מושג מי שם את הכסף בשקינו!'.",
  "43_23": "המנהל הרגיע אותם ואמר: 'הירגעו ואל תפחדו! אלוהיכם ואלוהי אביכם זימן לכם מטמון בשקיכם; הכסף המקורי שלכם אכן הגיע אליי במלואו'; והוא הוציא אליהם את שמעון לחופשי.",
  "43_24": "האיש הכניס את האחים לתוך בית יוסף, נתן מים והם רחצו את רגליהם מאבק הדרך, וסיפק מספוא עשיר לחמוריהם.",
  "43_25": "הם ערכו והכינו את המנחה לקראת בואו של יוסף בצהריים, כיוון ששמעו ששם הם עתידים לסעוד.",
  "43_26": "כאשר יוסף נכנס הביתה, הם הגישו לו בכבוד את המנחה שבידם, והשתחוו לו עד הקרקע.",
  "43_27": "יוסף דרש בשלומם בחמימות ושאל: 'האם שלום לאביכם הזקן שסיפרתם עליו? האם הוא עדיין חי ובריא?'.",
  "43_28": "הם השיבו: 'שלום לעבדך לאבינו, הוא עדיין חי ובריא', והם כרעו ברך והשתחוו לו שוב.",
  "43_29": "יוסף נשא את עיניו והבחין בבנימין אחיו מאותה אם (רחל), ושאל בהתרגשות: 'האם זהו אחיכם הצעיר שסיפרתם לי עליו?'; ובירך אותו: 'אלוהים יחון ויברך אותך, בני'.",
  "43_30": "יוסף מיהר לצאת כי רגשותיו וגעגועיו געשו ונכמרו כלפי אחיו וחיפש מקום לבכות; הוא נכנס לחדרו הפנימי ובכה שם בדמעות חמות.",
  "43_31": "הוא רחץ את פניו, יצא החוצה כשהוא מתאפק בכל כוחו, והורה למשרתים: 'הגישו את הסעודה'.",
  "43_32": "המשרתים ערכו שולחן נפרד ליוסף לבדו, שולחן לאחים לבדם ושולחן למצרים שאכלו איתו לבדם; שכן המצרים נמנעו לחלוטין מלאכול יחד עם עברים באותו שולחן, כי הדבר נחשב לתועבה בעיניהם.",
  "43_33": "יוסף הושיב את האחים לפניו בדיוק לפי סדר לידתם – מהבכור כפי בכורתו ועד הצעיר לפי גילו (באמצעות גביע הכסף כאילו ניחש); והאחים הביטו זה בזה בהשתאות ופליאה עצומה.",
  "43_34": "יוסף שלח מנות מכובדות משולחנו אליהם, ומנתו של בנימין הייתה גדולה פי חמישה ממנות כל האחרים; הם שתו ושמחו איתו ללא דאגה (לאחר שלא שתו יין מאז מכירתו).",
  "44_1": "יוסף ציווה בסתר על מנהל ביתו: 'מלא את שקי האנשים במזון ככל שיוכלו לשאת, והחזר את כספו של כל איש בפתח שקו'.",
  "44_2": "'ואת גביעי האישי, גביע הכסף המיוחד, תטמין בפתח שקו של הצעיר (בנימין), יחד עם כסף התבואה שלו'; והמנהל עשה בדיוק כפי שהורה לו יוסף.",
  "44_3": "עם עלות אור הבוקר שולחו האחים לשלום, והם יצאו לדרך עם חמוריהם.",
  "44_4": "הם רק יצאו משערי העיר וטרם הספיקו להתרחק, כאשר יוסף פנה למנהל ביתו ואמר: 'קום ורדוף מיד אחרי האנשים! כשתשיג אותם, אמור להם: מדוע גמלתם רעה תחת טובה?!'.",
  "44_5": "'הלוא זהו הגביע שבו שותה אדוני ובו הוא נוהג לנחש ולחזות! מעשה רע ונפשע עשיתם!'.",
  "44_6": "המנהל השיג אותם וחזר בפניהם בדיוק על המילים הללו.",
  "44_7": "הם הגיבו בתדהמה וזעזוע: 'מדוע אדוני מדבר בצורה כזאת? חלילה לעבדיך מלעשות מעשה שפל שכזה!'.",
  "44_8": "'הרי אפילו את הכסף שמצאנו בפי שקינו החזרנו לך ביוזמתנו מארץ כנען! אז איך נעלה על הדעת לגנוב מבית אדונך כסף או זהב?!'.",
  "44_9": "'זה שיימצא הגביע אצלו מבין עבדיך – יומת מיד, וגם כולנו נהיה עבדים לאדוני!'.",
  "44_10": "המנהל אמר: 'אקבל את עקרון דבריכם, אך בהקלה: רק זה שיימצא הגביע אצלו יהיה לי לעבד, ואילו אתם שאר האחים תהיו נקיים ורשאים ללכת'.",
  "44_11": "הם מיהרו בביטחון מלא, הורידו איש איש את שקו ארצה ופתחו את השקים לחיפוש.",
  "44_12": "המנהל ערך חיפוש יסודי: הוא פתח בשקו של הבכור ראובן וסיים בשקו של הצעיר – והגביע נמצא בתוך שקו של בנימין!",
  "44_13": "האחים נחרדו וקרעו את בגדיהם באבל וייאוש מוחלט; כל אחד העמיס חזרה את משאו על חמורו, וכולם שבו יחד העירה.",
  "44_14": "יהודה ואחיו נכנסו לביתו של יוסף כשהוא עדיין שהה שם, ונפלו לפניו עד הקרקע בשברון לב.",
  "44_15": "יוסף הטיח בהם: 'איזה מעשה חמור עשיתם! האם לא ידעתם שאדם רם מעלה כמוני מסוגל לנחש ולגלות כל מעשה נסתר?!'.",
  "44_16": "יהודה ניגש וענה בחוסר אונים: 'מה נוכל לומר לאדוני? מה נדבר ואיך נוכל להצטדק? אלוהים מצא וחשף את עווננו הקדום (על מכירת יוסף); הנה כולנו עבדים לאדוני – גם אנחנו וגם זה שהגביע נמצא בידו'.",
  "44_17": "אך יוסף השיב בנחרצות: 'חלילה לי מלעשות עוול כזה! רק האיש שהגביע נמצא בידו יהיה לי לעבד, ואילו אתם שאר האחים עלו לשלום אל אביכם'.",
  "44_18": "יהודה ניגש אל יוסף באומץ וברגש רב ואמר: 'אנא אדוני, יורשה נא לעבדך לומר דברים אחדים באוזניך, ואל יבער כעסך בעבדך, שהרי אתה חשוב ושקול בעינינו בדיוק כמו פרעה המלך'.",
  "44_19": "'אדוני שאל בעבר את עבדיו ובירר: האם יש לכם עוד אב או אח?'.",
  "44_20": "'וענינו לאדוני ביושר: יש לנו אב זקן, וילד שנולד לו לעת זקנתו – נער צעיר; אחיו מאותה אם מת, והוא נשאר יחיד לאמו ואביו קשור אליו באהבה עזה'.",
  "44_21": "'ואתה פקדת על עבדיך: הורידו אותו אליי למצרים כדי שאוכל לראותו בעיניי'.",
  "44_22": "'אמרנו לאדוני שהנער אינו מסוגל להיפרד מאביו, כי אם ייפרד מאביו – אביו לא ישרוד וימות מרוב צער'.",
  "44_23": "'אך אתה הזהרת את עבדיך: אם אחיכם הצעיר לא ירד איתכם, לא תורשו לראות את פניי שוב'.",
  "44_24": "'וכאשר עלינו חזרה אל אבינו עבדך, מסרנו לו את כל דברי אדוני'.",
  "44_25": "'וכאשר אבינו אמר לנו: חזרו וקנו לנו מעט מזון'.",
  "44_26": "'השבנו לו: לא נוכל לרדת! רק אם אחינו הצעיר יבוא איתנו נרד, כי איננו רשאים לראות את פני האיש ללא אחינו הקטן איתנו'.",
  "44_27": "'ואבינו עבדך אמר לנו בכאב: אתם יודעים היטב שרק שני בנים ילדה לי אשתי האהובה (רחל)'.",
  "44_28": "'האחד יצא מאיתי ונעלם, ואמרתי בלבי: ודאי נטרף בפי חיית טרף, ומאז ועד היום לא ראיתי אותו'.",
  "44_29": "'ואם תיקחו עכשיו גם את הבן הזה מעימיי ויקרה לו אסון בדרך – תורידו את שיבתי ביגון ובסבל נורא אל הקבר'.",
  "44_30": "'ועכשיו, אם אגיע אל אבינו עבדך והנער איננו איתנו – והרי נפשו קשורה בנפשו של הנער בעבותות אהבה'.",
  "44_31": "'ברגע שיבחין שהנער איננו, הוא ימות מיד מרוב שברון לב, ועבדיך יורידו את שיבת אבינו הזקן באבל כבד אל השאול'.",
  "44_32": "'שהרי עבדך קיבל על עצמו ערבות אישית מוחלטת על הנער כלפי אבי ואמרתי לו: אם לא אחזיר אותו אליך – אהיה חוטא כלפיך כל ימי חיי'.",
  "44_33": "'ולכן כעת, אנא יורשה לי להישאר כאן כעבד לאדוני במקום הנער, והנער יעלה חזרה עם שאר אחיו לאביו!'.",
  "44_34": "'כי איך אוכל לעלות אל אבי והנער איננו איתי?! אינני מסוגל לחזות באסון ובשברון הלב הנורא שיפקוד את אבי!'.",
  "45_1": "יוסף לא יכול היה עוד לעצור את רגשותיו ודמעותיו בפני כל פקידיו ומשרתיו הניצבים סביבו, וצעק: 'הוציאו כל איש זר מעליי!'; ואף אדם לא נשאר בחדר כאשר יוסף התוודע אל אחיו.",
  "45_2": "הוא פרץ בבכי חזק ורועם, עד שהמצרים שמעו את קולו מחוץ לחדר, והשמועה הגיעה גם אל ארמון פרעה.",
  "45_3": "יוסף פנה אל אחיו הנדהמים ואמר: 'אני יוסף! האם אבי עדיין חי?!'; אך אחיו נאלמו דום ולא היו מסוגלים להוציא מילה מפיהם מרוב תדהמה ובושה.",
  "45_4": "יוסף פנה אליהם בחום ואמר: 'אנא, גשו אליי קרוב'; וכאשר ניגשו, אמר להם: 'אני יוסף אחיכם, אותו אחד שמכרתם למצרים'.",
  "45_5": "'ועכשיו, אל תצטערו ואל תכעסו על עצמכם על כך שמכרתם אותי לכאן, כי בעצם לשם הצלת חיים שלח אותי אלוהים לפניכם'.",
  "45_6": "'שהרי זה שנתיים ימי הרעב שוררים בקרב הארץ, ונותרו עוד חמש שנים שבהן לא תהיה שום חרישה ושום קציר'.",
  "45_7": "'אלוהים שלח אותי לפניכם כדי להבטיח את המשך קיומכם בארץ ולהציל את חייכם בהצלה גדולה ונשגבת'.",
  "45_8": "'לכן לא אתם הם ששלחתם אותי לכאן אלא האלוהים בהשגחתו; והוא מינה אותי ליועץ בכיר (לאב) לפרעה, למנהל של כל ארמונו ולשליט על כל ארץ מצרים'.",
  "45_9": "'מהרו לעלות אל אבי ואמרו לו: כה אמר בנך יוסף: אלוהים שם אותי לשליט על כל מצרים; רד אליי מיד ואל תשתהה'.",
  "45_10": "'אתה תתיישב בחבל ארץ גושן ותהיה קרוב אליי – אתה, בניך, נכדיך, צאנך, בקרך וכל אשר לך'.",
  "45_11": "'ואני אכלכל ואפרנס אותך שם לאורך חמש שנות הרעב שנותרו, כדי שלא תרד לעוני ומחסור אתה, ביתך וכל רכושך'.",
  "45_12": "'והנה עיניכם רואות בעיניים, ועיני אחי בנימין עדות, שפי מדבר אליכם בשפתכם ללא מתורגמן'.",
  "45_13": "'ספרו לאבי על כל מעמדי וכבודי במצרים ועל כל מה שראיתם כאן במו עיניכם, ומיהרו והורידו את אבי לכאן'.",
  "45_14": "יוסף נפל על צווארו של בנימין אחיו ובכה מהתרגשות, ובנימין בכה על צווארו.",
  "45_15": "הוא נישק לכל שאר אחיו ובכה עליהם בחיבוק; ורק לאחר מכן השתחררו אחיו מההלם והחלו לשוחח איתו.",
  "45_16": "הידיעה הגיעה לארמון פרעה ונאמר: 'אחי יוסף הגיעו!'; והדבר שימח מאוד את פרעה ואת כל שריו ועבדיו.",
  "45_17": "פרעה אמר ליוסף: 'אמור לאחיך: עשו כך – העמיסו תבואה על בהמותיכם וצאו מיד לארץ כנען'.",
  "45_18": "'קחו את אביכם ואת משפחותיכם ובואו אליי למצרים; אני אתן לכם את מיטב אדמות ארץ מצרים, ותיהנו משפע שמני הארץ'.",
  "45_19": "'והנך מצווה להורות להם: קחו איתכם ממצרים שיירת עגלות משא מרווחות להסעת ילדיכם ונשותיכם, הסיעו בהן את אביכם ובואו לכאן'.",
  "45_20": "'ואל תצטערו על כלי הבית והחפצים הכבדים שתשאירו מאחור, כי מיטב כל ארץ מצרים עומד לרשותכם'.",
  "45_21": "בני ישראל ביצעו את ההוראות בשמחה; יוסף סיפק להם עגלות לפי פקודת פרעה, וצייד אותם בשפע צידה ומזון לדרך.",
  "45_22": "לכל אחד מהאחים נתן חליפת בגדים מכובדת וחדשה, ואילו לבנימין העניק שלוש מאות שקלי כסף וחמש חליפות בגדים מפוארות.",
  "45_23": "ולאביו שלח במיוחד: עשרה חמורים עמוסים ממיטב מעדני מצרים, ועשר אתונות עמוסות בתבואה, לחם ומזון מזין לאביו לקראת המסע.",
  "45_24": "יוסף ליווה את אחיו לשלום בצאתם לדרך, ואמר להם בהדרכה: 'אל תריבו ואל תתווכחו בדרך (מי מכם היה אשם במכירתי, ואל תמהרו בהליכה מסוכנת)'.",
  "45_25": "הם עלו ממצרים והגיעו לארץ כנען אל יעקב אביהם.",
  "45_26": "הם בישרו לו בהתרגשות: 'יוסף עודנו חי, והוא אפילו השליט והמושל על כל ארץ מצרים!'; אך לבו של יעקב קפא ונאלם מדום, כי לא היה מסוגל להאמין להם.",
  "45_27": "הם חזרו ומסרו לו את כל הדברים המדויקים שיוסף אמר להם; וכאשר ראה יעקב את העגלות המלכותיות ששלח יוסף להסיע אותו (רמז לסוגיית עגלה ערופה שלמדו יחד לפני פרידתם) – שבה רוח הקודש והנבואה לשרות על יעקב אביהם.",
  "45_28": "ישראל קרא בשמחה עצומה: 'רב לי האושר! יוסף בני עודנו חי! אלך ואראה אותו במו עיניי לפני שאמות'.",
  "46_1": "ישראל יצא למסעו עם כל אשר לו והגיע לבאר שבע, וזבח שם זבחי תודה לה' אלוהי יצחק אביו.",
  "46_2": "אלוהים דיבר אל ישראל במראות הלילה וקרא: 'יעקב! יעקב!', והוא ענה: 'הנני, אני מוכן'.",
  "46_3": "אלוהים אמר לו: 'אני האל, אלוהי אביך; אל תפחד מלרדת למצרים, כי לעם גדול וחזק אהפוך אותך שם'.",
  "46_4": "'אני ארד איתך בהשגחתי למצרים, ואני גם אעלה את צאצאיך בחזרה לארץ; ויוסף בנך יניח את ידו על עיניך בעת פטירתך'.",
  "46_5": "יעקב קם מבאר שבע; בני ישראל הסיעו את יעקב אביהם, את ילדיהם ואת נשיהם בעגלות שפרעה שלח להסיעו בהן.",
  "46_6": "הם לקחו את עדרי מקניהם ואת כל הרכוש שרכשו בארץ כנען והגיעו למצרים – יעקב וכל צאצאיו איתו.",
  "46_7": "את בניו, נכדיו, בנותיו ונכדותיו – את כל צאצאיו הביא איתו למצרים.",
  "46_8": "ואלה שמות בני ישראל שהגיעו למצרים, יעקב ובניו: בכור יעקב ראובן.",
  "46_9": "ובני ראובן: חנוך, פלוא, חצרון וכרמי.",
  "46_10": "ובני שמעון: ימואל, ימין, אוהד, יכין, צוחר, ושאול בן הכנענית.",
  "46_11": "ובני לוי: גרשון, קהת ומררי.",
  "46_12": "ובני יהודה: ער, אונן, שלה, פרץ וזרח (ער ואונן מתו בארץ כנען); ובני פרץ היו חצרון וחמול.",
  "46_13": "ובני יששכר: תולע, פווה, יוב ושמרון.",
  "46_14": "ובני זבולון: סרד, אילון ויחללאל.",
  "46_15": "אלה הם צאצאי לאה שילדה ליעקב בפדן ארם יחד עם דינה בתו; סך כל נפשות בניו ובנותיו עמד על שלושים ושלוש.",
  "46_16": "ובני גד: צפיון, חגי, שוני, אצבון, ערי, ארודי ואראלי.",
  "46_17": "ובני אשר: ימנה, ישוה, ישוי, בריעה וסרח אחותם; ובני בריעה היו חבר ומלכיאל.",
  "46_18": "אלה צאצאי זלפה שנתן לבן ללאה בתו, ואותם ילדה ליעקב – שש עשרה נפשות.",
  "46_19": "בני רחל אשת יעקב: יוסף ובנימין.",
  "46_20": "וביוזמת ה' נולדו ליוסף בארץ מצרים מאסנת בת פוטי פרע כהן און: מנשה ואפרים.",
  "46_21": "ובני בנימין: בלע, בכר, אשבל, גרא, נעמן, אחי, ראש, מופים, חופים וארד (עשרה בנים שקראם על שמות קורות יוסף אחיו).",
  "46_22": "אלה הם צאצאי רחל שנולדו ליעקב – סך הכל ארבע עשרה נפשות.",
  "46_23": "ובני דן: חושים.",
  "46_24": "ובני נפתלי: יחצאל, גוני, יצר ושילם.",
  "46_25": "אלה צאצאי בלהה שנתן לבן לרחל בתו, ואותם ילדה ליעקב – סך הכל שבע נפשות.",
  "46_26": "סך כל הנפשות שהגיעו עם יעקב למצרים יוצאי חלציו, מלבד נשות בני יעקב – ששים ושש נפשות.",
  "46_27": "ובני יוסף שנולדו לו במצרים היו שתי נפשות; סך כל יוצאי בית יעקב שנמנו בבואם למצרים היה שבעים נפש (בצירוף יוכבד שנולדה בין החומות בכניסה למצרים).",
  "46_28": "יעקב שלח את יהודה לפניו אל יוסף כדי להכין ולהקים מראש בית הוראה וישיבה בגושן, והם הגיעו לארץ גושן.",
  "46_29": "יוסף רתם את מרכבתו המלכותית בעצמו ועלה לקראת ישראל אביו לגושן; הוא התייצב לפניו, נפל על צוואריו ובכה על צווארו זמן ממושך (בעוד יעקב קורא קריאת שמע).",
  "46_30": "ישראל אמר אל יוסף: 'מעתה אוכל למות בשלווה ובנחת, לאחר שזכיתי לראות את פניך שוב ולדעת שאתה עדיין חי!'.",
  "46_31": "יוסף אמר לאחיו ולכל בני בית אביו: 'אעלה לארמון ואודיע לפרעה: אחיי וכל משפחת אבי שהיו בארץ כנען הגיעו אליי'.",
  "46_32": "'ואסביר לו: האנשים הם רועי צאן ובעלי מקנה מנעוריהם, ואת צאנם, בקרם וכל רכושם הביאו איתם'.",
  "46_33": "'וכאשר פרעה יזמין אתכם וישאל אתכם: מהו משלח ידכם ומקצועכם?'",
  "46_34": "'תענו לו: אנשי מקנה היינו אנו ועבדיך מנעורינו ועד היום, הן אנו והן אבותינו; עשו כך כדי שהוא יושיב אתכם בנפרד בארץ גושן הפורייה, משום שכל רועה צאן נחשב למאוס בעיני המצרים (בשל פולחן הצאן שלהם)'.",
  "47_1": "יוסף הגיע לפרעה ודיווח לו: 'אבי ואחיי, יחד עם צאנם, בקרם וכל אשר להם, הגיעו מארץ כנען, והנה הם שוהים כעת בארץ גושן'.",
  "47_2": "הוא בחר חמישה מאחיו (שנראו פחות לוחמניים: ראובן, שמעון, לוי, יששכר ובנימין, כדי שפרעה לא יגייסם לצבאו) והציג אותם לפני פרעה.",
  "47_3": "פרעה שאל את אחיו: 'מהו תחום עיסוקכם?', והם ענו לפרעה: 'רועי צאן עבדיך, גם אנחנו וגם אבותינו מאז ומעולם'.",
  "47_4": "הם הוסיפו ואמרו לפרעה: 'באנו רק להתגורר זמנית בארץ, משום שאין מרעה לצאן עבדיך כיוון שהרעב כבד מאוד בארץ כנען; ועכשיו, אנא הרשה לעבדיך להתיישב בחבל גושן'.",
  "47_5": "פרעה אמר ליוסף ברוחב לב:",
  "47_6": "'כל ארץ מצרים פתוחה לרשותך; בחבל הארץ המשובח ביותר הושב את אביך ואת אחיך – שיתיישבו בארץ גושן; ואם אתה מזהה ביניהם אנשי מקצוע מוכשרים ובעלי יכולת – מנה אותם למנהלי עדריי המלכותיים'.",
  "47_7": "יוסף הביא את יעקב אביו והציג אותו בכבוד לפני פרעה, ויעקב בירך את פרעה בשלום.",
  "47_8": "פרעה שאל את יעקב: 'בן כמה שנים אתה?'.",
  "47_9": "יעקב ענה לפרעה: 'ימי שנות מסעותיי ונדודיי עומדים על מאה ושלושים שנה (130 שנה); מעטים ורוויי צער וקשיים היו ימי חיי, ולא הגיעו לאורך שנות חייהם של אבותיי בימי מגוריהם'.",
  "47_10": "יעקב בירך שוב את פרעה (שיעלה הנילוס לקראתו ויפסק הרעב), ויצא מנוכחות פרעה.",
  "47_11": "יוסף יישב את אביו ואת אחיו והעניק להם נחלה ואחוזה במיטב ארץ מצרים, באזור רעמסס (גושן), בדיוק כפי שציווה פרעה.",
  "47_12": "יוסף סיפק וכלכל בלחם ובמזון את אביו, את אחיו ואת כל משפחת אביו, בדיוק לפי צורכי הטף והילדים הקטנים.",
  "47_13": "ומזון לא היה בנמצא בכל האזור כי הרעב היה כבד מנשוא, ותושבי ארץ מצרים וארץ כנען נחלשו והותשו לחלוטין מאימת הרעב.",
  "47_14": "יוסף אסף וגבה את כל הכסף שנמצא בארץ מצרים ובארץ כנען בתמורה לתבואה שקנו ממנו, והביא את כל הכסף ישירות לאוצר ארמון פרעה.",
  "47_15": "כאשר אזל לחלוטין הכסף מארץ מצרים ומארץ כנען, באו כל המצרים אל יוסף והתחננו: 'תן לנו לחם! למה שנמות מול עיניך רק משום שנגמר לנו הכסף?!'.",
  "47_16": "יוסף השיב: 'אם אין לכם כסף – הביאו את בהמותיכם, ואתן לכם מזון תמורת המקנה שלכם'.",
  "47_17": "הם הביאו את מקניהם אל יוסף, ויוסף סיפק להם לחם תמורת סוסים, עדרי צאן, עדרי בקר וחמורים; וכך פרנס אותם בלחם תמורת כל מקניהם במשך אותה שנה.",
  "47_18": "השנה ההיא הסתיימה, ובשנה שלאחריה באו אליו שוב ואמרו: 'לא נסתיר מאדוני כי נגמר הכסף וכל עדרי הבהמות כבר נמסרו לאדוני; לא נותר לפני אדוני דבר מלבד גופנו ואדמותינו'.",
  "47_19": "'מדוע נמות לנגד עיניך, אנו ואדמתנו שתישאר שממה? קנה אותנו ואת אדמותינו תמורת לחם, ואנו ושדותינו נהיה עבדים ונכסים לפרעה; תן לנו זרעים כדי שנחיה ולא נמות, והאדמה לא תהפוך לשממה'.",
  "47_20": "יוסף קנה את כל אדמות מצרים לבעלותו של פרעה, משום שכל מצרי מכר את שדהו מרוב חומרת הרעב, וכך עברו כל הקרקעות לרשות פרעה.",
  "47_21": "ואת האוכלוסייה העביר יוסף לערי מגורים מרוכזות, מקצה אחד של גבול מצרים ועד קצהו השני (כדי לבטל את מעמד הקרקעות הפרטי וכדי שלא יביישו את אחיו כזרים).",
  "47_22": "רק את אדמות כוהני הדת לא קנה, משום שהוקצתה להם קצבת מזון קבועה מפרעה והם חיו מקצבתם, ולכן לא נאלצו למכור את אדמותיהם.",
  "47_23": "יוסף אמר לכל העם: 'הנה קניתי היום אתכם ואת אדמותיכם לפרעה; קחו זרעים וזרעו את השדות'.",
  "47_24": "'וכאשר תאספו את היבולים, תמסרו חמישית (20%) מן התוצרת לאוצר פרעה, וארבעה חלקים (80%) יישארו שלכם – לזריעת השדות, למזונכם, לכל בני בתיכם ולהאכלת ילדיכם'.",
  "47_25": "העם הודה לו בהערצה ואמר: 'הצלת את חיינו! העיקר שנמצא חן וחסד בעיני אדוני, ונהיה עבדים נאמנים לפרעה'.",
  "47_26": "יוסף קבע זאת כחוק קבוע שעומד על תילו עד היום על כל אדמות מצרים: להפריש חמישית מהיבול לפרעה; רק אדמות הכוהנים בלבד לא נמסרו לפרעה.",
  "47_27": "עם ישראל התיישב בארץ מצרים בחבל גושן, רכשו בה אחוזות, והתרבו והתעצמו שם במידה עצומה.",
  "47_28": "יעקב חי בארץ מצרים שבע עשרה שנה, וסך כל שנות חייו של יעקב עמד על מאה ארבעים ושבע שנים (147 שנה).",
  "47_29": "כאשר התקרבו ימי מותו של ישראל, הוא קרא לבנו יוסף ואמר לו: 'אם מצאתי חן בעיניך, אנא שים את ידך תחת ירכי (כשבועה חמורה) ועשה איתי חסד של אמת: אל נא תקבור אותי במצרים'.",
  "47_30": "'ברצוני לשכב לצד אבותיי; לכן הוצא אותי ממצרים וקבור אותי באחוזת הקבר המשפחתית שלהם'; יוסף השיב ביראת כבוד: 'אעשה בדיוק כדבריך'.",
  "47_31": "יעקב ביקש: 'הישבע לי!', ויוסף נשבע לו; וישראל השתחווה לעבר ראש המיטה להודות לה' על שמיטתו שלמה ויוסף צדיק ונאמן.",
  "48_1": "לאחר הדברים הללו, הודיעו ליוסף: 'הנה אביך חולה ותשוש'; יוסף לקח איתו מיד את שני בניו – את מנשה ואת אפרים – ובא לבקרו.",
  "48_2": "הודיעו ליעקב: 'הנה בנך יוסף מגיע אליך'; ישראל אזר את שארית כוחותיו והתיישב זקוף על המיטה לכבודו.",
  "48_3": "יעקב פתח ואמר ליוסף: 'אל שדי נגלה אליי בלוז (בית אל) שבארץ כנען, ובירך אותי בהבטחה נצחית:'",
  "48_4": "'הוא אמר לי: הנני מפרה ומרבה אותך, אהפוך אותך לקהל של עמים רבים, ואתן את הארץ הזאת לצאצאיך אחריך לאחוזת עולם'.",
  "48_5": "'ועכשיו, שני בניך שנולדו לך בארץ מצרים לפני שבאתי אליך – הם נחשבים כבניי שלי ממש! אפרים ומנשה ייחשבו כשבטים נפרדים ועצמאיים בדיוק כמו ראובן ושמעון לקבלת נחלה ודגל'.",
  "48_6": "'וילדים נוספים שיוולדו לך אחריהם ייחשבו שלך, וייכללו בנחלותיהם תחת שמות אחיהם אפרים ומנשה'.",
  "48_7": "'ואני, בשובי מפדן ארם, מתה עליי רחל אמך בארץ כנען לצד הדרך, כשהיה עוד מרחק קצר להגיע לאפרת (בית לחם); קברתי אותה שם לצד דרך אפרת (בנבואה, כדי שתתפלל על בניה בצאתם לגלות)'.",
  "48_8": "ישראל הבחין בבני יוסף ושאל: 'מי אלה?'.",
  "48_9": "יוסף ענה לאביו: 'אלה הם בניי שאלוהים העניק לי כאן במצרים'; יעקב אמר: 'קרב אותם בבקשה אליי ואברך אותם'.",
  "48_10": "ועיני ישראל היו כבדות וכהות מזוקן ולא יכול היה לראות בבירור; יוסף קירב אותם אליו, ויעקב נישק להם וחיבק אותם בחום.",
  "48_11": "ישראל אמר ליוסף בהתרגשות: 'אפילו לראות את פניך שוב לא פיללתי ולא העזתי לקוות, והנה אלוהים זיכה אותי לראות גם את ילדיך!'.",
  "48_12": "יוסף הזיז אותם מעט מברכיו כדי להכינם לברכה, והשתחווה באפיים ארצה בכבוד לאביו.",
  "48_13": "יוסף לקח את שניהם בצורה מסודרת: את אפרים בימינו כנגד יד שמאל של ישראל, ואת מנשה בשמאלו כנגד יד ימין של ישראל (כי מנשה הבכור), וקירב אותם אליו.",
  "48_14": "אך ישראל שלח את יד ימינו והניח אותה על ראש אפרים שהיה הצעיר, ואת יד שמאלו הניח על ראש מנשה; הוא שיכל והצליב את ידיו בכוונה תחילה, אף שמנשה היה הבכור.",
  "48_15": "הוא בירך את יוסף ואת בניו ואמר: 'האלוהים שאבותיי אברהם ויצחק התהלכו לפניו בנאמנות, האלוהים הרועה, המפרנס והמדריך אותי מיום היוולדי ועד היום הזה'.",
  "48_16": "'המלאך שהציל וגאל אותי מכל רע וצרה – יברך את הנערים הללו; ייקרא בהם שמי ושם אבותיי אברהם ויצחק, והם יתרבו ויתעצמו בהמוניהם כדגים בקרב הארץ'.",
  "48_17": "יוסף ראה שאביו מניח את יד ימינו על ראש אפרים והדבר לא מצא חן בעיניו; הוא תמך ביד אביו כדי להסיר אותה מראש אפרים ולהעבירה לראש מנשה.",
  "48_18": "יוסף אמר לאביו: 'לא כך אבי, כי מנשה הוא הבכור; שים נא את יד ימינך על ראשו'.",
  "48_19": "אך אביו סירב בתוקף ואמר: 'ידעתי בני, ידעתי היטב; גם מנשה יהפוך לעם גדול וגם הוא יתעצם, אך אחיו הצעיר יהיה גדול ממנו (שממנו יקום יהושע בן נון שינחיל את הארץ), וזרעו ימלא את האומות'.",
  "48_20": "הוא בירך אותם באותו יום וקבע: 'בך יברך כל איש בישראל את בניו ויאמר: יְשִׂמְךָ אֱלֹהִים כְּאֶפְרַיִם וְכִמְנַשֶּׁה'; וכך הקדים את אפרים לפני מנשה.",
  "48_21": "ישראל אמר ליוסף: 'הנה אני עומד למות, אך אלוהים יהיה איתכם ויחזיר אתכם לארץ אבותיכם'.",
  "48_22": "'ואני מעניק לך נחלת חלק נוספת (שכם) מעבר לאחיך, חלק שכבשתי מיד האמורי בתפילתי ובבקשתי (בחרבי ובקשתי)'.",
  "49_1": "יעקב קרא לכל בניו ואמר: 'התאספו סביבי, ואספר לכם את מה שיקרה אתכם באחרית הימים'.",
  "49_2": "'התקבצו והקשיבו, בני יעקב; שמעו בקול ישראל אביכם:'",
  "49_3": "'ראובן, בכורי אתה – כוחי הראשון וראשית אוני; היית ראוי ליתרון הכהונה והמלכות'.",
  "49_4": "'אך בשל פזיזותך ומהירותך כמו מים שוצפים, הפסדת את היתרון הזה – כי עלית על יצועי אביך וחיללת את כבודי'.",
  "49_5": "'שמעון ולוי הם אחים באופיים ובזעמם; כלי נשק וחמס הם כלי מלחמתם'.",
  "49_6": "'בסוד מזימתם אל תיכנס נפשי, ובקהל אסיפתם אל ישתתף כבודי; כי בזעמם הרגו אנשים ובגחמתם עקרו שוורים'.",
  "49_7": "'ארור כעסם כי הוא עז, וזעמם כי הוא קשה; לכן אפזר אותם ביעקב ואפיץ אותם בישראל (שבט לוי משרת בערי מקלט מפוזרות, ושבט שמעון סופרים ומלמדים מפוזרים)'.",
  "49_8": "'יהודה – אתה הוא שאחיך יודו לך ויקבלו את מנהיגותך; ידך תנצח בעורף אויביך, ובני אביך ישתחוו לך במלכות'.",
  "49_9": "'גור אריה הוא יהודה! מטרף וחשד אחי, יצאת נעלה ונקי; הוא כורע ורובץ בעוצמה כמו אריה וכלביא, ומי יעז להקימו?'.",
  "49_10": "'שרביט המלוכה לא יסור מיהודה, ושופטים ומחוקקים ייצאו מחלציו לעד – עד שיבוא מלך המשיח (שִׁילֹה), ואליו יתקבצו ויישמעו כל העמים'.",
  "49_11": "'נחלתו תהיה כה שופעת בגפנים, עד שיקשור את חמורו לגפן מרוב ריבוי גפנים; הוא יכבס את בגדיו ביין ומרוב ענבים ישטוף את לבושו'.",
  "49_12": "'עיניו יהיו אדומות מרוב מתיקות היין, ושיניו לבנות מרוב שפע של חלב צאן'.",
  "49_13": "'זבולון ישכון לחוף ימים, ישלוט בנמלי אוניות, ונחלתו תגיע עד גבול צידון (יעסוק במסחר ימי ויפרנס את שבט יששכר הלומד תורה)'.",
  "49_14": "'יששכר הוא כחמור חזק גרם, הרובץ בשקדנות בין גבולות המנוחה'.",
  "49_15": "'הוא ראה כי המנוחה והארץ נעימות ללימוד, הרכין את שכמו לשאת בעול התורה והתמסר לה כעובד נאמן'.",
  "49_16": "'דן ישפוט וינהיג את עמו בצדק, כאחד המיוחד שבשבטי ישראל'.",
  "49_17": "'דן יהיה כנחש מסוכן על אם הדרך וכשפיפון על השביל, הנושך עקבי סוס והרוכב נופל לאחוריו (נבואה על שמשון הגיבור שהפיל לבדו אלפי פלשתים)'.",
  "49_18": "'לישועתך קיוויתי ה'!'.",
  "49_19": "'גד יוציא גדודי לוחמים חלוצים, וכל גדודיו יחזרו בשלום באותם עקבות לפתח בתיהם'.",
  "49_20": "'מאשר תהיה ארצו עשירה בשמן זית מובחר ומשובח, והוא יספק מעדנים ראויים לשולחן מלכים'.",
  "49_21": "'נפתלי הוא כאיילה קלה ושלוחה שתבואתה מבשילה במהירות, והוא משמיע דברי תורה ופיוט נאים ויפים'.",
  "49_22": "'ענף פורה וחינני הוא יוסף, בן חן הניצב על מעיין מים; בנות מצרים צעדו על החומות לחזות ביופיו, ואין עין הרע שולטת בו'.",
  "49_23": "'אויביו מיררו את חייו, ירו בו חיצים ונטרו לו שנאה'.",
  "49_24": "'אך קשתו נשארה איתנה וידיו התחזקו וזהרו בזכות כוחו של אביר יעקב, שמשם הועמד להיות רועה ומנהיג אבן ישראל'.",
  "49_25": "'מאלוהי אביך שיעזור לך, ומאת אל שדי שיברך אותך: ברכות גשמי שמיים מלמעלה, ברכות מעיינות תהום מלמטה, וברכות פוריות שדיים ורחם'.",
  "49_26": "'ברכות אביך גברו ועלו על ברכות אבותיי עד קצה גבולות גבעות עולם; כולן יחולו על ראשו של יוסף ועל קודקודו של מי שהיה מובדל ונזר אחיו'.",
  "49_27": "'בנימין הוא כזאב טורף וגיבור: בבוקר יאכל טרף ולעת ערב יחלק שלל (רמז לגבורת שאול המלך, מרדכי ואסתר, ומזבח בית המקדש שבנחלתו)'.",
  "49_28": "כל אלה הם שנים עשר שבטי ישראל השלמים, וזה מה שדיבר אליהם אביהם כאשר בירך אותם – איש איש לפי ברכתו וייעודו המיוחד בירך אותם.",
  "49_29": "הוא ציווה עליהם ואמר: 'אני עומד להיאסף אל אבותיי; קברו אותי לצד אבותיי במערה שבשדה עפרון החיתי'.",
  "49_30": "'במערת שדה המכפלה שמול ממרא בארץ כנען, אותה קנה אברהם יחד עם השדה מעפרון החיתי לאחוזת קבר'.",
  "49_31": "'שם קברו את אברהם ואת שרה אשתו, שם קברו את יצחק ואת רבקה אשתו, ושם קברתי אני את לאה'.",
  "49_32": "'זהו השדה והמערה שבו שנקנו בבירור מאת בני חת'.",
  "49_33": "יעקב סיים לצוות את בניו, אסף את רגליו אל המיטה, גווע בשלווה ונאסף אל עמיו.",
  "50_1": "יוסף נפל על פני אביו, בכה עליו מרה ונישק לו בפרידה.",
  "50_2": "יוסף הורה לרופאיו המלכותיים לחנוט את אביו בבשמים (כדי לשמר את גופו למסע), והרופאים חנטו את ישראל.",
  "50_3": "תהליך החניטה נמשך ארבעים יום כפי הנהוג בחניטה, והמצרים בכו והתאבלו עליו שבעים יום.",
  "50_4": "כאשר הסתיימו ימי האבל הרשמיים, פנה יוסף אל בכירי בית פרעה ואמר: 'אם מצאתי חן בעיניכם, אנא מסרו דברים אלה לפרעה:'",
  "50_5": "'אבי השביע אותי לפני מותו באומרו: הנה אני עומד למות; בקבר שחצבתי והכנתי לי בארץ כנען – שם תקבור אותי; ועכשיו, הרשה לי בבקשה לעלות ולקבור את אבי, ואשוב מיד חזרה'.",
  "50_6": "פרעה אישר והשיב: 'עלה וקבור את אביך בדיוק כפי שהשביע אותך'.",
  "50_7": "יוסף עלה לקבור את אביו, ואיתו עלתה פמליית כבוד ענקית: כל שרי פרעה, זקני ארמונו וכל נכבדי ארץ מצרים.",
  "50_8": "וכן כל בית יוסף, אחיו וכל משפחת אביו; רק את ילדיהם הקטנים, את צאנם ואת בקרם השאירו בארץ גושן.",
  "50_9": "עלו איתו גם מרכבות צבאיות ופרשים, והשיירה הייתה מחנה כבד ומרשים ביותר.",
  "50_10": "הם הגיעו עד גורן האטד שבעבר הירדן, וערכו שם מספד גדול, עצוב ומכובד ביותר; ויוסף עשה לאביו אבל כבד שנמשך שבעה ימים.",
  "50_11": "הכנענים יושבי הארץ ראו את האבל הכבד בגורן האטד ואמרו: 'אבל כבד ועצום הוא זה למצרים!'; לכן נקרא שם המקום 'אָבֵל מִצְרַיִם' שבעבר הירדן.",
  "50_12": "בני יעקב קיימו את צוואתו במדויק כפי שציווה אותם.",
  "50_13": "בניו נשאו אותו לארץ כנען וקברו אותו במערת שדה המכפלה, שקנה אברהם לאחוזת קבר מעפרון החיתי מול ממרא.",
  "50_14": "לאחר שקבר את אביו, שב יוסף למצרים – הוא, אחיו וכל הפמליה שעלתה איתו לקבור את אביו.",
  "50_15": "אחי יוסף ראו שאביהם מת וחששו מאוד; הם אמרו בלשון דאגה: 'שמא יוסף עדיין נוטר לנו שנאה, ועכשיו יגמול לנו על כל הרעה שעוללנו לו?!'.",
  "50_16": "הם שלחו שליחים אל יוסף למסור לו: 'אביך ציווה לפני מותו לאמור:'",
  "50_17": "'כה תאמרו ליוסף: אנא סלח נא לפשע אחיך ולחטאתם על כל הרעה שגמלו לך; ועכשיו אנא סלח לפשע עבדי אלוהי אביך'; ויוסף פרץ בבכי כאשר דיברו אליו כך.",
  "50_18": "אחיו הלכו בעצמם, נפלו לפניו עד הקרקע ואמרו: 'הנה כולנו מוכנים להיות לך לעבדים'.",
  "50_19": "יוסף הרגיע אותם ואמר: 'אל תפחדו כלל! האם במקום אלוהים אני שאשפוט או אעניש אתכם?!'.",
  "50_20": "'אתם אומנם תכננתם עליי רעה – אך אלוהים תכנן וסובב זאת לטובה גדולה, כדי להביא לתוצאה המופלאה של היום הזה: להחיות ולהציל עם רב מרעב'.",
  "50_21": "'ועכשיו אל תחששו כלל! אני אכלכל ואפרנס אתכם ואת כל ילדיכם'; והוא ניחם אותם ודיבר אל לבם בחום ובאהבה.",
  "50_22": "יוסף התגורר במצרים, הוא וכל בית אביו; ויוסף חי מאה ועשר שנים (110 שנה).",
  "50_23": "יוסף זכה לראות לאפרים בנים עד דור שלישי (נינים), וגם בני מכיר בן מנשה גדלו והתחנכו על ברכיו של יוסף.",
  "50_24": "יוסף אמר לאחיו לפני מותו: 'אני עומד למות; אך אלוהים ודאי יזכור ויפקוד אתכם, ויעלה אתכם מן הארץ הזאת אל הארץ שהבטיח בשבועה לאברהם, ליצחק וליעקב'.",
  "50_25": "יוסף השביע את בני ישראל ואמר: 'כאשר יפקוד אלוהים אתכם ויוציא אתכם מכאן – עליכם להעלות את עצמותיי מזה איתכם לארץ ישראל'.",
  "50_26": "יוסף נפטר בהיותו בן מאה ועשר שנים; הם חנטו אותו בבשמים, והניחו אותו בארון מיוחד במצרים עד לגאולה. (חֲזַק חֲזַק וְנִתְחַזֵּק!)"
};
